var e={id:`k1-13-kronik-ve-granulomatoz-enflamasyon`,sira:13,kurul:1,ders:`Tıbbi Patoloji`,konu:`Kronik ve Granülomatöz Enflamasyon`,ogretim_uyesi:`Prof. Dr. Hikmet Keleş`,tarih:`2026-09-18`,soru_sayisi:224,kazanimlar:[{no:1,metin:`Kronik enflamasyonu tanımlamak ve akut enflamasyonla karşılaştırmak`,sorular:[{id:`k1-13-q01`,kazanim:1,zorluk:`kolay`,soru:`Kronik enflamasyonda baskın olan hücre grubu aşağıdakilerden hangisidir?`,secenekler:{A:`Nötrofiller`,B:`Eritrositler`,C:`Makrofaj, lenfosit ve plazma hücreleri (mononükleer hücreler)`,D:`Trombositler`,E:`Bazofiller`},dogru:`C`,aciklama:`Kronik enflamasyonda mononükleer hücreler (makrofaj, lenfosit, plazma hücresi) baskındır; akut enflamasyonda ise nötrofiller ve ödem öndedir.`,sik_aciklamalari:{A:`Nötrofiller akut enflamasyonun tipik hücresidir.`,B:`Eritrositler enflamatuvar hücre değildir.`,C:`Doğru. Mononükleer hücre infiltrasyonu kronik enflamasyonun temel özelliğidir.`,D:`Trombositler hemostazda görev alır.`,E:`Bazofiller alerjik reaksiyonlarla ilişkilidir; kronik enflamasyonun baskın hücresi değildir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-13-q02`,kazanim:1,zorluk:`orta`,soru:`Kronik enflamasyonun tanımı için aşağıdakilerden hangisi en doğrudur?`,secenekler:{A:`Dakikalar-saatler içinde başlayan, nötrofil ve ödem ağırlıklı kendini sınırlayan yanıt`,B:`Hücre içi trigliserid birikimi`,C:`Yalnızca akut enflamasyonu izleyen, her zaman tam iyileşmeyle biten yanıt`,D:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarım girişimlerinin (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,E:`Bir olgun hücre tipinin başka bir olgun tiple yer değiştirmesi`},dogru:`D`,aciklama:`Kronik enflamasyon akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir; enflamasyon, hasar ve onarım birlikte sürer.`,sik_aciklamalari:{A:`Bu akut enflamasyonun tanımıdır.`,B:`Bu steatozdur: hücre içi trigliserid birikimi.`,C:`Kronik enflamasyon primer olarak da başlayabilir ve sıklıkla fibrozisle sonlanır.`,D:`Doğru. Kronik enflamasyon akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir; enflamasyon, hasar ve onarım birlikte sürer.`,E:`Bu metaplazidir: bir olgun hücre tipinin başka bir olgun tiple yer değiştirmesi.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-13-q03`,kazanim:1,zorluk:`zor`,soru:`Akut ve kronik enflamasyonun sonuçlarının karşılaştırılmasında aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Akut enflamasyon genellikle kalıcı organ fonksiyon kaybıyla sonlanır.`,B:`Kronik enflamasyon her zaman tam rezolüsyonla iyileşir.`,C:`Akut enflamasyon genelde tam iyileşme veya basit skarla sonlanırken kronik enflamasyonda kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişebilir.`,D:`İki tablonun sonuçları arasında fark yoktur.`,E:`Kronik enflamasyonda doku onarımı hiç gerçekleşmez.`},dogru:`C`,aciklama:`Kronik enflamasyonda süregen hasar ve onarım girişimleri fibrozis ve organ fonksiyon kaybına yol açabilir.`,sik_aciklamalari:{A:`Akut enflamasyon çoğunlukla tam iyileşir.`,B:`Kronik enflamasyon sıklıkla fibrozisle sonlanır.`,C:`Doğru. Kronik enflamasyonda süregen hasar ve onarım girişimleri fibrozis ve organ fonksiyon kaybına yol açabilir.`,D:`Sonuçlar belirgin şekilde farklıdır.`,E:`Onarım girişimleri (anjiyogenez, fibrozis) kronik enflamasyonun parçasıdır.`},bilgi:[2,3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q04`,kazanim:1,zorluk:`orta`,soru:`27 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Kronik enflamasyonu tanımlamak ve akut enflamasyonla karşılaştırmak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı… ilkesinin tam tersi geçerlidir ve Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Kronik enflamasyonda baskın hücreler olup "Kronik enflamasyonu tanımlamak ve akut enflamasyonla…" ile ilişkisizdir`,C:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt Bu nedenle Akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir`,D:`Bulgular "Kronik enflamasyonu tanımlamak ve akut enflamasyonla karşılaştırmak" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Kronik enflamasyonun tanımı" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt Doğrudan sonucu "Akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,C:`Doğru; Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt…`,D:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Kronik enflamasyonda baskın hücreler" vurgulanıyor ve hekim "Kronik enflamasyonu tanımlamak ve akut enflamasyonla karşılaştırmak" kazanımındaki "Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir hiçbir koşulda gözlenmez ve Kronik enflamasyonun tanımı tek belirleyicidir`,B:`Bu süreçte "Kronik enflamasyonun tanımı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Kronik enflamasyonda baskın hücreler" ayırıcı tanıda gereksizdir`,D:`Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir Çünkü Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,E:`Bu olguda izlem gerekmez; "Kronik enflamasyonu tanımlamak ve akut enflamasyonla karşılaştırmak" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri sonucu "Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`,D:`Doğru; Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir Çünkü Mononükleer hücreler: makrofajlar,…`,E:`Yanlış; ders paketindeki "Kronik enflamasyonun tanımı" bilgisiyle çelişir.`},bilgi:[2,3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q06`,kazanim:1,zorluk:`orta`,soru:`Kronik enflamasyonda baskın hücreler: Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Doku makrofaj havuzu inflamatuvar ve yerleşik popülasyonların karışımıdır`,B:`Makrofajların klasik (M1) aktivasyonunu uyarır`,C:`Sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz (özellikle tüberkülozda)`,D:`Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir`,E:`Treponema pallidum enfeksiyonunda hastalığın üçüncül evresinde görülür`},dogru:`D`,aciklama:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri. Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir. Fizyopatolojik sıra bu yönde ilerlediğinden makrofajlar, lenfositler, plazma hücreleri varlığında Kalıcı doku yıkımı, fibrozis ve organ fonksiyon beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Makrofaj kökeni sürecine ait bir özelliktir ve kronik enflamasyonda baskın hücreler düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Th1 hücreleri sürecine ait bir özelliktir ve kronik enflamasyonda baskın hücreler düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Granülomatöz enflamasyonun tanımı sürecine ait bir özelliktir ve kronik enflamasyonda baskın hücreler düzeneğini tanımlamaz.`,D:`Doğru; Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir çünkü makrofajlar, lenfositler, plazma hücreleri düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Sifilizde granülom (gumma) sürecine ait bir özelliktir ve kronik enflamasyonda baskın hücreler düzeneğini tanımlamaz.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q07`,kazanim:1,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Akut enflamasyonda baskın hücre mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Nötrofiller ve ödem`,B:`Fagositoz`,C:`Akut enflamasyonun tipik hücresidir`,D:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş`,E:`Haftalar-aylar süren`},dogru:`A`,aciklama:`Nötrofiller ve ödem. Genelde tam iyileşme veya basit skar ile sonlanır. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Nötrofiller ve ödem doğrudan Genelde tam iyileşme veya basit skar ile doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Nötrofiller ve ödem. Bu mekanizma genelde tam iyileşme veya basit skar ile sonlanır sonucunu doğurur.`,B:`Yanlış; bu ifade Makrofajların ana fonksiyonları sürecine ait bir özelliktir ve akut enflamasyonda baskın hücre düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Nötrofillerin kronik tablolardaki katılımı sürecine ait bir özelliktir ve akut enflamasyonda baskın hücre düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Yabancı cisim granülomları sürecine ait bir özelliktir ve akut enflamasyonda baskın hücre düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonun tanımı sürecine ait bir özelliktir ve akut enflamasyonda baskın hücre düzeneğini tanımlamaz.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q08`,kazanim:1,zorluk:`orta`,soru:`Akut ve kronik enflamasyonun temel patofizyolojik özellikleri karşılaştırıldığında, aşağıdakilerden hangisi KRONİK ENFLAMASYONUN karakteristik bir özelliğidir?`,secenekler:{A:`Dakikalar veya saatler içinde aniden başlayıp kısa sürede sonlanması`,B:`Aktif enflamasyon, doku yıkımı (hasar) ve iyileşme (onarılma/fibrozis) süreçlerinin eşzamanlı olarak bir arada sürmesi`,C:`Vasküler geçirgenlik artışı sonucu baskın olarak nötrofillerden zengin eksüda toplanması`,D:`Genellikle doku hasarı bırakmadan tam rezolüsyon ile iyileşmesi`,E:`Sadece plazma kompleman proteinleri ve histamin tarafından yönetilmesi`},dogru:`B`,aciklama:`Kronik enflamasyon; haftalar, aylar hatta yıllar süren uzamış bir süreçtir. En belirleyici patolojik niteliği; aktif enflamatuar hücre infiltrasyonunun, doku yıkımının (hasar) ve onarım girişimlerinin (anjiyogenez ve fibrozis/bağ dokusu proliferasyonu) aynı anda ve bir arada (eşzamanlı) devam etmesidir. Akut enflamasyonda ise erken ödem ve nötrofil hakimiyeti vardır ve genellikle rezolüsyonla biter.`,sik_aciklamalari:{A:`Dakikalar/saatler içinde ani başlayıp kısa süren akut enflamasyondur.`,B:`Doğrudur. Enflamasyon, doku hasarı ve onarımın (fibrozis) eşzamanlı bir arada sürmesi kronik enflamasyonun temel tanımıdır.`,C:`Nötrofil ve eksüda akut enflamasyon özelliğidir; kronik enflamasyonda mononükleer hücreler baskındır.`,D:`Kronik enflamasyon hemen her zaman doku distorsiyonu ve skar (fibrozis) bırakır.`,E:`Kronik enflamasyon mononükleer hücreler (makrofaj, lenfosit) ve sitokinlerce yürütülür.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q09`,kazanim:1,zorluk:`zor`,soru:`Bir doku biyopsisinde enflamasyonun evresi değerlendirilirken, aşağıdakilerden hangisinin mikroskopik olarak saptanması sürecin AKUT değil KRONİK bir enflamasyon olduğunu kesin olarak gösterir?`,secenekler:{A:`Postkapiller venüllerde lökosit marginasyonu ve rulositoz`,B:`İnterstisyel alanda yaygın lenfoplazmositer hücre infiltrasyonu, makrofajlar ve fibroblastik kollajen birikimi (fibrozis)`,C:`Endotel hücre aralıklarının açılarak seröz ödem sıvısının birikmesi`,D:`Damar lümeninde yoğun nötrofil lökositlerin görülmesi`,E:`Lokal eritrosit ekstravazasyonu (peteşiyel kanama)`},dogru:`B`,aciklama:`Kronik enflamasyonun histopatolojik triadı: 1) Mononükleer hücre infiltrasyonu (makrofajlar, lenfositler ve plazma hücreleri), 2) Kalıcı enflamatuar hücrelerin veya etkenin uyardığı doku harabiyeti (nekroz/hasar), 3) Hasar gören parankimin yerine granülasyon dokusu, yeni damar oluşumu (anjiyogenez) ve fibroblast proliferasyonu ile kollajen depolanması (fibrozis/skarlaşma) sürecidir.`,sik_aciklamalari:{A:`Lökosit marginasyonu akut vasküler yanıtın erken adımıdır.`,B:`Doğrudur. Lenfosit, plazma hücresi, makrofaj infiltrasyonu ve fibrozis kronik enflamasyonun histopatolojik kanıtıdır.`,C:`Seröz ödem akut vasküler permeabilite artışıdır.`,D:`Nötrofil hakimiyeti akut enflamasyonun damgasıdır.`,E:`Peteşiyel kanama akut vasküler endotel hasarında da görülür.`},bilgi:[1,3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q10`,kazanim:1,zorluk:`orta`,soru:`Akut enflamasyon ile kronik enflamasyonun ana hücresel bileşenleri karşılaştırıldığında, aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Akut enflamasyonda primer hücreler lenfositler iken, kronik enflamasyonda trombositlerdir.`,B:`Akut enflamasyonun baskın hücreleri nötrofillerdir; kronik enflamasyonun baskın hücreleri ise makrofajlar, lenfositler ve plazma hücreleridir.`,C:`Her iki enflamasyon tipinde de tek hücresel eleman bazofillerdir.`,D:`Kronik enflamasyonda monositler tamamen apoptoza gider ve dokuda hiç makrofaj bulunmaz.`,E:`Akut enflamasyonda fibroblast proliferasyonu saatler içinde tüm dokuyu kaplar.`},dogru:`B`,aciklama:`Akut enflamasyonun ilk 6-24 saatinde damar dışına çıkan ana efektör hücreler nötrofillerdir. Süreç devam edip 24-48 saat aşıldığında monosit/makrofajlar hakimiyeti devralır. Kronikleşen tabloda ise dokuda makrofajlar, T ve B lenfositleri ile plazma hücrelerinden oluşan 'mononükleer infiltrat' yerleşir.`,sik_aciklamalari:{A:`Akut hücreler nötrofillerdir, lenfositler değil.`,B:`Doğrudur. Akut enflamasyon nötrofil, kronik enflamasyon ise mononükleer hücre (makrofaj, lenfosit, plazma hücresi) hakimiyetiyle karakterizedir.`,C:`Bazofiller primer veya tek hücre değildir.`,D:`Makrofajlar kronik enflamasyonun merkezi hücresidir.`,E:`Fibroblast proliferasyonu ve skar kronik enflamasyon ve onarımın özelliğidir, ilk saatlerde dokuyu kaplamaz.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q11`,kazanim:1,zorluk:`orta`,soru:`Aşağıdaki klinik tablolardan hangisi akut enflamasyonun tam rezolüsyona UĞRAYAMAYIP kronik enflamasyona ilerlemesine (progresyonuna) klasik bir örnektir?`,secenekler:{A:`Deri sıyrığı sonrası 3 günde kabuklanıp iz bırakmadan iyileşen yüzeysel erozyon`,B:`Çözülemeyen akut bakteriyel lobar pnömoninin akciğer absesine ve organize kronik fibroza dönüşmesi`,C:`Güneş yanığı sonrası 48 saatte kızarıklığın kendiliğinden solması`,D:`Sivrisinek ısırığı yerindeki histaminik kabarıklığın 2 saatte kaybolması`,E:`Hafif alerjik rinit atağının antihistaminikle dakikalar içinde düzelmesi`},dogru:`B`,aciklama:`Akut enflamasyonun üç olası sonlanımı vardır: 1) Tam rezolüsyon (dokunun normale dönmesi), 2) Doku yıkımıyla skarlaşma/apseleşme, 3) Kronik enflamasyona ilerleme. Akut lober pnömonide bakteri temizlenemez, nekroz gelişir veya eksüda drene edilemezse abseleşme, fibroblastik organizasyon ve kronik süpüratif/fibrotik akciğer hasarı meydana gelir.`,sik_aciklamalari:{A:`Tam rezolüsyon örneğidir, kronikleşme değildir.`,B:`Doğrudur. Akut pnömoninin temizlenemeyip akciğer absesine ve kronik organizasyona ilerlemesi klasik kronikleşme örneğidir.`,C:`Rezolüsyonla iyileşen akut yanıttır.`,D:`Geçici akut histaminik vazodilatasyondur.`,E:`Hızlı rezolüsyondur.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q12`,kazanim:1,zorluk:`zor`,soru:`Kronik enflamasyonun akut enflamasyondan farklı olarak sinsi ve subklinik (asemptomatik) başlayabilmesinin patofizyolojik temeli aşağıdakilerden hangisidir?`,secenekler:{A:`Hastanın bağışıklık sisteminin hiçbir antikor üretememesi`,B:`Etkenin (örneğin Mycobacterium tuberculosis, lipid birikimi veya otoantijenler) düşük virülansta fakat kalıcı olması, akut vasküler eksüdasyon oluşturmadan doğrudan gecikmiş hücresel immün yanıtı tetiklemesi`,C:`Kanda kompleman C3 proteininin tamamen eksik olması`,D:`Nötrofillerin fagositoz yeteneğinin aşırı artarak mikrobu 1 saniyede yok etmesi`,E:`Tüm periferik sinirlerin kalıcı olarak felç olması`},dogru:`B`,aciklama:`Kronik enflamasyon her zaman gürültülü bir akut enflamasyon atağını takiben gelişmek zorunda değildir. Birçok durumda (tüberküloz enfeksiyonu, aterosklerozda intimal kolesterol birikimi, romatoid artrit gibi otoimmün hastalıklar) etken başlangıçta şiddetli vasküler geçirgenlik veya nötrofilik fırtına yapmaz; sessizce dokuda birikir ve doğrudan CD4+ T lenfosit-makrofaj eksenini uyararak sinsi, subklinik ve progresif doku hasarına yol açar.`,sik_aciklamalari:{A:`Kronik enflamasyonda antikorlar ve lenfositler son derece aktiftir.`,B:`Doğrudur. Kalıcı, temizlenemeyen etkenler akut vasküler fırtına yapmadan doğrudan sinsi kronik hücresel yanıtı başlatabilir.`,C:`Kompleman eksikliği kural değildir.`,D:`Nötrofiller etkensiz kalırsa veya etkeni yok edemezse kronikleşir.`,E:`Sinir felci söz konusu değildir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q13`,kazanim:1,zorluk:`kolay`,soru:`Aşağıdakilerden "Klasik (M1) makrofaj aktivasyonu" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,A:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`IFN-γ üretir`,E:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,C:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`},dogru:`B`,aciklama:`Doğru: Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,sik_aciklamalari:{B:`Doğru. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,A:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`Yanlış. IFN-γ üretir`,E:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,C:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q14`,kazanim:1,zorluk:`orta`,soru:`"M1 ve M2 dengesi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,B:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,A:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`},dogru:`D`,aciklama:`Doğru: Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,sik_aciklamalari:{D:`Doğru. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`Yanlış. IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,E:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,B:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,A:`Yanlış. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q15`,kazanim:1,zorluk:`orta`,soru:`"Kronik enflamasyonun üç histolojik özelliği" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,C:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,D:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`Nötrofiller ve ödem`,B:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`},dogru:`A`,aciklama:`Doğru: Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,sik_aciklamalari:{A:`Doğru. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,C:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,D:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`Yanlış. Nötrofiller ve ödem`,B:`Yanlış. Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k01-q16`,kazanim:1,zorluk:`zor`,soru:`"Yabancı cisim granülomları" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,B:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},dogru:`C`,aciklama:`Doğru: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,sik_aciklamalari:{C:`Doğru. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,E:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,B:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,D:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},bilgi:[29],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`Kronik enflamasyonun başlıca nedenlerini sıralamak`,sorular:[{id:`k1-13-q04`,kazanim:2,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi kronik enflamasyonun başlıca nedenlerinden biri değildir?`,secenekler:{A:`Mycobacterium tuberculosis gibi kalıcı enfeksiyonlar`,B:`Otoimmün hastalıklar`,C:`Silika ve asbest gibi toksik maddelere uzun süreli maruziyet`,D:`Kısa süreli, tamamen temizlenen bakteriyel enfeksiyon`,E:`Endojen lipid birikimi (ateroskleroz)`},dogru:`D`,aciklama:`Kronik enflamasyonun nedenleri kalıcı enfeksiyonlar, aşırı duyarlılık hastalıkları ve uzun süreli toksik maruziyettir.`,sik_aciklamalari:{A:`Nedendir; tüberkülozda granülomatöz enflamasyon gelişir.`,B:`Nedendir; otoantijenlere süregen yanıt vardır.`,C:`Nedendir; silikozis ve asbest ilişkili akciğer hastalığı örnektir.`,D:`Neden değildir (aranan cevap); etken temizlenince enflamasyon akut kalır ve iyileşir.`,E:`Nedendir; arter duvarında kronik enflamasyon olur.`},bilgi:[5,6,7],benzer_cikmis:[]},{id:`k1-13-q05`,kazanim:2,zorluk:`orta`,soru:`Uzun süre taş ocağında çalışan bir hastada gelişen akciğer fibrozisi hangi kronik enflamasyon nedenine örnektir?`,secenekler:{A:`Kalıcı viral enfeksiyon`,B:`Alerjik reaksiyon`,C:`Otoimmün hastalık`,D:`Eksojen toksik madde (silika) maruziyeti`,E:`Endojen lipid birikimi`},dogru:`D`,aciklama:`Silika gibi eksojen toksik maddeler uzun süreli maruziyette kronik enflamasyon ve fibrozise (silikozis) yol açar.`,sik_aciklamalari:{A:`Viral enfeksiyon bu tablonun nedeni değildir.`,B:`Alerji zararsız antijenlere aşırı yanıttır.`,C:`Otoimmünite otoantijenlere yanıttır.`,D:`Doğru. Silika gibi eksojen toksik maddeler uzun süreli maruziyette kronik enflamasyon ve fibrozise (silikozis) yol açar.`,E:`Endojen lipid birikimi aterosklerozun nedenidir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-q06`,kazanim:2,zorluk:`zor`,soru:`Kronik enflamasyon nedenleri ile örnekleri arasındaki eşleştirmelerden hangisi yanlıştır?`,secenekler:{A:`Kalıcı enfeksiyon – kronik viral hepatitin siroza ilerlemesi`,B:`Aşırı duyarlılık hastalığı – tekrarlayan ataklarla karışık akut ve kronik enflamasyon`,C:`Eksojen toksik madde – asbeste bağlı akciğer fibrozisi ve mezotelyoma`,D:`Kalıcı enfeksiyon – silikozis`,E:`Endojen toksik madde – kolesterol/lipid birikimiyle ateroskleroz`},dogru:`D`,aciklama:`Silikozis eksojen toksik madde (silika) maruziyetine bağlıdır; enfeksiyöz değildir.`,sik_aciklamalari:{A:`Doğru eşleştirme: kalıcı enfeksiyon – kronik viral hepatitin siroza ilerlemesi.`,B:`Doğru eşleştirme; geç evrede fibrozis baskınlaşır.`,C:`Doğru eşleştirme: eksojen toksik madde – asbeste bağlı akciğer fibrozisi ve mezotelyoma.`,D:`Yanlış eşleştirme (aranan cevap). Silikozis eksojen toksik madde (silika) maruziyetine bağlıdır; enfeksiyöz değildir.`,E:`Doğru eşleştirme: endojen toksik madde – kolesterol/lipid birikimiyle ateroskleroz.`},bilgi:[5,6,7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q04`,kazanim:2,zorluk:`orta`,soru:`34 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Kronik enflamasyonun başlıca nedenlerini sıralamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan… ilkesinin tam tersi geçerlidir ve Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Uzun süreli toksik maruziyet olup "Kronik enflamasyonun başlıca nedenlerini sıralamak" ile ilişkisizdir`,C:`Bulgular "Kronik enflamasyonun başlıca nedenlerini sıralamak" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar Bu nedenle Tüberkülozda granülomatöz enflamasyon ve fibrozis; kronik viral hepatitte siroza gidiş`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Kalıcı enfeksiyonlar" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar Doğrudan sonucu "Tüberkülozda granülomatöz enflamasyon ve fibrozis; kronik viral hepatitte siroza gidiş" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,D:`Doğru; Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen…`,E:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Uzun süreli toksik maruziyet" vurgulanıyor ve hekim "Kronik enflamasyonun başlıca nedenlerini sıralamak" kazanımındaki "Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir hiçbir koşulda gözlenmez ve Kalıcı enfeksiyonlar tek belirleyicidir`,B:`Bu süreçte "Kalıcı enfeksiyonlar" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Uzun süreli toksik maruziyet" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "Kronik enflamasyonun başlıca nedenlerini sıralamak" yalnızca teorik bir bilgidir`,E:`Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir Çünkü Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi…`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz) sonucu "Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kalıcı enfeksiyonlar" bilgisiyle çelişir.`,E:`Doğru; Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir Çünkü Eksojen silika (silikozis),…`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q06`,kazanim:2,zorluk:`orta`,soru:`Uzun süreli toksik maruziyet: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma). Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Doku onarımı ve fibrozis (anjiyogenez, fibroblast aktivasyonu, kollajen sentezi) ile`,B:`Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir`,C:`Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür`,D:`Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardit gelişebilir`,E:`Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir`},dogru:`E`,aciklama:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma). Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve doğrudan Akciğerde kronik hastalık veya arter duvarında kronik doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Alternatif (M2) makrofaj aktivasyonu sürecine ait bir özelliktir ve uzun süreli toksik maruziyet düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Lenfosit-makrofaj döngüsü sürecine ait bir özelliktir ve uzun süreli toksik maruziyet düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Non-kazeöz granülom sürecine ait bir özelliktir ve uzun süreli toksik maruziyet düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Kronik enflamasyon ve fibrozis sürecine ait bir özelliktir ve uzun süreli toksik maruziyet düzeneğini tanımlamaz.`,E:`Doğru; Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir çünkü Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma) düzeneği bu sonucu üretir.`},bilgi:[7],benzer_cikmis:[`feefe19e69b1`]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Aşırı duyarlılık (immün) hastalıkları mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Eozinofil aktivasyonu yapar`,B:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt`,C:`Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı`,D:`Bartonella henselae (gram-negatif basil)`,E:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile`},dogru:`B`,aciklama:`Tıbbi Patoloji düzeneğinde Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız bilinir. Tekrarlayan ataklar, karışık akut+kronik enflamasyon ve geç evrede fibrozis baskınlığı. Mekanizma bu sırayla işlediği için beklenen sonuç Tekrarlayan ataklar, karışık akut+kronik enflamasyon ve geç olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Th2 hücreleri sürecine ait bir özelliktir ve aşırı duyarlılık (immün) hastalıkları düzeneğini tanımlamaz.`,B:`Doğru; Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik). Bu mekanizma tekrarlayan ataklar, karışık akut+kronik enflamasyon ve geç evrede sonucunu doğurur.`,C:`Yanlış; bu ifade Granülom morfolojisi sürecine ait bir özelliktir ve aşırı duyarlılık (immün) hastalıkları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Kedi tırmığı hastalığında granülom sürecine ait bir özelliktir ve aşırı duyarlılık (immün) hastalıkları düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonun üç histolojik özelliği sürecine ait bir özelliktir ve aşırı duyarlılık (immün) hastalıkları düzeneğini tanımlamaz.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q08`,kazanim:2,zorluk:`orta`,soru:`Aşağıdakilerden hangisi kronik enflamasyonun etiyolojik nedenleri arasında yer alan 'Dirençli (persistan) mikrobiyal enfeksiyonlara' klasik bir örnektir?`,secenekler:{A:`Mycobacterium tuberculosis enfeksiyonu`,B:`Staphylococcus aureus'a bağlı basit yüzeyel folikülit`,C:`Streptococcus pneumoniae'ya bağlı tipik akut krupöz pnömoni`,D:`Rhinovirus kaynaklı akut nezle`,E:`Vibrio cholerae kaynaklı akut sulu ishal`},dogru:`A`,aciklama:`Dirençli (persistan) enfeksiyonlar; mikroorganizmanın fagositoza, lizozomal sindirime veya humoral yanıta direnç gösterdiği durumlardır. Mycobacterium tuberculosis (lipidden zengin hücre duvarı ile fagozom-lizozom füzyonunu engeller), Treponema pallidum (sifiliz) ve bazı mantar/parazitler vücutta aylarca/yıllarca kalarak gecikmiş tip aşırı duyarlık ve granülomatöz kronik enflamasyona yol açarlar.`,sik_aciklamalari:{A:`Doğrudur. M. tuberculosis persistan intrasellüler enfeksiyon ve kronik granülomatöz enflamasyon prototipidir.`,B:`Basit folikülit akut piyojenik bir enfeksiyondur.`,C:`Lobar pnömoni klasik akut eksüdatif enfeksiyondur.`,D:`Rhinovirus kendini sınırlayan akut viral tablodur.`,E:`Kolera toksin aracılı akut sekresyondur, kronik infiltrasyon yapmaz.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q09`,kazanim:2,zorluk:`zor`,soru:`Kronik enflamasyonun nedenleri incelendiğinde, organizmanın kendi öz antijenlerine karşı immün toleransın bozulması sonucu gelişen ve sürekli antijenik uyarı nedeniyle kendi kendini besleyen (self-perpetuating) doku yıkımı tablosu aşağıdakilerden hangisidir?`,secenekler:{A:`İmmün aracılı enflamatuar hastalıklar (Otoimmün hastalıklar — örn. Romatoid Artrit, SLE)`,B:`Toksik yabancı cisim reaksiyonu (Silikozis)`,C:`Akut faz proteini eksikliği sendromu`,D:`Paraziter lizis sendromu`,E:`İzole endotelyal atoni`},dogru:`A`,aciklama:`İmmün aracılı hastalıklar (otoimmün hastalıklar ve alerjik bozukluklar), kronik enflamasyonun en önemli nedenlerindendir. Vücut kendi antijenlerini yabancı algılayarak sürekli T ve B lenfosit yanıtı verir. Kendi antijenleri ortamdan uzaklaştırılamadığı için immün yanıt durdurulamaz; kendi kendini besleyen (self-perpetuating), geri dönüşümsüz eklem ve organ hasarına (örn. Romatoid Artrit'te pannus oluşumu ve ankiloz) yol açan kronik enflamasyon gelişir.`,sik_aciklamalari:{A:`Doğrudur. Otoimmün hastalıklarda temizlenemeyen endojen antijenler kronik, kendi kendini besleyen enflamasyona neden olur.`,B:`Silikozis ekzojen inorganik partiküllere bağlıdır, otoimmünite değildir.`,C:`Akut faz eksikliği otoimmün kronik hasar mekanizması değildir.`,D:`Paraziter lizis akut/paraziter bir süreçtir.`,E:`Endotelyal atoni vasküler bir terimdir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q10`,kazanim:2,zorluk:`orta`,soru:`Potansiyel olarak toksik olan endojen veya ekzojen maddelere UZUN SÜRELİ MARUZİYET sonucu gelişen kronik enflamasyon tabloları ile ilgili aşağıdaki eşleştirmelerden hangisi DOĞRUDUR?`,secenekler:{A:`Endojen toksik madde: Solunan silika partikülleri — Pnömokonyoz`,B:`Ekzojen toksik madde: Dolaşımdaki okside LDL kolesterol — Ateroskleroz`,C:`Ekzojen toksik madde: Solunan asbest lifleri — Asbestozis ve plevral fibrozis`,D:`Endojen toksik madde: Cerrahi ipek sütür reaksiyonu`,E:`Ekzojen toksik madde: Karaciğerde biriken serbest bakır (Wilson)`},dogru:`C`,aciklama:`Toksik maddelere uzun süreli maruziyet ikiye ayrılır: 1) Ekzojen maddeler: Solunan silika partikülleri (silikozis), asbest lifleri (asbestozis), cerrahi sütür iplikleri, dövme pigmentleri. 2) Endojen maddeler: Arter duvarında biriken toksik lipidler/okside LDL (ateroskleroz), eklemlerde biriken ürat kristalleri (gut). Asbest lifleri dışarıdan solunan ekzojen bir ajandır.`,sik_aciklamalari:{A:`Silika partikülleri endojen değil ekzojendir.`,B:`Okside LDL vücudun kendi ürettiği endojen bir maddedir.`,C:`Doğrudur. Asbest ekzojen toksik bir maddedir; solunması kronik interstisyel fibrozis ve asbestozis yapar.`,D:`Cerrahi sütür ekzojendir.`,E:`Bakır birikimi endojen metabolik defekttir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q11`,kazanim:2,zorluk:`orta`,soru:`Aşağıdaki hastalıklardan hangisi kronik enflamasyonun etiyolojisinde 'Tekrarlayan akut enflamasyon ataklarının kümülatif hasarı' zemininde gelişen bir tablodur?`,secenekler:{A:`Tekrarlayan akut piyelonefrit atakları sonucu gelişen Kronik Piyelonefrit ve renal parankim skarlaşması`,B:`Asemptomatik basit böbrek kisti`,C:`Akut büllöz pemfigoid atağı`,D:`Primer herediter hiperkolesterolemi`,E:`Doğuştan atriyal septal defekt`},dogru:`A`,aciklama:`Kronik enflamasyon bazen tekrarlayan akut enflamasyon ataklarının birikimiyle ortaya çıkar. Bunun en tipik klinik örneği tekrarlayan akut bakteriyel piyelonefrit (özellikle vezikoüreteral reflü veya obstrüksiyon zemininde) ataklarıdır. Her atak kalikste ve parankimde doku nekrozuna, ardından kollajen birikimine yol açarak böbreğin büzüşmesine (kronik atrofik piyelonefrit) ve böbrek yetmezliğine neden olur.`,sik_aciklamalari:{A:`Doğrudur. Tekrarlayan akut piyelonefrit atakları kronik piyelonefrit ve asimetrik parankim skarlarına ilerler.`,B:`Basit kist edinsel kavitary anomalidir, enflamatuar değildir.`,C:`Büllöz pemfigoid otoantikor aracılı subepidermal büllöz dermatozdur.`,D:`Hiperkolesterolemi genetik reseptör defektidir.`,E:`ASD konjenital kardiyak şanttır.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q12`,kazanim:2,zorluk:`zor`,soru:`Alzheimer hastalığı, Tip 2 Diabetes Mellitus ve bazı metabolik sendrom tablolarında gözlenen düşük dereceli (low-grade) subklinik kronik enflamasyonun tetikleyicisi aşağıdakilerden hangisidir?`,secenekler:{A:`Beyinde beta-amiloid protein agregatlarının ve adipositlerde serbest yağ asitlerinin inflamazom (NLRP3) ve makrofajları kronik olarak uyarması`,B:`Streptococcus pyogenes'in beyin dokusunda üremesi`,C:`Plazmada aşırı eritropoietin üretilmesi`,D:`Karaciğerde safra asitlerinin tamamen tükenmesi`,E:`Tüm mast hücrelerinin genetik olarak yok olması`},dogru:`A`,aciklama:`Günümüzde non-klasik kronik enflamatuar hastalıklar kavramı tanımlanmıştır: Alzheimer hastalığında yanlış katlanmış beta-amiloid plakları mikrogliaları uyarır; Tip 2 diyabette aşırı yağ asitleri ve doymuş lipidler adiposit kaynaklı makrofajlarda NLRP3 inflamazomunu aktive eder. Düşük dereceli kronik enflamasyon (meta-enflamasyon) IL-1β salınımı ile doku hasarına ve insülin direncine öncülük eder.`,sik_aciklamalari:{A:`Doğrudur. Beta-amiloid ve serbest yağ asitleri gibi endojen metabolitler NLRP3/makrofaj uyarısıyla 'low-grade' kronik enflamasyon yapar.`,B:`Alzheimer bakteriyel enfeksiyon değildir.`,C:`Eritropoietin fazlalığı primer neden değildir.`,D:`Safra asidi tükenmesi mekanizma değildir.`,E:`Mast yokluğu enflamasyon yapmaz.`},bilgi:[2,14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q13`,kazanim:2,zorluk:`kolay`,soru:`"Th17 hücreleri" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{C:`IL-17 ve diğer sitokinleri salgılar`,D:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,B:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,A:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,E:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`},dogru:`C`,aciklama:`Doğru: IL-17 ve diğer sitokinleri salgılar`,sik_aciklamalari:{C:`Doğru. IL-17 ve diğer sitokinleri salgılar`,D:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,B:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,A:`Yanlış. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,E:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`},bilgi:[19],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q14`,kazanim:2,zorluk:`orta`,soru:`"Kazeöz (kazeifiye) granülom" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,A:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,C:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},dogru:`B`,aciklama:`Doğru: Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,sik_aciklamalari:{B:`Doğru. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,A:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Yanlış. Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,D:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,C:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q15`,kazanim:2,zorluk:`orta`,soru:`"Uzun süreli toksik maruziyet" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,C:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`},dogru:`B`,aciklama:`Doğru: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,sik_aciklamalari:{B:`Doğru. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,C:`Yanlış. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k02-q16`,kazanim:2,zorluk:`zor`,soru:`"Nötrofillerin kronik tablolardaki katılımı" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,C:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},dogru:`A`,aciklama:`Doğru: Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,sik_aciklamalari:{A:`Doğru. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,E:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Yanlış. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,C:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Yanlış. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},bilgi:[22],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:3,metin:`Kronik enflamasyonun morfolojik özelliklerini açıklamak`,sorular:[{id:`k1-13-q07`,kazanim:3,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi kronik enflamasyonun histolojik özelliklerinden biri değildir?`,secenekler:{A:`Mononükleer hücre infiltrasyonu`,B:`Parankim tahribi`,C:`Bağ dokusuyla yer değiştirme (fibrozis)`,D:`Yalnızca nötrofil ve ödemden oluşan eksüda`,E:`Anjiyogenez`},dogru:`D`,aciklama:`Kronik enflamasyonun üç temel özelliği mononükleer hücre birikimi, doku yıkımı ve onarım girişimleridir (anjiyogenez, fibrozis).`,sik_aciklamalari:{A:`Özelliğidir: mononükleer hücre infiltrasyonu.`,B:`Özelliğidir; kalıcı etken doku yıkımına yol açar.`,C:`Özelliğidir: bağ dokusuyla yer değiştirme (fibrozis).`,D:`Özelliği değildir (aranan cevap); bu akut enflamasyonun bulgusudur.`,E:`Özelliğidir; onarım girişiminin parçasıdır.`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-13-q08`,kazanim:3,zorluk:`orta`,soru:`Kronik enflamasyonlu bir akciğer örneğinde normal alveollerin yerini kübik epitelle döşeli boşlukların alması ve aralarında bağ dokusu artışı izleniyor.

Bu görünüm kronik enflamasyonun hangi özelliklerini yansıtır?`,secenekler:{A:`Yalnızca akut eksüdasyon`,B:`Metastatik kalsifikasyon`,C:`Hücresel şişme`,D:`Parankim tahribi ve fibrozis ile yer değiştirme`,E:`Hücre içi glikojen birikimi`},dogru:`D`,aciklama:`Kronik enflamasyonda parankim tahrip olur ve bağ dokusu ile yer değiştirir; alveollerin yerini kübik epitelli boşluklar alır.`,sik_aciklamalari:{A:`Eksüdasyon akut enflamasyonun özelliğidir.`,B:`Metastatik kalsifikasyon hiperkalsemiyle ilişkilidir.`,C:`Hücresel şişme geri dönüşümlü hasar bulgusudur.`,D:`Doğru. Kronik enflamasyonda parankim tahrip olur ve bağ dokusu ile yer değiştirir; alveollerin yerini kübik epitelli boşluklar alır.`,E:`Glikojen birikimi bu tabloyla ilgili değildir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-q09`,kazanim:3,zorluk:`zor`,soru:`Kronik enflamasyonda doku yıkımı ile onarımın eş zamanlı sürmesinin morfolojik sonucu aşağıdakilerden hangisidir?`,secenekler:{A:`Anjiyogenez, fibrozis ve yara izi oluşumu`,B:`Doku mimarisinin hiç değişmeden korunması`,C:`Saf hücre hipertrofisi`,D:`Yalnızca seröz eksüda`,E:`Likefaksiyon nekrozuyla dokunun tamamen erimesi`},dogru:`A`,aciklama:`Kalıcı etken doku yıkımına, iyileşme girişimleri ise anjiyogenez, fibrozis ve skar oluşumuna yol açar.`,sik_aciklamalari:{A:`Doğru. Kalıcı etken doku yıkımına, iyileşme girişimleri ise anjiyogenez, fibrozis ve skar oluşumuna yol açar.`,B:`Kronik enflamasyonda mimari bozulur.`,C:`Hipertrofi bir adaptasyondur.`,D:`Seröz eksüda akut enflamasyonun kalıbıdır.`,E:`Likefaksiyon püy oluşturan enfeksiyonlar ve beyin infarktında görülür.`},bilgi:[8,34],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q04`,kazanim:3,zorluk:`orta`,soru:`41 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Kronik enflamasyonun morfolojik özelliklerini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis) ilkesinin tam tersi geçerlidir ve Anjiyogenez, fibrozis ve yara izi oluşumu izlenir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Kronik enflamasyonun morfolojik özellikleri olup "Kronik enflamasyonun morfolojik özelliklerini açıklamak" ile ilişkisizdir`,C:`Bulgular "Kronik enflamasyonun morfolojik özelliklerini açıklamak" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Kronik enflamasyonun üç histolojik özelliği" ile açıklanamaz`,E:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis) Bu nedenle Akciğer örneğinde normal alveollerin kübik epitelli boşluklarla yer değiştirmesi olarak izlenir`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis) Doğrudan sonucu "Akciğer örneğinde normal alveollerin kübik epitelli boşluklarla yer değiştirmesi olarak izlenir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,E:`Doğru; Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis) Bu nedenle…`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "Kronik enflamasyonun morfolojik özellikleri" vurgulanıyor ve hekim "Kronik enflamasyonun morfolojik özelliklerini açıklamak" kazanımındaki "Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Anjiyogenez, fibrozis ve yara izi oluşumu izlenir Çünkü Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Anjiyogenez, fibrozis ve yara izi oluşumu izlenir hiçbir koşulda gözlenmez ve Kronik enflamasyonun üç histolojik özelliği tek belirleyicidir`,C:`Bu süreçte "Kronik enflamasyonun üç histolojik özelliği" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Kronik enflamasyonun morfolojik özellikleri" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Kronik enflamasyonun morfolojik özelliklerini açıklamak" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri sonucu "Anjiyogenez, fibrozis ve yara izi oluşumu izlenir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Anjiyogenez, fibrozis ve yara izi oluşumu izlenir Çünkü Mononükleer hücre infiltrasyonu, kalıcı etkenin neden…`,B:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kronik enflamasyonun üç histolojik özelliği" bilgisiyle çelişir.`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Kronik enflamasyonun morfolojik özellikleri: Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Anjiyogenez, fibrozis ve yara izi oluşumu izlenir`,B:`B hücreleri ve plazma hücreleri antikor üretir`,C:`Hem akut hem kronik enflamasyon süreçlerine katılır`,D:`Granülom vücut için izolasyon stratejisidir`,E:`Genelde tam iyileşme veya basit skar ile sonlanır`},dogru:`A`,aciklama:`Tıbbi Patoloji düzeneğinde Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu bilinir. Anjiyogenez, fibrozis ve yara izi oluşumu izlenir. Mekanizma bu sırayla işlediği için beklenen sonuç Anjiyogenez, fibrozis ve yara izi oluşumu izlenir olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Anjiyogenez, fibrozis ve yara izi oluşumu izlenir çünkü Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Lenfositlerin rolü sürecine ait bir özelliktir ve kronik enflamasyonun morfolojik özellikleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Mast hücreleri sürecine ait bir özelliktir ve kronik enflamasyonun morfolojik özellikleri düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade T hücre aracılı granülomatöz yanıt sürecine ait bir özelliktir ve kronik enflamasyonun morfolojik özellikleri düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Akut enflamasyonda baskın hücre sürecine ait bir özelliktir ve kronik enflamasyonun morfolojik özellikleri düzeneğini tanımlamaz.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Kronik enflamasyonun üç histolojik özelliği mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar`,B:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı`,C:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile`,D:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük`,E:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve`},dogru:`C`,aciklama:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis). Akciğer örneğinde normal alveollerin kübik epitelli boşluklarla yer değiştirmesi olarak izlenir. Fizyopatolojik sıra bu yönde ilerlediğinden Kronik inflamatuvar hücre birikimi, parankim tahribi ve varlığında Akciğer örneğinde normal alveollerin kübik epitelli boşluklarla beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Eozinofiller sürecine ait bir özelliktir ve kronik enflamasyonun üç histolojik özelliği düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Granülomatöz enflamasyonun nedenleri sürecine ait bir özelliktir ve kronik enflamasyonun üç histolojik özelliği düzeneğini tanımlamaz.`,C:`Doğru; Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis). Bu mekanizma akciğer örneğinde normal alveollerin kübik epitelli boşluklarla yer sonucunu doğurur.`,D:`Yanlış; bu ifade Non-klasik hastalıklar sürecine ait bir özelliktir ve kronik enflamasyonun üç histolojik özelliği düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonun morfolojik özellikleri sürecine ait bir özelliktir ve kronik enflamasyonun üç histolojik özelliği düzeneğini tanımlamaz.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q08`,kazanim:3,zorluk:`orta`,soru:`Kronik enflamasyonun histopatolojik incelemesinde izlenen 'Mononükleer Hücre İnfiltrasyonu'nu oluşturan hücre grubu aşağıdakilerden hangisinde EKSİKSİZ verilmiştir?`,secenekler:{A:`Nötrofiller, eritrositler ve trombositler`,B:`Makrofajlar, lenfositler ve plazma hücreleri`,C:`Sadece eozinofiller ve nötrofiller`,D:`Megakaryositler ve retikülositler`,E:`Osteoklastlar ve kondrositler`},dogru:`B`,aciklama:`Kronik enflamasyonun morfolojik temel taşı 'mononükleer lökosit infiltrasyonu'dur. Bu infiltrat; fagositoz ve sitokin salgısından sorumlu Makrofajlar, antijene özgü immün yanıtı yöneten Lenfositler (T ve B hücreleri) ve antikor üreten Plazma hücrelerinin birleşiminden oluşur.`,sik_aciklamalari:{A:`Nötrofiller ve trombositler akut vasküler/hemostatik hücrelerdir.`,B:`Doğrudur. Makrofajlar, lenfositler ve plazma hücreleri mononükleer infiltratın temel bileşenleridir.`,C:`Nötrofil akut hücredir.`,D:`Megakaryosit ve retikülosit hematopoetik prekürsörlerdir.`,E:`Kemik/kıkırdak hücreleridir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q09`,kazanim:3,zorluk:`zor`,soru:`Kronik enflamasyonda doku hasarını takiben gelişen onarım sürecinde rol oynayan 'Anjiyogenez' ve 'Fibrozis' morfolojik olayları ile ilgili aşağıdaki ifadelerden hangisi YANLIŞTIR?`,secenekler:{A:`Anjiyogenez, mevcut damarlardan tomurcuklanarak yeni endotelyal kapiller tüplerin gelişmesidir; VEGF ve bFGF ile uyarılır.`,B:`Fibroblastlar aktive olarak Tip I ve Tip III kollajen sentezler; doku mimarisini restore etmeye çalışırken fibröz skar dokusu oluştururlar.`,C:`Yeni oluşan kapiller damarlar endotel kavşakları tam olgunlaşmadığı için aşırı geçirgendir ve granülasyon dokusunun ödemli görünmesine yol açar.`,D:`Kronik enflamasyondaki fibrozis süreci sadece nötrofillerin fagositoz yapmasıyla tetiklenir; makrofajların hiçbir rolü yoktur.`,E:`Fibrozis ilerledikçe parankim hücrelerinin yerini fibröz bağ dokusu alır ve organ disfonksiyonu (organ yetmezliği) gelişir.`},dogru:`D`,aciklama:`Kronik enflamasyondaki fibrozisin ana yöneticisi alternatif aktive (M2) makrofajlardır. M2 makrofajlar TGF-β, PDGF ve FGF gibi profibrotik büyüme faktörleri salgılayarak fibroblastları uyarır ve kollajen sentezini yönetir. Nötrofiller ise primer olarak akut fagositoz ve litik hasardan sorumludur; fibrozisi başlatan veya yöneten hücreler değillerdir.`,sik_aciklamalari:{A:`Doğrudur. VEGF ve FGF anjiyogenezin temel büyüme faktörleridir.`,B:`Doğrudur. Aktive fibroblastlar kollajen üreterek skar oluşturur.`,C:`Doğrudur. Yeni kapillerler 'sızıntılıdır' (leaky), bu yüzden taze granülasyon dokusu ödemlidir.`,D:`Doğrudur (yanlış önermedir). Fibrozisin orkestra şefi nötrofiller değil, profibrotik sitokinler (TGF-β) salgılayan M2 makrofajlardır.`,E:`Doğrudur. Parankimin yerini fibröz dokunun alması kronik organ yetmezliğinin (siroz, KBY vb.) temelidir.`},bilgi:[3,5,14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q10`,kazanim:3,zorluk:`orta`,soru:`Romatoid artritli bir hastanın proliferatif sinovyal biyopsisinde lenfositlerin organize olarak lenf nodu benzeri germinal merkezler içeren yapılar oluşturduğu izlenmektedir. 
Kronik enflamasyon alanlarında gelişen bu ektopik lenfoid doku oluşumuna ne ad verilir?`,secenekler:{A:`Tersiyer Lenfoid Yapılar (Tersiyer Lenfoid Organogenez)`,B:`Kazeifikasyon nekrozu`,C:`Pyojenik granülom`,D:`Distrofik kalsifikasyon odağı`,E:`Fibrinoid vaskülit`},dogru:`A`,aciklama:`Şiddetli ve uzamış kronik enflamasyonda (örneğin Romatoid Artrit sinovyası, Hashimoto tiroiditi veya H. pylori gastritinde MALT), antijenik uyarı lenfositlerin enflamasyon dokusunda organize olmasına yol açar. T ve B hücre alanları, foliküler dendritik hücreler ve hatta germinal merkezler içeren sekonder lenf nodlarına benzer yapılar gelişir. Bu fenomene 'Tersiyer Lenfoid Yapılar' veya 'Lenfoid Neogenez' adı verilir.`,sik_aciklamalari:{A:`Doğrudur. Kronik enflamasyon dokusunda oluşan lenfoid folikül benzeri kümelere Tersiyer Lenfoid Yapılar denir.`,B:`Kazeifikasyon peynirimsi asellüler nekrozdur.`,C:`Pyojenik granülom hemanjiyom benzeri vasküler proliferasyondur.`,D:`Distrofik kalsifikasyon nekrotik alana kalsiyum çökmesidir.`,E:`Fibrinoid vaskülit damar duvarında immün kompleks birikimidir.`},bilgi:[3,6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q11`,kazanim:3,zorluk:`orta`,soru:`Kronik peptik ülser zemininde gelişen histopatolojik tabakalanmada tabandan yüzeye doğru incelendiğinde, aşağıdakilerden hangisi kronik doku hasarı ve onarımının tipik morfolojik yansımasıdır?`,secenekler:{A:`Tabanda derin kollajenöz fibröz skar dokusu, üzerinde anjiyogenezden zengin granülasyon dokusu ve en yüzeyde nekrotik fibrinöz debris`,B:`Sadece sağlam skuamöz epitel ve sıfır enflamatuar hücre`,C:`Yaygın hyalin kıkırdak metaplazisi`,D:`Tamamen kalsifiye olmuş osteoid kemik dokusu`,E:`Sadece mast hücrelerinden oluşan saf tümöral kitle`},dogru:`A`,aciklama:`Kronik peptik ülser kronik enflamasyon ve onarımın bir arada oluşunun klasik patolojik modelidir. Dört karakteristik tabaka izlenir: 1) En yüzeyde nekrotik fibrinöz lökositik eksüda, 2) Akut enflamatuar infiltrat tabakası, 3) Yeni damarlar ve fibroblastlardan oluşan taze granülasyon dokusu, 4) Tabanda ve submukozada derin, yoğun kollajenöz fibröz skar tabakası.`,sik_aciklamalari:{A:`Doğrudur. Fibröz skar, granülasyon dokusu ve nekrotik döküntü kronik peptik ülserin morfolojik triadıdır.`,B:`Ülser defekttir, sağlam epitel tabakası kaybıyla tanımlanır.`,C:`Midede kıkırdak metaplazisi ülserin tipik bulgusu değildir.`,D:`Kemik dokusu oluşmaz.`,E:`Mast hücresi tümörü (mastositoz) değildir.`},bilgi:[1,3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q12`,kazanim:3,zorluk:`zor`,soru:`Kronik enflamasyonda aktive makrofajların ve lenfositlerin salgıladığı metalloproteinazlar (MMP'ler) ve serin proteazların dokudaki kontrolsüz aktivitesi hangi morfolojik sonuca yol açar?`,secenekler:{A:`Ekstrasellüler matriks ve bazal membranın parçalanması ile kalıcı doku harabiyeti (doku destrüksiyonu)`,B:`Eritrositlerin hücre zarlarının aşırı kalınlaşması`,C:`Yeni kromozom duplikasyonları`,D:`Tüm lenfatik damarların kalıcı kapanması`,E:`Böbrek tübüllerinin saf kemik dokusuna dönüşmesi`},dogru:`A`,aciklama:`Aktive makrofajlar ve nötrofiller dokuya Matriks Metalloproteinazlar (MMP-1, MMP-9, MMP-12 vb.), elastaz ve katepsinler salgılarlar. Kronik süreçte bu proteolitik enzimler ekstrasellüler matriks proteinlerini (kollajen, elastin, fibronektin) ve bazal membranları sindirerek parankimal doku harabiyetine (destrüksiyon) ve kavitasyonlara (örn. tüberküloz kavernleri veya amfizemdeki alveol duvar yıkımı) yol açarlar.`,sik_aciklamalari:{A:`Doğrudur. MMP'ler matriks ve bazal membranı yıkarak doku hasarını ve destrüksiyonu derinleştirir.`,B:`Eritrosit zarı kalınlaşması yapmaz.`,C:`Proteazlar kromozom replikasyonu yapmaz.`,D:`Lenfatik kapanma primer mekanizma değildir.`,E:`Tübüller kemiğe dönüşmez.`},bilgi:[3,4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q13`,kazanim:3,zorluk:`kolay`,soru:`Aşağıdakilerden "Th17 hücreleri" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`IL-17 ve diğer sitokinleri salgılar`,A:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,D:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,B:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`},dogru:`C`,aciklama:`Doğru: IL-17 ve diğer sitokinleri salgılar`,sik_aciklamalari:{C:`Doğru. IL-17 ve diğer sitokinleri salgılar`,A:`Yanlış. Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,E:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,D:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,B:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`},bilgi:[19],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q14`,kazanim:3,zorluk:`orta`,soru:`"T hücre aracılı granülomatöz yanıt" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,B:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Eozinofil aktivasyonu yapar`,E:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},dogru:`A`,aciklama:`Doğru: Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,sik_aciklamalari:{A:`Doğru. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,B:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Yanlış. Eozinofil aktivasyonu yapar`,E:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},bilgi:[30],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q15`,kazanim:3,zorluk:`orta`,soru:`"Non-kazeöz granülom" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Merkezi nekroz yoktur`,E:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,A:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,C:`Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,D:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`},dogru:`B`,aciklama:`Doğru: Merkezi nekroz yoktur`,sik_aciklamalari:{B:`Doğru. Merkezi nekroz yoktur`,E:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,A:`Yanlış. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,C:`Yanlış. Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,D:`Yanlış. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`},bilgi:[27],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k03-q16`,kazanim:3,zorluk:`zor`,soru:`"Akut enflamasyonda baskın hücre" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{D:`Nötrofiller ve ödem`,C:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,B:`IFN-γ üretir`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},dogru:`D`,aciklama:`Doğru: Nötrofiller ve ödem`,sik_aciklamalari:{D:`Doğru. Nötrofiller ve ödem`,C:`Yanlış. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,B:`Yanlış. IFN-γ üretir`,E:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Yanlış. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},bilgi:[2],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Makrofajların kronik enflamasyondaki merkezi rolünü, kökenini ve dağılımını açıklamak`,sorular:[{id:`k1-13-q10`,kazanim:4,zorluk:`kolay`,soru:`Karaciğerde yerleşik makrofajlara ne ad verilir?`,secenekler:{A:`Mikroglia`,B:`Alveoler makrofaj`,C:`Kupffer hücresi`,D:`Langerhans hücresi`,E:`Sinüs histiyositi`},dogru:`C`,aciklama:`Yerleşik makrofajlar organa göre farklı adlandırılır: karaciğerde Kupffer hücreleri, beyinde mikroglia, akciğerde alveoler makrofaj, dalak/lenf düğümünde sinüs histiyositleri.`,sik_aciklamalari:{A:`Mikroglia beyindeki makrofajlardır.`,B:`Alveoler makrofajlar akciğerdedir.`,C:`Doğru. Yerleşik makrofajlar organa göre farklı adlandırılır: karaciğerde Kupffer hücreleri, beyinde mikroglia, akciğerde alveoler makrofaj, dalak/lenf düğümünde sinüs histiyositleri.`,D:`Langerhans hücresi deride antijen sunan dendritik hücredir.`,E:`Sinüs histiyositleri dalak ve lenf düğümündedir.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-q11`,kazanim:4,zorluk:`orta`,soru:`Makrofajların kronik enflamasyondaki işlevleri arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Mikrop ve nekrotik doku fagositozu`,B:`TNF, IL-1 ve kemokin salgısı`,C:`TGF-β, PDGF ve FGF ile onarım ve fibrozisin uyarılması`,D:`T lenfositlerine antijen sunumu`,E:`Antikor üretimi`},dogru:`E`,aciklama:`Makrofajlar fagositoz, mediyatör salgısı, onarım-fibrozis ve antijen sunumu yapar; antikorları plazma hücreleri üretir.`,sik_aciklamalari:{A:`Makrofaj işlevidir: mikrop ve nekrotik doku fagositozu.`,B:`Makrofaj işlevidir: TNF, IL-1 ve kemokin salgısı.`,C:`Makrofaj işlevidir: TGF-β, PDGF ve FGF ile onarım ve fibrozisin uyarılması.`,D:`Makrofaj işlevidir; ko-uyarıcı sinyal de sağlar.`,E:`Yer almaz (aranan cevap); antikoru plazma hücreleri üretir.`},bilgi:[15,16],benzer_cikmis:[`d3-f-240`]},{id:`k1-13-q12`,kazanim:4,zorluk:`zor`,soru:`Makrofajların kökeni ile ilgili aşağıdaki ifadelerden hangisi doğrudur?`,secenekler:{A:`İnflamatuvar yanıttaki makrofajların çoğu kemik iliği öncüllerinden (kan monositi) türer; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer) köken alır.`,B:`Tüm doku makrofajları yalnızca embriyonik vitellus kesesinden türer.`,C:`Makrofajlar lenfositlerin farklılaşmasıyla oluşur.`,D:`Makrofajlar fibroblastlardan türer.`,E:`Doku makrofajları yalnızca dalakta üretilir.`},dogru:`A`,aciklama:`Doku makrofaj havuzu, dolaşımdaki monositlerden gelen inflamatuvar makrofajlar ile embriyonik kökenli yerleşik makrofajların karışımıdır.`,sik_aciklamalari:{A:`Doğru. Doku makrofaj havuzu, dolaşımdaki monositlerden gelen inflamatuvar makrofajlar ile embriyonik kökenli yerleşik makrofajların karışımıdır.`,B:`İnflamasyondaki makrofajların çoğu kan monositinden gelir.`,C:`Makrofajlar miyeloid seriden (monosit) gelir.`,D:`Fibroblastlar mezenkimal hücrelerdir; makrofaj kaynağı değildir.`,E:`Makrofajlar tüm dokularda bulunur.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q04`,kazanim:4,zorluk:`orta`,soru:`48 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Makrofajların kronik enflamasyondaki merkezi rolünü, kökenini ve dağılımını açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır Bu nedenle Mikrop ve nekrotik doku fagositozu, sitokin ve büyüme faktörü salgısı, diğer hücrelerin aktivasyonu ve onarımın…`,B:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır ilkesinin tam tersi geçerlidir ve T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Makrofajların ana fonksiyonları olup "Makrofajların kronik enflamasyondaki merkezi rolünü,…" ile ilişkisizdir`,D:`Bulgular "Makrofajların kronik enflamasyondaki merkezi rolünü, kökenini ve…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Makrofajın merkezi rolü" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır Doğrudan sonucu "Mikrop ve nekrotik doku fagositozu, sitokin ve büyüme faktörü salgısı, diğer hücrelerin aktivasyonu ve onarımın başlatılması" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır Bu nedenle Mikrop ve nekrotik doku fagositozu,…`,B:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`},bilgi:[9,10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q05`,kazanim:4,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Makrofajların ana fonksiyonları" vurgulanıyor ve hekim "Makrofajların kronik enflamasyondaki merkezi rolünü, kökenini ve dağılımını açıklamak" kazanımındaki "Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır hiçbir koşulda gözlenmez ve Makrofajın merkezi rolü tek belirleyicidir`,B:`T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır Çünkü Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis…`,C:`Bu süreçte "Makrofajın merkezi rolü" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Makrofajların ana fonksiyonları" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Makrofajların kronik enflamasyondaki merkezi rolünü, kökenini ve…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu sonucu "T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,B:`Doğru; T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır Çünkü Fagositoz; inflamasyon mediyatörleri…`,C:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Makrofajın merkezi rolü" bilgisiyle çelişir.`},bilgi:[11,15],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q06`,kazanim:4,zorluk:`orta`,soru:`Makrofajların ana fonksiyonları: Fagositoz. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Nötrofil alımı ve aktivasyonu artar`,B:`T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır`,C:`Tipik örneği tüberkülozdur`,D:`Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir`,E:`Tüberkülozda granülomatöz enflamasyon ve fibrozis`},dogru:`B`,aciklama:`Fagositoz. T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır. Fizyopatolojik sıra bu yönde ilerlediğinden Fagositoz varlığında T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Th17 hücreleri sürecine ait bir özelliktir ve makrofajların ana fonksiyonları düzeneğini tanımlamaz.`,B:`Doğru; T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır çünkü Fagositoz düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade Kazeöz (kazeifiye) granülom sürecine ait bir özelliktir ve makrofajların ana fonksiyonları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Granülomların klinik önemi ve tanısı sürecine ait bir özelliktir ve makrofajların ana fonksiyonları düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kalıcı enfeksiyonlar sürecine ait bir özelliktir ve makrofajların ana fonksiyonları düzeneğini tanımlamaz.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Yerleşik makrofaj isimleri mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kronik enflamasyonun özel bir tipi`,B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları`,C:`makrofajlar, lenfositler, plazma hücreleri`,D:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde`,E:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi)`},dogru:`D`,aciklama:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar. Tümü mononükleer fagosit sisteminin parçasıdır. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, doğrudan Tümü mononükleer fagosit sisteminin parçasıdır doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Granülomatöz enflamasyonun tanımı sürecine ait bir özelliktir ve yerleşik makrofaj isimleri düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Sifilizde granülom (gumma) sürecine ait bir özelliktir ve yerleşik makrofaj isimleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Kronik enflamasyonda baskın hücreler sürecine ait bir özelliktir ve yerleşik makrofaj isimleri düzeneğini tanımlamaz.`,D:`Doğru; Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar. Bu mekanizma tümü mononükleer fagosit sisteminin parçasıdır sonucunu doğurur.`,E:`Yanlış; bu ifade Makrofaj kökeni sürecine ait bir özelliktir ve yerleşik makrofaj isimleri düzeneğini tanımlamaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q08`,kazanim:4,zorluk:`orta`,soru:`Fizyolojik şartlarda çeşitli dokularda yerleşik olarak bulunan 'Doku Makrofajları' (Mononükleer Fagosit Sistemi) ile ilgili aşağıdaki anatomik lokalizasyon ve isim eşleştirmelerinden hangisi YANLIŞTIR?`,secenekler:{A:`Karaciğer — Kupffer hücreleri`,B:`Santral Sinir Sistemi — Mikroglia`,C:`Akciğer alveolleri — Alveoler makrofajlar (toz hücreleri)`,D:`Kemik dokusu — Osteoklastlar`,E:`Deri epidermisi — Podositler`},dogru:`E`,aciklama:`Mononükleer fagosit sistemi (retiküloendotelyal sistem): Karaciğerde Kupffer hücreleri, santral sinir sisteminde Mikroglia, akciğerde Alveoler makrofajlar, kemikte Osteoklastlar, dalak ve lenf nodlarında sinüs histiyositleri, deride ise 'Langerhans hücreleri' veya dermal dendritik hücreler/makrofajlardır. Podositler deride değil, böbrek glomerülünün Bowman kapsülü viseral yaprağında yer alan epitel hücreleridir.`,sik_aciklamalari:{A:`Karaciğer sinüzoid makrofajları Kupffer hücreleridir.`,B:`SSS'nin yerleşik makrofajları mikrogliadır.`,C:`Akciğer makrofajları alveoler makrofajlardır.`,D:`Osteoklastlar kemik rezorpsiyonu yapan multinükleer makrofaj kökenli hücrelerdir.`,E:`Doğrudur. Podosit böbrek glomerül hücresidir; derideki dendritik/makrofajik hücre Langerhans hücresidir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q09`,kazanim:4,zorluk:`zor`,soru:`Doku makrofajlarının embriyolojik ve erişkin kökenleri modern immünoloji verileri ışığında incelendiğinde, aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Vücuttaki tüm doku makrofajları istisnasız sadece erişkin kemik iliğindeki monositlerden köken alır ve ömürleri 24 saattir.`,B:`Beyin mikrogliyası, karaciğer Kupffer hücreleri ve alveoler makrofajların çoğu erken embriyonik dönemde yolk kesesi (vitellüs kesesi) veya fetal karaciğerden köken alıp dokuda kendi kendine çoğalarak ömür boyu yerleşik kalır; akut/kronik enflamasyonda ise dokuya kandan kemik iliği kökenli monositler göç eder.`,C:`Makrofajlar sadece B lenfositlerin farklılaşmasıyla oluşur.`,D:`Monositler dolaşımda ortalama 10 yıl kaldıktan sonra dokuya geçer.`,E:`Doku makrofajları mitoz bölünme yeteneğine hiçbir zaman sahip olamaz.`},dogru:`B`,aciklama:`Yerleşik doku makrofajlarının (özellikle mikroglia, Kupffer hücreleri ve Langerhans hücreleri) büyük bir kısmı embriyogenez sırasında yolk kesesi veya fetal karaciğerdeki hematopoetik öncüllerden dokulara göç eder ve lokal proliferasyonla homeostazı korurlar. Buna karşın enflamatuar durumlarda dokuya kandan çekilen makrofajlar, erişkin kemik iliğinde üretilen ve dolaşımda 1 gün kalan 'kan monositleri'nden köken alır.`,sik_aciklamalari:{A:`Tüm makrofajlar kemik iliğinden gelmez; çoğu fetal yolk kesesi kökenlidir.`,B:`Doğrudur. Dokuda yerleşikler yolk kesesi/fetal karaciğer kökenliyken, enflamasyonda kandan gelenler kemik iliği monositleridir.`,C:`Makrofajlar miyeloid seridir, lenfoid (B hücresi) seri değildir.`,D:`Monositlerin dolaşımdaki yarı ömrü yaklaşık 1 gündür (10 yıl değil).`,E:`Bazı doku makrofajları lokal mitozla kendini yenileyebilir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q10`,kazanim:4,zorluk:`orta`,soru:`Akut enflamasyonda nötrofillerin ömrü 1-2 gün iken, kronik enflamasyon alanındaki doku makrofajlarının aylarca hatta yıllarca ortamda kalarak birikmesini sağlayan mekanizmalar arasında aşağıdakilerden hangisi YER ALMAZ?`,secenekler:{A:`Dolaşımdaki kandan monositlerin kemokinler (örn. MCP-1) aracılığıyla dokuya sürekli göç etmesi`,B:`Lokal dokuda yerleşik makrofajların sitokinlerin (örn. M-CSF, GM-CSF) etkisiyle mitoz geçirerek çoğalması`,C:`İnterferon-gama ve doku faktörlerinin etkisiyle makrofajların apoptozunun geciktirilmesi ve göçlerinin kısıtlanması (immobilizasyon)`,D:`Makrofajların fagositoz yaptıkça doğrudan nötrofile dönüşerek kana geri dönmesi`,E:`Kalıcı antijenik uyarının mononükleer hücre göçünü sürekli tetiklemesi`},dogru:`D`,aciklama:`Kronik enflamasyon alanında makrofaj birikimi: 1) Kandan sürekli monosit alımı, 2) Lokal makrofaj proliferasyonu, 3) Makrofajların apoptozdan korunması ve dokuda hapsedilmesi (immobilizasyonu) ile sağlanır. Makrofajlar asla nötrofile 'dönüşemez'; bunlar farklı gelişim basamaklarına ve sonlanımlara sahip bağımsız miyeloid hücrelerdir.`,sik_aciklamalari:{A:`Monositlerin sürekli damar dışına çekilmesi temel birikim yoludur.`,B:`M-CSF uyarısıyla dokuda mitozla çoğalabilirler.`,C:`Makrofajların dokuda hapsolması ve yaşam süresinin uzaması kronikleşmeyi sağlar.`,D:`Doğrudur. Makrofaj nötrofile dönüşemez; bu biyolojik olarak imkansızdır.`,E:`Sürekli antijenik uyarı göçü açık tutar.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q11`,kazanim:4,zorluk:`zor`,soru:`Makrofajların kronik enflamasyonda 'antijen sunan hücre' (APC) olarak CD4+ T lenfositleri aktive edebilmesi için hücre zarında eksprese ettiği zorunlu moleküler yapılar hangisidir?`,secenekler:{A:`MHC Sınıf II molekülleri ve kostimülatör moleküller (CD80 / CD86 / B7)`,B:`Sadece eritrosit ABO yüzey antijenleri`,C:`P-selektin glikoprotein ligandı-1 (PSGL-1)`,D:`Faktör VIII ve von Willebrand kompleksi`,E:`Perforin ve granzim B vezikülleri`},dogru:`A`,aciklama:`Profesyonel bir antijen sunan hücre (APC) olan makrofaj, fagositozla aldığı protein antijenleri peptitlere parçalar ve bunları hücre yüzeyindeki 'MHC Sınıf II' molekülleri üzerinde CD4+ T hücre reseptörüne (TCR) sunar. T hücresinin tam aktivasyonu için ikinci sinyal olan kostimülatör B7 (CD80 ve CD86) molekülleri de makrofaj yüzeyinde bulunur ve T hücresindeki CD28'e bağlanır.`,sik_aciklamalari:{A:`Doğrudur. CD4+ T hücrelerine antijen sunumu MHC Sınıf II ve B7-1/B7-2 (CD80/86) kostimülatörleri ile gerçekleşir.`,B:`ABO antijenleri eritrosit kan gruplarıdır.`,C:`PSGL-1 endotelde yuvarlanma ligandıdır.`,D:`Faktör VIII pıhtılaşma proteinidir.`,E:`Perforin/granzim sitotoksik T ve NK hücrelerine aittir.`},bilgi:[4,6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q12`,kazanim:4,zorluk:`orta`,soru:`Aktive makrofajların kronik enflamasyondaki biyolojik etkileri incelendiğinde, bu hücrelerin 'iki ucu keskin kılıç' olarak tanımlanmasının temel nedeni nedir?`,secenekler:{A:`Sadece parazitleri öldürürken virüslere hiç dokunmamaları`,B:`Bir yandan mikropları temizleyip doku onarımını başlatırken; diğer yandan kontrolsüz aktive olduklarında salgıladıkları serbest radikaller, proteazlar ve sitokinlerle konak dokusunda ağır destrüksiyon ve fibrozis oluşturmaları`,C:`Hücre zarlarının kristalize olup çevre dokuyu kesmesi`,D:`Kanda pıhtılaşmayı aynı anda hem başlatıp hem durdurması`,E:`Vücuttaki tüm lenfositleri fagositozla yok etmeleri`},dogru:`B`,aciklama:`Makrofajlar konak savunmasında vazgeçilmez koruyuculardır: Mikropları öldürür, hücresel debrisi temizler ve büyüme faktörleriyle tamiri uyarırlar. Ancak kronik enflamasyonda sürekli ve aşırı aktive kaldıklarında salgıladıkları ROS, NO, proteazlar (MMP'ler), TNF ve profibrotik faktörlerle çevre sağlam parankimi tahrip eder ve geri dönüşümsüz fibrozise yol açarlar ('iki ucu keskin kılıç').`,sik_aciklamalari:{A:`Makrofajlar hem bakteri, hem parazit, hem virüs yanıtında rol alır.`,B:`Doğrudur. Hem mikrobu temizleyen koruyucu hem de dokuyu tahrip eden patolojik hücre olmaları nedeniyle bu benzetme yapılır.`,C:`Zarları fiziksel olarak kesici kristal değildir.`,D:`Pıhtılaşma regülasyonu primer tanımlayıcı neden değildir.`,E:`Normal lenfositleri körlemesine yok etmezler.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q13`,kazanim:4,zorluk:`kolay`,soru:`"Nötrofillerin kronik tablolardaki katılımı" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,C:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,A:`IFN-γ üretir`,E:`IL-17 ve diğer sitokinleri salgılar`,B:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`},dogru:`D`,aciklama:`Doğru: Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,sik_aciklamalari:{D:`Doğru. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,C:`Yanlış. Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,A:`Yanlış. IFN-γ üretir`,E:`Yanlış. IL-17 ve diğer sitokinleri salgılar`,B:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`},bilgi:[22],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q14`,kazanim:4,zorluk:`orta`,soru:`"Kronik enflamasyonda baskın hücreler" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,E:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,B:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,D:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`},dogru:`A`,aciklama:`Doğru: Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,sik_aciklamalari:{A:`Doğru. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,E:`Yanlış. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,B:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,D:`Yanlış. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`},bilgi:[3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q15`,kazanim:4,zorluk:`orta`,soru:`"Yabancı cisim granülomları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,A:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,B:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,E:`IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,D:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`},dogru:`C`,aciklama:`Doğru: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,sik_aciklamalari:{C:`Doğru. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,A:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,B:`Yanlış. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,E:`Yanlış. IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,D:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k04-q16`,kazanim:4,zorluk:`zor`,soru:`"Non-kazeöz granülom" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Merkezi nekroz yoktur`,B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,D:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`},dogru:`E`,aciklama:`Doğru: Merkezi nekroz yoktur`,sik_aciklamalari:{E:`Doğru. Merkezi nekroz yoktur`,B:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,D:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`},bilgi:[27],benzer_cikmis:[]}],ilgili_cikmis:[{id:`d3-f-240`,soru:`Antikora bağlı (hümoral) immünitede antikor salgılayan hücre aşağıdakilerden hangisidir?`,secenekler:{A:`T lenfosit`,B:`Plazma hücresi`,C:`Makrofaj`,D:`Nötrofil granülosit`,E:`Doğal katil (NK) hücre`},cevap:`B`}]},{no:5,metin:`Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt etmek`,sorular:[{id:`k1-13-q13`,kazanim:5,zorluk:`kolay`,soru:`Makrofajların klasik (M1) aktivasyonunu indükleyen T hücre kaynaklı sitokin aşağıdakilerden hangisidir?`,secenekler:{A:`IL-4`,B:`IL-13`,C:`IL-10`,D:`IFN-γ`,E:`TGF-β`},dogru:`D`,aciklama:`Klasik aktivasyon mikrobiyal ürünler (LPS, TLR ligandları) ve IFN-γ ile; alternatif aktivasyon IL-4 ve IL-13 ile indüklenir.`,sik_aciklamalari:{A:`IL-4 alternatif (M2) aktivasyonu indükler.`,B:`IL-13 alternatif (M2) aktivasyonu indükler.`,C:`IL-10 M2 makrofajların salgıladığı anti-enflamatuvar sitokindir.`,D:`Doğru. Klasik aktivasyon mikrobiyal ürünler (LPS, TLR ligandları) ve IFN-γ ile; alternatif aktivasyon IL-4 ve IL-13 ile indüklenir.`,E:`TGF-β M2 makrofaj ürünüdür; fibrozisi uyarır.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-13-q14`,kazanim:5,zorluk:`orta`,soru:`Alternatif (M2) aktive makrofajların başlıca işlevi aşağıdakilerden hangisidir?`,secenekler:{A:`ROS ve NO üretimiyle mikropları öldürmek`,B:`IL-12 salgılayarak Th1 yanıtını güçlendirmek`,C:`IL-10 ve TGF-β ile enflamasyonu baskılamak, anjiyogenez ve kollajen sentezini uyararak onarım ve fibrozisi sağlamak`,D:`Antikor üretmek`,E:`Histamin salgılamak`},dogru:`C`,aciklama:`M2 makrofajların mikrobisidal aktivitesi sınırlıdır; onarım ve fibrozis ile enflamasyonun baskılanmasında rol oynar.`,sik_aciklamalari:{A:`Mikrop öldürme klasik (M1) aktivasyonun özelliğidir.`,B:`IL-12 salgısı M1 makrofajlara özgüdür.`,C:`Doğru. M2 makrofajların mikrobisidal aktivitesi sınırlıdır; onarım ve fibrozis ile enflamasyonun baskılanmasında rol oynar.`,D:`Antikor üretimi plazma hücrelerine aittir.`,E:`Histamin mast hücrelerinden salınır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-q15`,kazanim:5,zorluk:`zor`,soru:`M1 ve M2 makrofaj aktivasyonu ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`M1 aktivasyonunda lizozomal enzimler, ROS ve NO artar.`,B:`M1 makrofajlar IL-1, TNF, IL-12 ve IL-6 salgılar.`,C:`M2 aktivasyonu IL-4 ve IL-13 ile indüklenir.`,D:`Teorik olarak erken yanıt M1, sonraki dönem M2 ağırlıklıdır; pratikte ara formlar sıktır.`,E:`M2 makrofajlar güçlü mikrobisidal aktivite göstererek enflamasyonu sürdürür.`},dogru:`E`,aciklama:`M2 makrofajların mikrobisidal aktivitesi sınırlıdır; enflamasyonu baskılar ve onarımı sağlar. Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar.`,sik_aciklamalari:{A:`Doğru ifade: M1 aktivasyonunda lizozomal enzimler, ROS ve NO artar.`,B:`Doğru ifade: M1 makrofajlar IL-1, TNF, IL-12 ve IL-6 salgılar.`,C:`Doğru ifade: M2 aktivasyonu IL-4 ve IL-13 ile indüklenir.`,D:`Doğru ifade: teorik olarak erken yanıt M1, sonraki dönem M2 ağırlıklıdır; pratikte ara formlar sıktır.`,E:`Yanlış ifade (aranan cevap); bu M1 makrofajların özelliğidir.`},bilgi:[12,13,14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q04`,kazanim:5,zorluk:`orta`,soru:`55 yaşındaki bir hasta yıllardır süren yakınmalarla başvuran ve fizik muayenede tipik bulguları saptanan bir hastada hekime başvuruyor. Değerlendirmede "Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt etmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal… ilkesinin tam tersi geçerlidir ve Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar gözlenmez`,B:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler… Bu nedenle Mikropların öldürülmesi ve enflamasyonun sürdürülmesi sağlanır`,C:`Bu tablodan sorumlu temel mekanizma M1 ve M2 dengesi olup "Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt…" ile ilişkisizdir`,D:`Bulgular "Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt etmek" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Klasik (M1) makrofaj aktivasyonu" ile açıklanamaz`},dogru:`B`,aciklama:`Robbins/Harrison mantığıyla: Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar Doğrudan sonucu "Mikropların öldürülmesi ve enflamasyonun sürdürülmesi sağlanır" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,B:`Doğru; Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS,…`,C:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Farklı bir hasta tedavi seçeneğinin tartışıldığı farklı bir klinik senaryoda ele alınıyor. Öyküde "M1 ve M2 dengesi" vurgulanıyor ve hekim "Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt etmek" kazanımındaki "Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar hiçbir koşulda gözlenmez ve Klasik (M1) makrofaj aktivasyonu tek belirleyicidir`,B:`Bu süreçte "Klasik (M1) makrofaj aktivasyonu" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar Çünkü Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "M1 ve M2 dengesi" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Klasik (M1) ve alternatif (M2) makrofaj aktivasyonunu ayırt etmek" yalnızca teorik bir bilgidir`},dogru:`C`,aciklama:`Guyton/Robbins bütünlüğünde: Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır sonucu "Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,C:`Doğru; Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar Çünkü Teorik olarak erken yanıt M1…`,D:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Klasik (M1) makrofaj aktivasyonu" bilgisiyle çelişir.`},bilgi:[13,14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q06`,kazanim:5,zorluk:`orta`,soru:`M1 ve M2 dengesi: Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Osteomiyelit ve sigara ilişkili akciğer hastalıklarında süregen nötrofil görülür`,B:`Dev hücrelerin merkezinde/çevresinde yabancı materyal`,C:`Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar`,D:`Akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir`,E:`Anjiyogenez, fibrozis ve yara izi oluşumu izlenir`},dogru:`C`,aciklama:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır. Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Teorik olarak erken yanıt M1 ağırlıklı, sonra doğrudan Bu dengenin bozulması kronik enflamasyon ve fibroziste doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Nötrofillerin kronik tablolardaki katılımı sürecine ait bir özelliktir ve m1 ve m2 dengesi düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Yabancı cisim granülomları sürecine ait bir özelliktir ve m1 ve m2 dengesi düzeneğini tanımlamaz.`,C:`Doğru; Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar çünkü Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 düzeneği bu sonucu üretir.`,D:`Yanlış; bu ifade Kronik enflamasyonun tanımı sürecine ait bir özelliktir ve m1 ve m2 dengesi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonun morfolojik özellikleri sürecine ait bir özelliktir ve m1 ve m2 dengesi düzeneğini tanımlamaz.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Alternatif (M2) makrofaj aktivasyonu mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Merkezi nekroz yoktur`,B:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar`,C:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt`,D:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır`,E:`IL-4 ve IL-13 ile indüklenir`},dogru:`E`,aciklama:`Tıbbi Patoloji düzeneğinde IL-4 ve IL-13 ile indüklenir bilinir. Doku onarımı ve fibrozis (anjiyogenez, fibroblast aktivasyonu, kollajen sentezi) ile enflamasyonun baskılanması. Mekanizma bu sırayla işlediği için beklenen sonuç Doku onarımı ve fibrozis (anjiyogenez, fibroblast aktivasyonu, olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Non-kazeöz granülom sürecine ait bir özelliktir ve alternatif (m2) makrofaj aktivasyonu düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Kronik enflamasyon ve fibrozis sürecine ait bir özelliktir ve alternatif (m2) makrofaj aktivasyonu düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Aşırı duyarlılık (immün) hastalıkları sürecine ait bir özelliktir ve alternatif (m2) makrofaj aktivasyonu düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade M1 ve M2 dengesi sürecine ait bir özelliktir ve alternatif (m2) makrofaj aktivasyonu düzeneğini tanımlamaz.`,E:`Doğru; IL-4 ve IL-13 ile indüklenir. Bu mekanizma doku onarımı ve fibrozis (anjiyogenez, fibroblast aktivasyonu, kollajen sonucunu doğurur.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q08`,kazanim:5,zorluk:`orta`,soru:`Makrofaj aktivasyonunun iki ana yolu olan Klasik (M1) ve Alternatif (M2) yolların uyarılma sinyalleri karşılaştırıldığında, KLASİK (M1) YOLU aktive eden temel sitokin ve mikrobiyal ürün çifti aşağıdakilerden hangisidir?`,secenekler:{A:`İnterlökin-4 (IL-4) ve İnterlökin-13 (IL-13)`,B:`İnterferon-gama (IFN-γ) ve Endotoksin (LPS / TLR ligandları)`,C:`Transforme edici büyüme faktörü-beta (TGF-β) ve IL-10`,D:`Eritropoietin ve Trombopoietin`,E:`İnterlökin-5 ve Histamin`},dogru:`B`,aciklama:`Klasik makrofaj aktivasyonu (M1): Mikrobiyal ürünler (endotoksin/LPS, TLR ligandları) ve Th1 hücreleri ile NK hücrelerinden salınan İnterferon-gama (IFN-γ) ile indüklenir. Alternatif makrofaj aktivasyonu (M2) ise Th2 hücreleri, eozinofiller ve mast hücrelerinden salınan İnterlökin-4 (IL-4) ve İnterlökin-13 (IL-13) tarafından uyarılır.`,sik_aciklamalari:{A:`IL-4 ve IL-13 alternatif (M2) yolun uyarıcılarıdır.`,B:`Doğrudur. IFN-γ ve mikrobiyal LPS/TLR sinyalleri klasik (M1) makrofaj aktivasyonunu başlatır.`,C:`TGF-β ve IL-10 immünosupresif sitokinlerdir.`,D:`Hematopoetik sitokinlerdir.`,E:`IL-5 eozinofil farklılaşma faktörüdür.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q09`,kazanim:5,zorluk:`orta`,soru:`Klasik aktive makrofajların (M1) mikrop öldürme ve doku hasarı oluşturma kapasitesinde kullandığı temel sitotoksik moleküller hangileridir?`,secenekler:{A:`Reaktif oksijen türleri (ROS), Nitrik Oksit (NO) ve lizozomal enzimler`,B:`Tip I ve Tip III kollajen lifleri`,C:`İnterlökin-10 ve arginaz-1`,D:`VEGF ve FGF büyüme faktörleri`,E:`Mukopolisakkaritler ve hyalüronik asit`},dogru:`A`,aciklama:`M1 makrofajlar uyarılınca fagozom membranında NADPH oksidaz kompleksini toplayarak Reaktif Oksijen Türleri (ROS) üretirler; ayrıca iNOS enzimini eksprese ederek yüksek miktarda Nitrik Oksit (NO) sentezlerler. ROS ve NO birleşerek çok güçlü bir mikrobisidal ve sitotoksik radikal olan 'peroksinitrit'i oluşturur. Lizozomal asit hidrolazlarla birlikte fagozitoz yapılan mikropları yok ederler.`,sik_aciklamalari:{A:`Doğrudur. M1 makrofajlar ROS, NO (iNOS) ve lizozomal enzimlerle mikrobisidal ve doku hasarı yapıcı etki gösterir.`,B:`Kollajen M2 makrofajların uyardığı onarım ürünüdür.`,C:`IL-10 ve arginaz-1 M2 makrofajlara özgüdür.`,D:`VEGF ve FGF anjiyogenez/onarım faktörleridir (M2).`,E:`Mukopolisakkaritler matriks elemanıdır.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q10`,kazanim:5,zorluk:`zor`,soru:`L-arginin amino asidinin hücre içi metabolizmasında M1 ve M2 makrofajlar arasındaki enzimatik ayrım aşağıdakilerden hangisinde DOĞRU olarak verilmiştir?`,secenekler:{A:`M1 makrofajlar argininden histamin üretir; M2 makrofajlar argininden üre üretir.`,B:`M1 makrofajlar arginini indüklenebilir Nitrik Oksit Sentaz (iNOS) ile Nitrik Oksite (NO) dönüştürür; M2 makrofajlar ise arginini Arginaz-1 enzimi ile prolin ve poliaminlere (kollajen sentezi ve hücre çoğalması için) dönüştürür.`,C:`Her iki makrofaj tipi de arginini doğrudan glukoza çevirir.`,D:`M1 makrofajlarda arginaz-1 aşırı eksprese edilirken iNOS tamamen sıfırlanır.`,E:`M2 makrofajlar arginini parçalayarak süperoksit anyonuna dönüştürür.`},dogru:`B`,aciklama:`M1 ve M2 makrofajların en temel biyokimyasal ayrımı L-arginin metabolizmasındadır: M1 makrofajlar L-arginini iNOS enzimiyle sitotoksik NO ve sitrüline dönüştürür (mikrobisidal etki). M2 makrofajlar ise L-arginini Arginaz-1 enzimiyle ornitin, prolin ve poliaminlere dönüştürür. Prolin fibroblastlarca kollajen sentezinde, poliaminler ise hücre proliferasyonu ve doku onarımında kullanılır.`,sik_aciklamalari:{A:`Argininden histamin üretilmez (histidinden üretilir).`,B:`Doğrudur. M1'de iNOS → NO; M2'de Arginaz-1 → ornitin/prolin (kollajen ve tamir) sentezlenir.`,C:`Glukoneogenez karaciğer/böbrek işidir.`,D:`Arginaz-1 M2'ye, iNOS M1'e aittir; tersi değil.`,E:`Süperoksit NADPH oksidaz ürünüdür.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q11`,kazanim:5,zorluk:`orta`,soru:`Alternatif yoldan aktive olan makrofajların (M2) temel fizyolojik ve patolojik işlevleri aşağıdakilerden hangisinde EKSİKSİZ tanımlanmıştır?`,secenekler:{A:`Mikropları fagositozla öldürmek ve yüksek ateş oluşturmak`,B:`Doku onarımı (anjiyogenez, fibroblast proliferasyonu ve kollajen birikimi), paraziter enfeksiyonlarla mücadele ve enflamasyonu yatıştırıcı (anti-enflamatuar) etki`,C:`Kemik iliğinde granülosit yapımını durdurmak`,D:`Tüm bağışıklık sistemini kalıcı olarak lize etmek`,E:`Sadece akut apandisitte püy oluşumunu sağlamak`},dogru:`B`,aciklama:`M2 makrofajlar IL-4 ve IL-13 ile aktive olurlar. Başlıca fonksiyonları: 1) Enflamasyonu yatıştırmak (IL-10 ve TGF-β salgılayarak anti-enflamatuar etki), 2) Doku onarımı ve yara iyileşmesi (TGF-β, PDGF ve FGF ile fibroblastları uyarma, anjiyogenez ve kollajen depolanması), 3) Paraziter helmint enfeksiyonlarına karşı Th2 aracılı koruma sağlamaktır. Patolojik olarak aşırı M2 aktivitesi organ fibrozisine (siroz, pulmoner fibrozis) yol açar.`,sik_aciklamalari:{A:`Mikrop öldürme ve ateş M1 makrofajların işidir.`,B:`Doğrudur. M2 makrofajlar doku onarımı, fibrozis, anti-enflamatuar etki ve parazit yanıtından sorumludur.`,C:`Granülopoezi durdurmaz.`,D:`İmmün sistemi lize etmez.`,E:`Püy oluşumu nötrofil ve M1 makrofajların litik aktivitesidir.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q12`,kazanim:5,zorluk:`zor`,soru:`Kronik enflamasyonda M1 ve M2 makrofaj fenotipleri arasındaki dinamik denge (polarizasyon) ve plastisite ile ilgili aşağıdaki ifadelerden hangisi DOĞRUDUR?`,secenekler:{A:`Bir monosit bir kez M1 olduğunda genetik olarak kilitlenir ve asla M2 fenotipine dönüşemez.`,B:`Makrofajlar çevre dokudaki sitokin mikroçevresine son derece duyarlıdır (plastisite); enflamasyonun erken evresinde M1 fenotipinde mikrop temizlerken, doku temizlendikten sonra mikroçevrede IL-4/IL-10/TGF-β artışıyla M2 fenotipine geçerek onarımı başlatabilirler.`,C:`M2 makrofajlar sadece embriyonik hayatta bulunur, doğumdan sonra vücutta hiç M2 kalmaz.`,D:`M1 makrofajlar sadece viral enfeksiyonlarda, M2 sadece fungal enfeksiyonlarda çalışır.`,E:`Glukokortikoidler M1 fenotipini 100 kat artırarak doku hasarını patlatır.`},dogru:`B`,aciklama:`Makrofajlar olağanüstü bir fonksiyonel esnekliğe (plastisite) sahiptir. M1 ve M2 kesin sınırlarla ayrılmış nihai hücreler değil, bir spektrumun iki ucudur. Doku hasarının başlangıcında patojen ve IFN-γ varlığında makrofajlar M1 yönüne polarize olur. Enfeksiyon kontrol altına alındığında lokal mikroçevre değişir (rezolüsyon sitokinleri baskınlaşır); aynı makrofajlar M2 fenotipine kayarak debrisi temizler ve iyileşmeyi/fibrozisi yönetir.`,sik_aciklamalari:{A:`Genetik kilitlenme yoktur; makrofajlar plastiktir ve fenotip değiştirebilir.`,B:`Doğrudur. Mikroçevreye göre makrofajlar M1 ve M2 arasında geçiş yapabilir (makrofaj plastisitesi).`,C:`M2 erişkinde her türlü doku onarımında ve organ fibrozisinde aktiftir.`,D:`Mikrop türüyle böyle katı bir ayrım yoktur.`,E:`Steroidler M1 aktivasyonunu baskılar, M2'yi destekler.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q13`,kazanim:5,zorluk:`kolay`,soru:`"Makrofaj kökeni" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,C:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,D:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,A:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,B:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`},dogru:`E`,aciklama:`Doğru: İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,sik_aciklamalari:{E:`Doğru. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,C:`Yanlış. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,D:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,A:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,B:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`},bilgi:[10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q14`,kazanim:5,zorluk:`orta`,soru:`"Th17 hücreleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`IL-17 ve diğer sitokinleri salgılar`,B:`Eozinofil aktivasyonu yapar`,C:`Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,D:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,A:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},dogru:`E`,aciklama:`Doğru: IL-17 ve diğer sitokinleri salgılar`,sik_aciklamalari:{E:`Doğru. IL-17 ve diğer sitokinleri salgılar`,B:`Yanlış. Eozinofil aktivasyonu yapar`,C:`Yanlış. Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,D:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,A:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},bilgi:[19],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q15`,kazanim:5,zorluk:`orta`,soru:`"Kazeöz (kazeifiye) granülom" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,B:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,D:`Eozinofil aktivasyonu yapar`,A:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`},dogru:`C`,aciklama:`Doğru: Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,sik_aciklamalari:{C:`Doğru. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,B:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,D:`Yanlış. Eozinofil aktivasyonu yapar`,A:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Yanlış. Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k05-q16`,kazanim:5,zorluk:`zor`,soru:`"Kronik enflamasyonda baskın hücreler" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{C:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,A:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,B:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,E:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},dogru:`C`,aciklama:`Doğru: Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,sik_aciklamalari:{C:`Doğru. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,A:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,B:`Yanlış. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Yanlış. Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,E:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},bilgi:[3],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2, Th17) rolünü açıklamak`,sorular:[{id:`k1-13-q16`,kazanim:6,zorluk:`kolay`,soru:`IL-17 salgılayarak nötrofil alımını ve aktivasyonunu artıran CD4+ T hücre alt grubu aşağıdakilerden hangisidir?`,secenekler:{A:`Th1`,B:`Th2`,C:`Th17`,D:`Düzenleyici T hücresi`,E:`CD8+ sitotoksik T hücresi`},dogru:`C`,aciklama:`Th1 IFN-γ ile M1 aktivasyonunu, Th2 eozinofil aktivasyonu ve M2'yi, Th17 IL-17 ile nötrofil alımını destekler.`,sik_aciklamalari:{A:`Th1 IFN-γ üretir ve makrofajları klasik yolla aktive eder.`,B:`Th2 eozinofil aktivasyonu yapar ve M2'yi destekler.`,C:`Doğru. Th1 IFN-γ ile M1 aktivasyonunu, Th2 eozinofil aktivasyonu ve M2'yi, Th17 IL-17 ile nötrofil alımını destekler.`,D:`Düzenleyici T hücreleri yanıtı baskılar.`,E:`CD8+ hücreler sitotoksik etkilidir; CD4+ alt grubu değildir.`},bilgi:[17,18,19],benzer_cikmis:[]},{id:`k1-13-q17`,kazanim:6,zorluk:`orta`,soru:`CD4+ T hücre alt grupları ve etkileri eşleştirmelerinden hangisi doğrudur?`,secenekler:{A:`Th1 – IFN-γ ile klasik (M1) makrofaj aktivasyonu`,B:`Th2 – IL-17 ile nötrofil alımı`,C:`Th17 – eozinofil aktivasyonu`,D:`Th1 – alternatif (M2) makrofaj aktivasyonu`,E:`Th2 – IFN-γ üretimi`},dogru:`A`,aciklama:`Th1 hücreleri IFN-γ üreterek makrofajların klasik aktivasyonunu uyarır.`,sik_aciklamalari:{A:`Doğru. Th1 hücreleri IFN-γ üreterek makrofajların klasik aktivasyonunu uyarır.`,B:`IL-17 ile nötrofil alımı Th17'ye aittir.`,C:`Eozinofil aktivasyonu Th2'ye aittir.`,D:`M2 aktivasyonunu Th2 destekler.`,E:`IFN-γ Th1 ürünüdür: th2 – IFN-γ üretimi.`},bilgi:[17,18,19],benzer_cikmis:[]},{id:`k1-13-q18`,kazanim:6,zorluk:`zor`,soru:`Kronik enflamasyonda lenfositler ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`Makrofajlarla birlikte kronik enflamasyonda baskın hücrelerdendir.`,B:`Adaptif bağışıklıkla antijen özgüllüğü sağlar.`,C:`B hücreleri ve plazma hücreleri antikor üretir.`,D:`Bazı kronik lezyonlarda plazma hücreleri belirgindir.`,E:`Lenfositler kronik enflamasyonda yalnızca seyirci hücrelerdir; makrofajları etkilemezler.`},dogru:`E`,aciklama:`T lenfositler sitokinlerle (IFN-γ, IL-4, IL-17) makrofajları ve diğer hücreleri aktive ederek kronik enflamasyonu yönlendirir.`,sik_aciklamalari:{A:`Doğru ifade: makrofajlarla birlikte kronik enflamasyonda baskın hücrelerdendir.`,B:`Doğru ifade: adaptif bağışıklıkla antijen özgüllüğü sağlar.`,C:`Doğru ifade: B hücreleri ve plazma hücreleri antikor üretir.`,D:`Doğru ifade: bazı kronik lezyonlarda plazma hücreleri belirgindir.`,E:`Yanlış ifade (aranan cevap). T lenfositler sitokinlerle (IFN-γ, IL-4, IL-17) makrofajları ve diğer hücreleri aktive ederek kronik enflamasyonu yönlendirir.`},bilgi:[16,17,20],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q04`,kazanim:6,zorluk:`orta`,soru:`62 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2, Th17) rolünü açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar ilkesinin tam tersi geçerlidir ve Nötrofil alımı ve aktivasyonu artar gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Th17 hücreleri olup "Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2,…" ile ilişkisizdir`,C:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar Bu nedenle B hücreleri ve plazma hücreleri antikor üretir; bazı kronik lezyonlarda belirgindir`,D:`Bulgular "Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2, Th17) rolünü…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Lenfositlerin rolü" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar Doğrudan sonucu "B hücreleri ve plazma hücreleri antikor üretir; bazı kronik lezyonlarda belirgindir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,C:`Doğru; Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar Bu nedenle…`,D:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`},bilgi:[16,17],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q05`,kazanim:6,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Th17 hücreleri" vurgulanıyor ve hekim "Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2, Th17) rolünü açıklamak" kazanımındaki "IL-17 ve diğer sitokinleri salgılar" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Nötrofil alımı ve aktivasyonu artar hiçbir koşulda gözlenmez ve Lenfositlerin rolü tek belirleyicidir`,B:`Bu süreçte "Lenfositlerin rolü" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Th17 hücreleri" ayırıcı tanıda gereksizdir`,D:`Nötrofil alımı ve aktivasyonu artar Çünkü IL-17 ve diğer sitokinleri salgılar`,E:`Bu olguda izlem gerekmez; "Lenfositlerin ve CD4+ T hücre alt gruplarının (Th1, Th2, Th17) rolünü…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: IL-17 ve diğer sitokinleri salgılar sonucu "Nötrofil alımı ve aktivasyonu artar" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`,D:`Doğru; Nötrofil alımı ve aktivasyonu artar Çünkü IL-17 ve diğer sitokinleri salgılar`,E:`Yanlış; ders paketindeki "Lenfositlerin rolü" bilgisiyle çelişir.`},bilgi:[18,19],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Th17 hücreleri: IL-17 ve diğer sitokinleri salgılar. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Çevrede lenfositler bulunur`,B:`Dev hücreler genellikle nadirdir`,C:`Akciğer örneğinde normal alveollerin kübik epitelli boşluklarla yer değiştirmesi olarak`,D:`Nötrofil alımı ve aktivasyonu artar`,E:`Tümü mononükleer fagosit sisteminin parçasıdır`},dogru:`D`,aciklama:`Tıbbi Patoloji düzeneğinde IL-17 ve diğer sitokinleri salgılar bilinir. Nötrofil alımı ve aktivasyonu artar. Mekanizma bu sırayla işlediği için beklenen sonuç Nötrofil alımı ve aktivasyonu artar olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Granülom morfolojisi sürecine ait bir özelliktir ve th17 hücreleri düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Kedi tırmığı hastalığında granülom sürecine ait bir özelliktir ve th17 hücreleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Kronik enflamasyonun üç histolojik özelliği sürecine ait bir özelliktir ve th17 hücreleri düzeneğini tanımlamaz.`,D:`Doğru; Nötrofil alımı ve aktivasyonu artar çünkü IL-17 ve diğer sitokinleri salgılar düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Yerleşik makrofaj isimleri sürecine ait bir özelliktir ve th17 hücreleri düzeneğini tanımlamaz.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Th2 hücreleri mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Eozinofil aktivasyonu yapar`,B:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir`,C:`Nötrofiller ve ödem`,D:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,E:`Kronik enflamasyonda makrofajlarla birlikte baskın`},dogru:`A`,aciklama:`Eozinofil aktivasyonu yapar. Alternatif (M2) makrofaj aktivasyonunu destekler. Fizyopatolojik sıra bu yönde ilerlediğinden Eozinofil aktivasyonu yapar varlığında Alternatif (M2) makrofaj aktivasyonunu destekler beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Eozinofil aktivasyonu yapar. Bu mekanizma alternatif (m2) makrofaj aktivasyonunu destekler sonucunu doğurur.`,B:`Yanlış; bu ifade T hücre aracılı granülomatöz yanıt sürecine ait bir özelliktir ve th2 hücreleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Akut enflamasyonda baskın hücre sürecine ait bir özelliktir ve th2 hücreleri düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Makrofajın merkezi rolü sürecine ait bir özelliktir ve th2 hücreleri düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Lenfositlerin rolü sürecine ait bir özelliktir ve th2 hücreleri düzeneğini tanımlamaz.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q08`,kazanim:6,zorluk:`orta`,soru:`CD4+ T yardımcı lenfositlerin üç ana alt grubu olan Th1, Th2 ve Th17 hücrelerinin salgıladıkları karakteristik anahtar sitokinler aşağıdakilerin hangisinde EKSİKSİZ ve DOĞRU eşleştirilmiştir?`,secenekler:{A:`Th1: IFN-γ — Th2: IL-4, IL-5, IL-13 — Th17: IL-17, IL-22`,B:`Th1: IL-4 — Th2: IFN-γ — Th17: Histamin`,C:`Th1: IL-10 — Th2: TNF-α — Th17: Bradikinin`,D:`Th1: Eritropoietin — Th2: Tromboksan — Th17: Heparin`,E:`Th1: Serotonin — Th2: Dopamin — Th17: GABA`},dogru:`A`,aciklama:`CD4+ T efektör hücre alt grupları ve imza sitokinleri: 1) Th1: İnterferon-gama (IFN-γ) salgılar; klasik makrofaj (M1) aktivasyonunu ve hücre içi patojenlerin fagositozla öldürülmesini sağlar. 2) Th2: İnterlökin-4, IL-5 ve IL-13 salgılar; IgE sentezini, eozinofil alımını ve alternatif makrofaj (M2) aktivasyonunu yönetir. 3) Th17: İnterlökin-17 ve IL-22 salgılar; nötrofil ve monositlerin dokuya çekilmesini sağlar.`,sik_aciklamalari:{A:`Doğrudur. Th1: IFN-γ; Th2: IL-4/5/13; Th17: IL-17/22 imza sitokinleridir.`,B:`Th1 ve Th2 sitokinleri karıştırılmıştır.`,C:`Histamin ve bradikinin T hücre sitokini değildir.`,D:`Eritropoietin ve tromboksan T hücre sitokini değildir.`,E:`Bunlar nörotransmiterlerdir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q09`,kazanim:6,zorluk:`zor`,soru:`Granülomatöz kronik enflamasyonların (örneğin Tüberküloz veya Sarkoidoz) patogenezinde doku makrofajlarını uyararak 'epiteloid histiyositlere' ve 'Langhans dev hücrelerine' dönüştüren majör CD4+ T hücre alt grubu ve salgıladığı sitokin hangisidir?`,secenekler:{A:`Th2 lenfositler — İnterlökin-4`,B:`Th1 lenfositler — İnterferon-gama (IFN-γ)`,C:`Treg (Regülatuvar T) hücreler — İnterlökin-10`,D:`Th17 lenfositler — İnterlökin-22`,E:`Sitotoksik CD8+ T lenfositler — Perforin`},dogru:`B`,aciklama:`Granülom oluşumu klasik bir gecikmiş tip aşırı duyarlık (Tip IV hipersensitivite) reaksiyonudur. Antijeni sunan dendritik hücreler ve makrofajlar IL-12 salgılayarak naif CD4+ T hücrelerini Th1 hücrelerine dönüştürür. Th1 hücreleri yüksek miktarda İnterferon-gama (IFN-γ) salgılar. IFN-γ makrofajları aktive eder, onları bol eozinofilik sitoplazmalı 'epiteloid histiyositlere' ve birbirleriyle kaynaştırarak 'Langhans tipi multinükleer dev hücrelere' dönüştürür.`,sik_aciklamalari:{A:`Th2 parazit ve alerjide rol oynar, epiteloid granülom yapmaz.`,B:`Doğrudur. Th1 kaynaklı IFN-γ granülom oluşumunun (epiteloid hücre ve dev hücre) anahtar itici gücüdür.`,C:`Treg immün yanıtı baskılar.`,D:`Th17 nötrofil kemotaksisi yapar.`,E:`CD8 perforin ile hedef hücreyi lize eder, granülom stimülatörü değildir.`},bilgi:[6,9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q10`,kazanim:6,zorluk:`orta`,soru:`Kronik enflamasyon alanında plazma hücrelerinin varlığı mikroskopik olarak saptandığında, bu hücrelerin temel patolojik işlevi aşağıdakilerden hangisidir?`,secenekler:{A:`Doku içine doğrudan serbest oksijen radikali püskürtmek`,B:`Antijene özgü immünoglobulinler (antikorlar) üreterek persistan antijenleri veya hücresel debrisleri opsonize etmek ve nötralize etmek`,C:`Arteriolleri vazokonstriksiyona uğratmak`,D:`Fibroblastları doğrudan eriterek skar dokusunu yok etmek`,E:`Kemik iliğinde kalsiyum depolarını eritmek`},dogru:`B`,aciklama:`Plazma hücreleri, terminal olarak farklılaşmış B lenfositleridir. Kronik enflamasyon odağında antijenik uyarının devam etmesi B hücrelerinin klonal proliferasyonuna ve plazma hücrelerine dönüşmesine yol açar. Plazma hücreleri persistan yabancı veya otoantijenlere karşı spesifik immünoglobulinler (IgG, IgA, IgM) üreterek antijenlerin opsonize edilmesine, kompleman fiksasyonuna veya antijen nötralizasyonuna katkı sağlarlar.`,sik_aciklamalari:{A:`Serbest radikal üretimi makrofaj ve nötrofillerin işidir.`,B:`Doğrudur. Plazma hücreleri persistan antijenlere karşı antikor üreten efektör hücrelerdir.`,C:`Vazokonstriksiyon yapmazlar.`,D:`Fibroblastları eritmezler.`,E:`Kalsiyum depolamasıyla doğrudan ilişkili değillerdir.`},bilgi:[3,6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q11`,kazanim:6,zorluk:`zor`,soru:`Helmintik (paraziter) enfeksiyonlarda ve alerjik kronik enflamatuar hastalıklarda (örneğin astım ve atopik dermatit) baskın olan ve B lenfositlerinden IgE izotip değişimini (class-switching) uyaran Th2 sitokini aşağıdakilerden hangisidir?`,secenekler:{A:`İnterlökin-4 (IL-4)`,B:`İnterferon-gama (IFN-γ)`,C:`İnterlökin-12 (IL-12)`,D:`Tümör Nekrozis Faktör (TNF)`,E:`İnterlökin-1 (IL-1)`},dogru:`A`,aciklama:`Th2 lenfositler tarafından üretilen İnterlökin-4 (IL-4), B lenfositlerinde STAT6 yolağı üzerinden immünoglobulin ağır zincir gen rekombinasyonunu uyararak IgE izotipine dönüşümü (class switching) sağlar. Üretilen IgE mast hücreleri ve bazofillerin FcεRI reseptörlerine bağlanarak parazitlere karşı korumayı ve alerjik reaksiyonları yönetir.`,sik_aciklamalari:{A:`Doğrudur. IL-4 B hücrelerinden IgE üretimini (izotip değişimini) tetikleyen majör Th2 sitokinidir.`,B:`IFN-γ IgG2a izotip değişimini uyarır, IgE'yi baskılar.`,C:`IL-12 Th1 yönüne iter.`,D:`TNF genel proinflamatuar sitokindir.`,E:`IL-1 akut faz sitokinidir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q12`,kazanim:6,zorluk:`orta`,soru:`Eozinofillerin kemik iliğinde farklılaşmasını, proliferasyonunu ve enflamasyon odağında aktivasyonunu sağlayan en spesifik Th2 sitokini aşağıdakilerden hangisidir?`,secenekler:{A:`İnterlökin-5 (IL-5)`,B:`İnterlökin-2 (IL-2)`,C:`İnterferon-alfa (IFN-α)`,D:`Eritropoietin`,E:`Trombopoietin`},dogru:`A`,aciklama:`İnterlökin-5 (IL-5), Th2 hücreleri ve mast hücreleri tarafından üretilir. Eozinofil soyunun kemik iliğinde olgunlaşmasını, dolaşıma çıkmasını, sağkalımını ve enflamasyon alanındaki efektör aktivasyonunu selektif olarak kontrol eden en önemli sitokindir. Anti-IL-5 biyolojik ajanlar (mepolizumab vb.) şiddetli eozinofilik astımda kullanılır.`,sik_aciklamalari:{A:`Doğrudur. IL-5 eozinofillerin büyüme, farklılaşma ve aktivasyon sitokinidir.`,B:`IL-2 T hücre otokrin proliferasyon faktörüdür.`,C:`IFN-α viral savunma sitokinidir.`,D:`Eritropoietin eritrositler içindir.`,E:`TPO trombositler içindir.`},bilgi:[6,8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q13`,kazanim:6,zorluk:`kolay`,soru:`Aşağıdakilerden "Mast hücreleri" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,D:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,B:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,A:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},dogru:`C`,aciklama:`Doğru: Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,sik_aciklamalari:{C:`Doğru. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Yanlış. Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,D:`Yanlış. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,B:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,A:`Yanlış. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`},bilgi:[23],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q14`,kazanim:6,zorluk:`orta`,soru:`"Makrofajın merkezi rolü" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,A:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,E:`Merkezi nekroz yoktur`,C:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`},dogru:`B`,aciklama:`Doğru: Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,sik_aciklamalari:{B:`Doğru. Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`,A:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,E:`Yanlış. Merkezi nekroz yoktur`,C:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`},bilgi:[9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q15`,kazanim:6,zorluk:`orta`,soru:`"Kedi tırmığı hastalığında granülom" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,A:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},dogru:`B`,aciklama:`Doğru: Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,sik_aciklamalari:{B:`Doğru. Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,E:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,C:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,A:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},bilgi:[32],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k06-q16`,kazanim:6,zorluk:`zor`,soru:`"Sifilizde granülom (gumma)" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,C:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},dogru:`B`,aciklama:`Doğru: Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,sik_aciklamalari:{B:`Doğru. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,C:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,D:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},bilgi:[31],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun sürdürülmesindeki önemini açıklamak`,sorular:[{id:`k1-13-q19`,kazanim:7,zorluk:`kolay`,soru:`Lenfosit-makrofaj döngüsünde makrofajın T hücresini aktive etmek için salgıladığı sitokin aşağıdakilerden hangisidir?`,secenekler:{A:`IL-12`,B:`IL-10`,C:`IL-4`,D:`TGF-β`,E:`IL-13`},dogru:`A`,aciklama:`Makrofaj antijen sunar ve IL-12 salgılayarak T hücresini aktive eder; T hücresi de IFN-γ ile makrofajı yeniden aktive eder.`,sik_aciklamalari:{A:`Doğru. Makrofaj antijen sunar ve IL-12 salgılayarak T hücresini aktive eder; T hücresi de IFN-γ ile makrofajı yeniden aktive eder.`,B:`IL-10 baskılayıcı bir sitokindir.`,C:`IL-4 Th2/M2 yanıtıyla ilişkilidir.`,D:`TGF-β fibrozis ve baskılamayla ilişkilidir.`,E:`IL-13 M2 aktivasyonu yapar.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-q20`,kazanim:7,zorluk:`orta`,soru:`Lenfosit-makrofaj etkileşiminin kronik enflamasyonu sürdürmesi en iyi aşağıdakilerden hangisiyle açıklanır?`,secenekler:{A:`İki hücrenin birbirini baskılaması`,B:`Makrofajların antikor üretmesi`,C:`Lenfositlerin makrofajları fagosite etmesi`,D:`Makrofajın IL-12 ve antijen sunumuyla T hücresini, T hücresinin IFN-γ ile makrofajı karşılıklı aktive ettiği pozitif geri besleme döngüsü`,E:`Lenfositlerin kompleman sistemini inhibe etmesi`},dogru:`D`,aciklama:`Karşılıklı aktivasyon döngüsü uyaran ortadan kalkmadıkça yanıtın süregen olmasına yol açar.`,sik_aciklamalari:{A:`Hücreler birbirini aktive eder.`,B:`Makrofajlar antikor üretmez.`,C:`Böyle bir etkileşim yoktur.`,D:`Doğru. Karşılıklı aktivasyon döngüsü uyaran ortadan kalkmadıkça yanıtın süregen olmasına yol açar.`,E:`Böyle bir mekanizma döngüyü açıklamaz.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-q21`,kazanim:7,zorluk:`zor`,soru:`Kronik granülomatöz bir hastalıkta IFN-γ etkisinin bloke edilmesi (ör. IFN-γ reseptör defekti) durumunda en olası sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Makrofajların klasik aktivasyonu azalır, hücre içi mikropların (ör. mikobakteriler) kontrolü bozulur.`,B:`Makrofajlar daha güçlü mikrobisidal hale gelir.`,C:`Plazma hücreleri antikor üretimini bırakır.`,D:`Nötrofillerin kemik iliğinden çıkışı durur.`,E:`Hiçbir etkisi olmaz.`},dogru:`A`,aciklama:`Lenfosit-makrofaj döngüsünün IFN-γ ayağı bozulunca makrofajlar aktive olamaz; hücre içi patojenler kontrol edilemez ve granülom oluşumu zayıflar.`,sik_aciklamalari:{A:`Doğru. Lenfosit-makrofaj döngüsünün IFN-γ ayağı bozulunca makrofajlar aktive olamaz; hücre içi patojenler kontrol edilemez ve granülom oluşumu zayıflar.`,B:`IFN-γ yokluğunda mikrobisidal aktivite azalır.`,C:`Antikor üretimi doğrudan IFN-γ'ya bağlı değildir.`,D:`Nötrofil çıkışı bu defektle ilişkili değildir.`,E:`IFN-γ döngünün temel sitokinidir; etkisi önemlidir.`},bilgi:[20,30],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q04`,kazanim:7,zorluk:`orta`,soru:`69 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun sürdürülmesindeki önemini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı… ilkesinin tam tersi geçerlidir ve Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Lenfosit-makrofaj döngüsü olup "Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun…" ile ilişkisizdir`,C:`Bulgular "Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun sürdürülmesindeki…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder Bu nedenle Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Lenfosit-makrofaj döngüsü" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder Doğrudan sonucu "Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,D:`Doğru; Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden…`,E:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q05`,kazanim:7,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Lenfosit-makrofaj döngüsü" vurgulanıyor ve hekim "Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun sürdürülmesindeki önemini açıklamak" kazanımındaki "Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir hiçbir koşulda gözlenmez ve Lenfosit-makrofaj döngüsü tek belirleyicidir`,B:`Bu süreçte "Lenfosit-makrofaj döngüsü" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Lenfosit-makrofaj döngüsü" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "Lenfosit-makrofaj döngüsünü ve kronik enflamasyonun sürdürülmesindeki…" yalnızca teorik bir bilgidir`,E:`Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir Çünkü Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden…`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder sonucu "Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Lenfosit-makrofaj döngüsü" bilgisiyle çelişir.`,E:`Doğru; Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir Çünkü Makrofaj antijen sunar ve…`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q06`,kazanim:7,zorluk:`orta`,soru:`Lenfosit-makrofaj döngüsü: Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Nedenler sınırlı sayıda hastalık grubunu düşündürür`,B:`Bu enflamasyon hastalık seyrine anlamlı katkı sunar`,C:`Akciğerde kronik hastalık veya arter duvarında kronik enflamasyon gelişir`,D:`Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar`,E:`Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir`},dogru:`E`,aciklama:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder. Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir. Fizyopatolojik sıra bu yönde ilerlediğinden Makrofaj antijen sunar ve IL-12 salgılar, T varlığında Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Granülomatöz enflamasyonun nedenleri sürecine ait bir özelliktir ve lenfosit-makrofaj döngüsü düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Non-klasik hastalıklar sürecine ait bir özelliktir ve lenfosit-makrofaj döngüsü düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Uzun süreli toksik maruziyet sürecine ait bir özelliktir ve lenfosit-makrofaj döngüsü düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade M1 ve M2 dengesi sürecine ait bir özelliktir ve lenfosit-makrofaj döngüsü düzeneğini tanımlamaz.`,E:`Doğru; Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir çünkü Makrofaj antijen sunar ve IL-12 salgılar, T hücresini düzeneği bu sonucu üretir.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Non-klasik hastalıklar mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bartonella henselae (gram-negatif basil)`,B:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük`,C:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan`,D:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ`,E:`IL-17 ve diğer sitokinleri salgılar`},dogru:`B`,aciklama:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur. Bu enflamasyon hastalık seyrine anlamlı katkı sunar. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer doğrudan Bu enflamasyon hastalık seyrine anlamlı katkı sunar doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kedi tırmığı hastalığında granülom sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,B:`Doğru; Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur. Bu mekanizma bu enflamasyon hastalık seyrine anlamlı katkı sunar sonucunu doğurur.`,C:`Yanlış; bu ifade Kalıcı enfeksiyonlar sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Klasik (M1) makrofaj aktivasyonu sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Th17 hücreleri sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q08`,kazanim:7,zorluk:`orta`,soru:`Kronik enflamasyonun aylarca devam etmesini ve kendi kendini besleyen bir kısır döngüye (self-perpetuating loop) dönüşmesini sağlayan 'Lenfosit-Makrofaj Etkileşim Döngüsü'nün temel adımları aşağıdakilerden hangisinde DOĞRU özetlenmiştir?`,secenekler:{A:`Nötrofiller lenfositleri parçalar, açığa çıkan nükleuslar makrofajları inhibe eder.`,B:`Makrofajlar antijen sunup IL-12 salgılayarak T hücrelerini aktive eder; aktive Th1 hücreleri ise IFN-γ salgılayarak daha fazla makrofajı uyarır ve sitokin salgılatır.`,C:`Lenfositler sadece histamin salgılar, makrofajlar ise histamini sindirerek döngüyü sonlandırır.`,D:`Döngü sadece kompleman proteinlerinin karaciğerden tamamen tükenmesiyle çalışır.`,E:`T hücreleri makrofajları doğrudan eritrositlere dönüştürür.`},dogru:`B`,aciklama:`Kronik enflamasyonun devamlılığını sağlayan çekirdek mekanizma iki yönlü 'Lenfosit-Makrofaj Karşılıklı Etkileşim Döngüsü'dür: 1) Makrofajlar antijeni T hücresine sunar ve IL-12/IL-6 salgılar. 2) Uyarılmış T lenfositleri (özellikle Th1) IFN-γ salgılar. 3) IFN-γ doku makrofajlarını daha da güçlü aktive ederek daha fazla TNF, IL-1, kemokin ve reaktif radikal salgılatır. Bu iki yönlü pozitif geri bildirim (feed-forward) döngüsü etken ortadan kalkmadığı sürece kronik reaksiyonu alevlendirerek sürdürür.`,sik_aciklamalari:{A:`Nötrofillerin lenfositleri parçalaması söz konusu değildir.`,B:`Doğrudur. Makrofaj (antijen sunumu + IL-12) → T hücresi (IFN-γ) → Makrofaj aktivasyonu döngüsü kronik enflamasyonu besler.`,C:`Lenfositler histamin üretmez.`,D:`Kompleman tükenmesi döngünün şartı değildir.`,E:`Makrofaj eritrosite dönüşemez.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q09`,kazanim:7,zorluk:`zor`,soru:`Lenfosit-makrofaj döngüsünde makrofajlar tarafından üretilerek yeni lenfosit ve monositlerin damardan dokuya sürekli göç etmesini (lökosit alımını) sağlayan temel kemotaktik faktörler ve sitokinler hangileridir?`,secenekler:{A:`TNF, IL-1 ve kemokinler (örn. CCL2 / MCP-1, CXCL10)`,B:`Albümin ve transferrin`,C:`Safra tuzları ve bilirubin`,D:`İnsülin ve glukagon`,E:`Troponin ve kreatin kinaz`},dogru:`A`,aciklama:`Aktive makrofajlar TNF ve IL-1 salgılayarak vasküler endotelde lökosit adezyon moleküllerini (VCAM-1, ICAM-1) sürekli açık tutarlar. Eşzamanlı olarak salgıladıkları CCL2 (MCP-1 - monositleri çeker) ve CXCL10 (aktive T lenfositlerini çeker) gibi kemokinlerle dolaşımdaki yeni lenfosit ve monositleri dokuya davet ederler. Böylece döngüye sürekli taze lökosit katılır.`,sik_aciklamalari:{A:`Doğrudur. TNF, IL-1 ve kemokinler (CCL2, CXCL10) yeni lenfosit ve monosit alımını sürekli besler.`,B:`Albümin ve transferrin plazma proteinleridir.`,C:`Safra elemanlarıdır.`,D:`Pankreas hormonlarıdır.`,E:`Miyokard nekroz enzimleridir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q10`,kazanim:7,zorluk:`orta`,soru:`Lenfosit-makrofaj döngüsünün kontrolsüz bir şekilde aşırı çalışması sonucu makrofajların fagositer aktivitesinin kontrolden çıkarak kan hücrelerini (eritrosit, lökosit, trombosit) yutmaya başlamasıyla karakterize hayatı tehdit eden tablo hangisidir?`,secenekler:{A:`Hemofagositik Lenfohistiyositoz (Makrofaj Aktivasyon Sendromu - MAS)`,B:`Basit demir eksikliği anemisi`,C:`Akut romatizmal ateş`,D:`Tip 1 diyabet`,E:`Kistik fibrozis`},dogru:`A`,aciklama:`Hemofagositik Lenfohistiyositoz (HLH) veya sistemik otoimmün hastalıklarda görülen adıyla Makrofaj Aktivasyon Sendromu (MAS): CD8+ T ve NK hücreleri ile makrofajlar arasındaki kontrol mekanizmalarının bozulması sonucu kontrolsüz masif sitokin fırtınası (IFN-γ, TNF, IL-6) ve hiperaktif makrofaj proliferasyonuyla seyreder. Aktive makrofajlar kemik iliğinde ve dalakta eritrosit ve diğer kan hücrelerini yutarlar (hemofagositoz); pansitopeni, aşırı ferritin yüksekliği ve karaciğer yetmezliği gelişir.`,sik_aciklamalari:{A:`Doğrudur. Makrofaj aktivasyon sendromu/HLH lenfosit-makrofaj döngüsünün fırtınaya dönüşmesidir.`,B:`Demir eksikliği nütrisyoneldir.`,C:`ARA moleküler benzerlik vaskülit/karditidir.`,D:`Tip 1 diyabet adacık otoimmünitesidir.`,E:`Kistik fibrozis CFTR klor kanal defektidir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q11`,kazanim:7,zorluk:`zor`,soru:`Lenfosit-makrofaj döngüsünün kırılması ve kronik enflamasyonun rezolüsyonu (sonlanması) için organizmada devreye giren en önemli anti-enflamatuar stop-sinyali sitokinler aşağıdakilerden hangisidir?`,secenekler:{A:`İnterlökin-10 (IL-10) ve Transforme Edici Büyüme Faktörü-beta (TGF-β)`,B:`Tümör Nekrozis Faktör (TNF) ve İnterlökin-1`,C:`İnterferon-gama ve İnterlökin-12`,D:`İnterlökin-17 ve İnterlökin-8`,E:`Bradikinin ve Histamin`},dogru:`A`,aciklama:`Enflamasyonun kendi kendini sınırlaması ve lenfosit-makrofaj döngüsünün durdurulması için regülatuvar T hücreleri (Treg) ve M2 makrofajlar devreye girer. Bu hücrelerin ürettiği IL-10 (makrofajlardan sitokin üretimini ve MHC-II ekspresyonunu baskılar) ve TGF-β (lenfosit proliferasyonunu inhibe eder), döngüyü kırarak dokuyu onarım ve rezolüsyon fazına geçirir.`,sik_aciklamalari:{A:`Doğrudur. IL-10 ve TGF-β enflamatuar döngüyü sonlandıran temel anti-enflamatuar sitokinlerdir.`,B:`TNF ve IL-1 enflamasyonu alevlendirir.`,C:`IFN-γ ve IL-12 döngünün temel itici motorudur.`,D:`IL-17 ve IL-8 nötrofil alımını artırır.`,E:`Bradikinin ve histamin vazoaktif proenflamatuar mediyatörlerdir.`},bilgi:[7,14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q12`,kazanim:7,zorluk:`orta`,soru:`Kronik enflamasyonda lenfosit ve makrofajların doku parankimini tahrip etmesini önlemek amacıyla geliştirilen 'Anti-TNF' tedaviler bu döngüyü hangi noktadan kırarlar?`,secenekler:{A:`TNF'yi nötralize ederek endotel aktivasyonunu, lökosit alımını ve makrofaj sitokin salınım kaskadını bloke ederler.`,B:`Hastadaki tüm makrofajları apoptozla öldürürler.`,C:`Kemik iliğinde monosit kök hücrelerini yok ederler.`,D:`MHC genlerini parçalarlar.`,E:`Kan basıncını sıfırlayarak lökosit dolaşımını durdururlar.`},dogru:`A`,aciklama:`TNF inhibitörleri (infliksimab, adalimumab, etanersept vb.), çözünür ve membrana bağlı TNF'yi bağlayarak reseptörlerine (TNFR1 ve TNFR2) tutunmasını engellerler. Bu sayede endotel aktivasyonu durur, yeni lökositlerin dokuya geçişi kesilir ve makrofajların otokrin/parakrin uyarılması engellenerek lenfosit-makrofaj kaskadı kırılır.`,sik_aciklamalari:{A:`Doğrudur. TNF inhibisyonu endotel aktivasyonunu ve proenflamatuar sitokin basamağını bloke ederek döngüyü keser.`,B:`Tüm makrofajları yok etmezler.`,C:`Kök hücreleri tahrip etmezler.`,D:`MHC genleriyle ilişkisizdir.`,E:`Hemodinamik dolaşımı durdurmazlar.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q13`,kazanim:7,zorluk:`kolay`,soru:`"Kedi tırmığı hastalığında granülom" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,D:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},dogru:`E`,aciklama:`Doğru: Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,sik_aciklamalari:{E:`Doğru. Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,B:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,A:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,D:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,C:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},bilgi:[32],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q14`,kazanim:7,zorluk:`orta`,soru:`"Granülomatöz enflamasyonun nedenleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,D:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,E:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,C:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`},dogru:`B`,aciklama:`Doğru: Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,sik_aciklamalari:{B:`Doğru. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,D:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,E:`Yanlış. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,C:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`},bilgi:[28],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q15`,kazanim:7,zorluk:`orta`,soru:`"Kronik enflamasyonun tanımı" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,E:`IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,A:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`},dogru:`B`,aciklama:`Doğru: Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,sik_aciklamalari:{B:`Doğru. Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,E:`Yanlış. IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,A:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`},bilgi:[1],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k07-q16`,kazanim:7,zorluk:`zor`,soru:`"Th2 hücreleri" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Eozinofil aktivasyonu yapar`,B:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,A:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,D:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`},dogru:`E`,aciklama:`Doğru: Eozinofil aktivasyonu yapar`,sik_aciklamalari:{E:`Doğru. Eozinofil aktivasyonu yapar`,B:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,A:`Yanlış. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,D:`Yanlış. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,C:`Yanlış. IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`},bilgi:[18],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:8,metin:`Eozinofil, nötrofil ve mast hücrelerinin kronik enflamasyondaki rolünü özetlemek`,sorular:[{id:`k1-13-q22`,kazanim:8,zorluk:`kolay`,soru:`Helmint parazit enfeksiyonları ve IgE aracılı alerjik reaksiyonlarda belirgin olan, özgül kemoatraktanı eotaksin olan hücre aşağıdakilerden hangisidir?`,secenekler:{A:`Nötrofil`,B:`Eozinofil`,C:`Makrofaj`,D:`Plazma hücresi`,E:`Fibroblast`},dogru:`B`,aciklama:`Eozinofil granüllerindeki major basic protein parazitler için toksiktir, ancak konak epitel hücrelerine de zarar verir.`,sik_aciklamalari:{A:`Nötrofiller akut enflamasyonun tipik hücresidir.`,B:`Doğru. Eozinofil granüllerindeki major basic protein parazitler için toksiktir, ancak konak epitel hücrelerine de zarar verir.`,C:`Makrofajlar kronik enflamasyonun merkezi hücresidir; eotaksinle çağrılan hücre değildir.`,D:`Plazma hücreleri antikor üretir.`,E:`Fibroblastlar onarım hücresidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-13-q23`,kazanim:8,zorluk:`orta`,soru:`Kronik enflamasyona katılan diğer hücreler ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`Eozinofil granüllerindeki major basic protein parazitler için toksiktir.`,B:`Osteomiyelitte süregen nötrofil infiltrasyonu görülebilir.`,C:`Mast hücreleri histamin, lökotrien ve sitokin salgılar.`,D:`Mast hücreleri hem akut hem kronik enflamasyona katılır.`,E:`Nötrofiller kronik enflamasyonda hiçbir koşulda bulunmaz.`},dogru:`E`,aciklama:`Nötrofiller akut enflamasyonun tipik hücresi olsa da osteomiyelit ve sigaraya bağlı akciğer hastalıkları gibi bazı kronik tablolarda süregen katılım gösterir.`,sik_aciklamalari:{A:`Doğru ifade; konak epiteline de zarar verebilir.`,B:`Doğru ifade: osteomiyelitte süregen nötrofil infiltrasyonu görülebilir.`,C:`Doğru ifade: mast hücreleri histamin, lökotrien ve sitokin salgılar.`,D:`Doğru ifade: mast hücreleri hem akut hem kronik enflamasyona katılır.`,E:`Yanlış ifade (aranan cevap). Nötrofiller akut enflamasyonun tipik hücresi olsa da osteomiyelit ve sigaraya bağlı akciğer hastalıkları gibi bazı kronik tablolarda süregen katılım gösterir.`},bilgi:[21,22,23],benzer_cikmis:[]},{id:`k1-13-q24`,kazanim:8,zorluk:`zor`,soru:`Uzun yıllardır sigara içen bir hastada kronik akciğer hastalığının biyopsisinde mononükleer hücrelerin yanında belirgin ve süregen nötrofil infiltrasyonu görülüyor.

Bu bulgu ile ilgili aşağıdakilerden hangisi en doğrudur?`,secenekler:{A:`Nötrofil varlığı lezyonun kesinlikle akut olduğunu gösterir.`,B:`Nötrofiller bazı kronik tablolarda (sigara ilişkili akciğer hastalığı, osteomiyelit) süregen olarak bulunabilir.`,C:`Bulgu eozinofilik pnömoniyi gösterir.`,D:`Nötrofiller kronik enflamasyonda yalnızca artefakttır.`,E:`Nötrofiller burada antikor üretmektedir.`},dogru:`B`,aciklama:`Kalıcı uyaran (sigara dumanı, nekrotik kemik) nötrofil alımını sürdürebilir; mononükleer hücrelerle birlikte karışık bir infiltrat görülür.`,sik_aciklamalari:{A:`Nötrofil varlığı tek başına lezyonun akut olduğunu kanıtlamaz.`,B:`Doğru. Kalıcı uyaran (sigara dumanı, nekrotik kemik) nötrofil alımını sürdürebilir; mononükleer hücrelerle birlikte karışık bir infiltrat görülür.`,C:`Eozinofilik tablo eozinofil baskınlığı gerektirir.`,D:`Nötrofiller gerçek bir infiltrat bileşenidir.`,E:`Nötrofiller antikor üretmez.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q04`,kazanim:8,zorluk:`orta`,soru:`26 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Eozinofil, nötrofil ve mast hücrelerinin kronik enflamasyondaki rolünü özetlemek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül… ilkesinin tam tersi geçerlidir ve Hem akut hem kronik enflamasyon süreçlerine katılır gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Mast hücreleri olup "Eozinofil, nötrofil ve mast hücrelerinin kronik…" ile ilişkisizdir`,C:`Bulgular "Eozinofil, nötrofil ve mast hücrelerinin kronik enflamasyondaki…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Eozinofiller" ile açıklanamaz`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir Bu nedenle Granüllerindeki major basic protein parazitler için toksiktir; konak epitel hücrelerine de zarar verir`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir Doğrudan sonucu "Granüllerindeki major basic protein parazitler için toksiktir; konak epitel hücrelerine de zarar verir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,E:`Doğru; IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan…`},bilgi:[21,22],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q05`,kazanim:8,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "Mast hücreleri" vurgulanıyor ve hekim "Eozinofil, nötrofil ve mast hücrelerinin kronik enflamasyondaki rolünü özetlemek" kazanımındaki "Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hem akut hem kronik enflamasyon süreçlerine katılır Çünkü Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Hem akut hem kronik enflamasyon süreçlerine katılır hiçbir koşulda gözlenmez ve Eozinofiller tek belirleyicidir`,C:`Bu süreçte "Eozinofiller" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Mast hücreleri" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Eozinofil, nötrofil ve mast hücrelerinin kronik enflamasyondaki…" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar sonucu "Hem akut hem kronik enflamasyon süreçlerine katılır" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Hem akut hem kronik enflamasyon süreçlerine katılır Çünkü Alerjik reaksiyonların ana hücresi; histamin,…`,B:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Eozinofiller" bilgisiyle çelişir.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Mast hücreleri: Alerjik reaksiyonların ana hücresi. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Hem akut hem kronik enflamasyon süreçlerine katılır`,B:`Treponema pallidum enfeksiyonunda hastalığın üçüncül evresinde görülür`,C:`Kalıcı doku yıkımı, fibrozis ve organ fonksiyon kaybı gelişir`,D:`Doku makrofaj havuzu inflamatuvar ve yerleşik popülasyonların karışımıdır`,E:`Makrofajların klasik (M1) aktivasyonunu uyarır`},dogru:`A`,aciklama:`Alerjik reaksiyonların ana hücresi. Hem akut hem kronik enflamasyon süreçlerine katılır. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Alerjik reaksiyonların ana hücresi doğrudan Hem akut hem kronik enflamasyon süreçlerine katılır doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Hem akut hem kronik enflamasyon süreçlerine katılır çünkü Alerjik reaksiyonların ana hücresi düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Sifilizde granülom (gumma) sürecine ait bir özelliktir ve mast hücreleri düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Kronik enflamasyonda baskın hücreler sürecine ait bir özelliktir ve mast hücreleri düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Makrofaj kökeni sürecine ait bir özelliktir ve mast hücreleri düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Th1 hücreleri sürecine ait bir özelliktir ve mast hücreleri düzeneğini tanımlamaz.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q07`,kazanim:8,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Nötrofillerin kronik tablolardaki katılımı mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Haftalar-aylar süren`,B:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve`,C:`Akut enflamasyonun tipik hücresidir`,D:`Fagositoz`,E:`Alerjik reaksiyonların ana hücresi`},dogru:`C`,aciklama:`Tıbbi Patoloji düzeneğinde Akut enflamasyonun tipik hücresidir bilinir. Osteomiyelit ve sigara ilişkili akciğer hastalıklarında süregen nötrofil görülür. Mekanizma bu sırayla işlediği için beklenen sonuç Osteomiyelit ve sigara ilişkili akciğer hastalıklarında süregen olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kronik enflamasyonun tanımı sürecine ait bir özelliktir ve nötrofillerin kronik tablolardaki katılımı düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Kronik enflamasyonun morfolojik özellikleri sürecine ait bir özelliktir ve nötrofillerin kronik tablolardaki katılımı düzeneğini tanımlamaz.`,C:`Doğru; Akut enflamasyonun tipik hücresidir. Bu mekanizma osteomiyelit ve sigara ilişkili akciğer hastalıklarında süregen nötrofil sonucunu doğurur.`,D:`Yanlış; bu ifade Makrofajların ana fonksiyonları sürecine ait bir özelliktir ve nötrofillerin kronik tablolardaki katılımı düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Mast hücreleri sürecine ait bir özelliktir ve nötrofillerin kronik tablolardaki katılımı düzeneğini tanımlamaz.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q08`,kazanim:8,zorluk:`orta`,soru:`Paraziter helmint enfeksiyonlarında ve alerjik reaksiyonlarda (örn. bronşiyal astım) doku infiltrasyonunun başrol oyuncusu olan; granüllerinde 'Majör Temel Protein' (MBP) içeren hücre aşağıdakilerden hangisidir?`,secenekler:{A:`Nötrofil`,B:`Eozinofil`,C:`Plazma hücresi`,D:`Kupffer hücresi`,E:`Trombosit`},dogru:`B`,aciklama:`Eozinofiller, IgE aracılı immün yanıtlarda ve paraziter helmint enfeksiyonlarında birincil savunma hücresidir. Kemik iliğinde IL-5 ile üretilir ve eotaksin kemokini ile dokuya çekilirler. Granüllerinde Majör Temel Protein (MBP), Eozinofil Katyonik Protein (ECP) ve Eozinofil Peroksidaz (EPO) bulunur. MBP parazitlerin kütikulasına toksiktir ancak bronş mukozasında da yoğun epitel nekrozu ve doku hasarı oluşturur.`,sik_aciklamalari:{A:`Nötrofil bakteriyel/akut hücredir, MBP içermez.`,B:`Doğrudur. Eozinofil paraziter ve alerjik reaksiyonlarda MBP ile doku hasarı yapan hücredir.`,C:`Plazma hücresi antikor üretir.`,D:`Kupffer karaciğer makrofajıdır.`,E:`Trombosit pıhtılaşma elemanıdır.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q09`,kazanim:8,zorluk:`orta`,soru:`Nötrofiller klasik olarak akut enflamasyon hücresi olmalarına rağmen, bazı KRONİK enflamatuar durumlarda aylarca dokuda persistan olarak bulunabilirler. 
Aşağıdakilerden hangisi kronik olmasına rağmen dokuda yoğun nötrofil birikimi ve püy oluşumu (kronik süpüratif enflamasyon) ile seyreden bir tablodur?`,secenekler:{A:`Kronik Osteomiyelit`,B:`Asemptomatik kalsifiye tüberküloz odağı`,C:`Hafif güneş yanığı`,D:`Deri skuamöz papillomu`,E:`Karaciğer kist hidatiği`},dogru:`A`,aciklama:`Nötrofiller persistan mikrobiyal enfeksiyonlarda (özellikle kemik enfeksiyonu olan Kronik Osteomiyelit, akciğer apsesi veya psödomonal kronik bronşiektazi) nekrotik kemik (sekestr) ve bakteriler varlığını sürdürdüğü için aylarca dokuya çekilmeye devam eder. Bu tabloya 'Kronik Süpüratif Enflamasyon' veya kronik zemininde akut alevlenme adı verilir.`,sik_aciklamalari:{A:`Doğrudur. Kronik osteomiyelit kronik mononükleer hücrelerle birlikte kalıcı nötrofil infiltrasyonu (püy) barındıran klasik örnektir.`,B:`Kalsifiye tüberkülozda nötrofil yoktur, fibröz/kazeöz skar vardır.`,C:`Güneş yanığı akut eritemdir.`,D:`Papillom benign epitelyal tümördür.`,E:`Kist hidatik paraziter kisttir, saf nötrofilik süpürasyon değildir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q10`,kazanim:8,zorluk:`zor`,soru:`Kronik enflamasyon alanlarında bulunan MAST HÜCRELERİNİN erken dönem histamin salınımının ötesinde, kronik doku remodelingi ve fibrozisteki rolü aşağıdakilerden hangisidir?`,secenekler:{A:`Sitokinler (TNF, IL-1), büyüme faktörleri (bFGF) ve triptaz salgılayarak fibroblast proliferasyonunu ve yara iyileşmesini/fibrozisi sürekli uyarmak`,B:`Sadece glikojen depolamak`,C:`Eritrositlerin içine girerek hemoglobin sentezlemek`,D:`Bakterilerin DNA'sını doğrudan klonlamak`,E:`Tüm ekstrasellüler kollajeni tamamen yok ederek skarı engellemek`},dogru:`A`,aciklama:`Mast hücreleri sadece akut alerjide değil kronik enflamasyonda da çok etkindir. Membrana bağlı de novo lipid mediyatörlerin yanı sıra TNF, IL-1, bFGF ve triptaz gibi mediyatörler üretirler. Triptaz fibroblastlardaki PAR-2 reseptörlerini uyararak fibroblast proliferasyonunu ve kollajen sentezini indükler. Skleroderma gibi fibrotik hastalıklarda ve yara onarımında mast hücreleri anahtar rol oynar.`,sik_aciklamalari:{A:`Doğrudur. Mast hücreleri sitokinler, FGF ve triptaz ile fibroblastları uyararak kronik fibrozise katkı sağlar.`,B:`Glikojen deposu değillerdir.`,C:`Hemoglobin eritrosit ürünüdür.`,D:`Bakteriyel genetik klonlama yapmazlar.`,E:`Kollajeni yok etmezler, fibrozisi tetiklerler.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q11`,kazanim:8,zorluk:`orta`,soru:`Alerjik astımlı bir hastanın bronş lavajında ve biyopsisinde saptanan Charcot-Leyden kristalleri hangi enflamatuar hücrenin parçalanması sonucu ortaya çıkan granül proteinlerinden (galektin-10) kaynaklanır?`,secenekler:{A:`Eozinofil`,B:`Nötrofil`,C:`Bazofil`,D:`Monosit`,E:`Plazma hücresi`},dogru:`A`,aciklama:`Charcot-Leyden kristalleri; astım, eozinofilik özofajit veya paraziter enfeksiyonlarda parçalanan Eozinofillerin membran ve lizofosfolipaz proteinlerinin (Galektin-10) heksagonal bikonik kristaller şeklinde çökelmesiyle oluşur. Eozinofilik doku yıkımının patognomonik morfolojik göstergesidir.`,sik_aciklamalari:{A:`Doğrudur. Charcot-Leyden kristalleri eozinofil kaynaklı lizofosfolipaz/galektin-10 proteinlerinden oluşur.`,B:`Nötrofil parçalanması bu kristalleri oluşturmaz.`,C:`Bazofil ana kaynak değildir.`,D:`Monosit kaynaklı değildir.`,E:`Plazma hücresi Russell cisimcikleri yapar.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q12`,kazanim:8,zorluk:`zor`,soru:`Kalıtsal veya edinsel kompleman eksikliği olmayan bir hastada, kronik granülomatöz hastalık (CGD) varlığında nötrofillerin fagositoz yapabilmesine rağmen mikropları hücre içinde öldürememesinin ve bu nedenle kronik granülomlar gelişmesinin biyokimyasal temeli nedir?`,secenekler:{A:`Fagositik NADPH oksidaz enzim kompleksinin genetik defekti ve serbest oksijen radikallerinin (oksidatif patlama) üretilememesi`,B:`Miyeloperoksidaz enziminin kanda aşırı yükselmesi`,C:`Lökosit integrinlerinin tamamen yok olması`,D:`Mast hücrelerinin kalsiyum alamaması`,E:`Kaspaz-1 geninin aşırı çalışması`},dogru:`A`,aciklama:`Kronik Granülomatöz Hastalık (CGD), fagositik NADPH oksidaz enzim kompleksini (özellikle gp91phox - CYBB geni) kodlayan genlerdeki mutasyonlar sonucu gelişir. Nötrofiller ve makrofajlar bakteriyi fagositozla yutarlar ancak serbest oksijen radikalleri (süperoksit, hidrojen peroksit vb.) üretemezler ('oksidatif patlama' gerçekleşemez). Katalaz-pozitif bakteriler (S. aureus, Aspergillus vb.) hücre içinde yaşar ve vücut bunları temizleyemediği için dokuda yaygın kronik granülomlar oluşur.`,sik_aciklamalari:{A:`Doğrudur. NADPH oksidaz defekti sonucu reaktif oksijen radikalleri üretilemez ve kronik granülomlar meydana gelir.`,B:`MPO fazlalığı değil, NADPH oksidaz yokluğudur.`,C:`Lökosit integrin eksikliği LAD sendromudur (nötrofil dokuya çıkamaz).`,D:`Mast hücresiyle doğrudan ilişkili değildir.`,E:`Kaspaz-1 inflamazom enzimidir, primer CGD defekti değildir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q13`,kazanim:8,zorluk:`kolay`,soru:`"Makrofaj kökeni" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,C:`IFN-γ üretir`,E:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,D:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,A:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},dogru:`B`,aciklama:`Doğru: İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,sik_aciklamalari:{B:`Doğru. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,C:`Yanlış. IFN-γ üretir`,E:`Yanlış. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,D:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,A:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},bilgi:[10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q14`,kazanim:8,zorluk:`orta`,soru:`"Kalıcı enfeksiyonlar" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,E:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,C:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,A:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`},dogru:`B`,aciklama:`Doğru: Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,sik_aciklamalari:{B:`Doğru. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,E:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,C:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,A:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`},bilgi:[5],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q15`,kazanim:8,zorluk:`orta`,soru:`"Aşırı duyarlılık (immün) hastalıkları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,A:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,B:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`Nötrofiller ve ödem`,E:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},dogru:`C`,aciklama:`Doğru: Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,sik_aciklamalari:{C:`Doğru. Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,A:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,B:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`,D:`Yanlış. Nötrofiller ve ödem`,E:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},bilgi:[6],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k08-q16`,kazanim:8,zorluk:`zor`,soru:`"Th1 hücreleri" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`IFN-γ üretir`,C:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,E:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,D:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`},dogru:`A`,aciklama:`Doğru: IFN-γ üretir`,sik_aciklamalari:{A:`Doğru. IFN-γ üretir`,C:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,E:`Yanlış. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,B:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,D:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`},bilgi:[17],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:9,metin:`Granülomatöz enflamasyonu tanımlamak ve granülom morfolojisini açıklamak`,sorular:[{id:`k1-13-q25`,kazanim:9,zorluk:`kolay`,soru:`Aktive makrofajların (epitelioid hücreler) nodüler kümeler oluşturduğu kronik enflamasyon tipine ne ad verilir?`,secenekler:{A:`Seröz enflamasyon`,B:`Fibrinöz enflamasyon`,C:`Granülomatöz enflamasyon`,D:`Pürülan enflamasyon`,E:`Ülseratif enflamasyon`},dogru:`C`,aciklama:`Granülomatöz enflamasyon kronik enflamasyonun özel tipidir; epitelioid hücre kümeleri çevresinde lenfosit halkası bulunur ve bazen merkezi nekroz vardır.`,sik_aciklamalari:{A:`Seröz enflamasyon hücreden fakir sıvı birikimidir.`,B:`Fibrinöz enflamasyon fibrin birikimidir.`,C:`Doğru. Granülomatöz enflamasyon kronik enflamasyonun özel tipidir; epitelioid hücre kümeleri çevresinde lenfosit halkası bulunur ve bazen merkezi nekroz vardır.`,D:`Pürülan enflamasyon irin oluşumudur.`,E:`Ülser epitel yüzeyinin lokal kaybıdır.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-13-q26`,kazanim:9,zorluk:`orta`,soru:`Granülom morfolojisi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Epitelioid hücreler bol, pembe, granüler sitoplazmalı ve hücre sınırları belirsizdir; Langhans dev hücrelerinde çekirdekler periferde taç şeklinde dizilir.`,B:`Granülom yalnızca nötrofillerden oluşur.`,C:`Langhans dev hücrelerinde çekirdekler merkezde kümelenir.`,D:`Granülom çevresinde lenfosit bulunmaz.`,E:`Granülomlar asla fibrozisle sonuçlanmaz.`},dogru:`A`,aciklama:`Granülomda epitelioid hücreler, Langhans tipi dev hücreler ve çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikir.`,sik_aciklamalari:{A:`Doğru. Granülomda epitelioid hücreler, Langhans tipi dev hücreler ve çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikir.`,B:`Granülomun temel hücresi aktive makrofajdır (epitelioid hücre).`,C:`Langhans hücrelerinde çekirdekler periferde at nalı/taç şeklindedir.`,D:`Çevrede lenfosit halkası tipiktir.`,E:`Granülomlar zamanla fibrozisle iyileşir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-13-q27`,kazanim:9,zorluk:`zor`,soru:`Granülomatöz enflamasyonda makrofajların epitelioid hücrelere dönüşmesinin temel uyaranı aşağıdakilerden hangisidir?`,secenekler:{A:`Kalıcı antijene karşı gelişen güçlü T hücre yanıtı ve IFN-γ üretimi`,B:`Histamin salınımı`,C:`Kompleman C3b birikimi`,D:`Nötrofillerin NET oluşturması`,E:`Hiperkalsemi`},dogru:`A`,aciklama:`Kalıcı mikrobiyal antijen T hücrelerini uyarır; IFN-γ makrofajları aktive ederek epitelioid hücrelere dönüştürür. Granülom etkeni izole etmeye yönelik bir stratejidir.`,sik_aciklamalari:{A:`Doğru. Kalıcı mikrobiyal antijen T hücrelerini uyarır; IFN-γ makrofajları aktive ederek epitelioid hücrelere dönüştürür. Granülom etkeni izole etmeye yönelik bir stratejidir.`,B:`Histamin erken vasküler değişikliklerin mediyatörüdür.`,C:`C3b opsonindir; epitelioid dönüşümü sağlamaz.`,D:`NET'ler nötrofil kaynaklıdır.`,E:`Hiperkalsemi metastatik kalsifikasyon yapar.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q04`,kazanim:9,zorluk:`orta`,soru:`33 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Granülomatöz enflamasyonu tanımlamak ve granülom morfolojisini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması Bu nedenle Sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz (özellikle tüberkülozda)`,B:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler… ilkesinin tam tersi geçerlidir ve Çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikimi (fibrozis)… gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Granülom morfolojisi olup "Granülomatöz enflamasyonu tanımlamak ve granülom…" ile ilişkisizdir`,D:`Bulgular "Granülomatöz enflamasyonu tanımlamak ve granülom morfolojisini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Granülomatöz enflamasyonun tanımı" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması Doğrudan sonucu "Sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz (özellikle tüberkülozda)" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler…`,B:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`},bilgi:[24,25],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q05`,kazanim:9,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Granülom morfolojisi" vurgulanıyor ve hekim "Granülomatöz enflamasyonu tanımlamak ve granülom morfolojisini açıklamak" kazanımındaki "Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikimi (fibrozis) gelişir hiçbir koşulda gözlenmez ve Granülomatöz enflamasyonun tanımı tek belirleyicidir`,B:`Çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikimi (fibrozis) gelişir Çünkü Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde…`,C:`Bu süreçte "Granülomatöz enflamasyonun tanımı" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Granülom morfolojisi" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Granülomatöz enflamasyonu tanımlamak ve granülom morfolojisini…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde sonucu "Çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikimi (fibrozis) gelişir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,B:`Doğru; Çevrede lenfositler bulunur; zamanla fibroblast ve kollajen birikimi (fibrozis) gelişir Çünkü Epiteloid…`,C:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun tanımı" bilgisiyle çelişir.`},bilgi:[24,25],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q06`,kazanim:9,zorluk:`orta`,soru:`Granülom morfolojisi: Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardit gelişebilir`,B:`Çevrede lenfositler bulunur`,C:`Tekrarlayan ataklar, karışık akut+kronik enflamasyon ve geç evrede fibrozis baskınlığı`,D:`Doku onarımı ve fibrozis (anjiyogenez, fibroblast aktivasyonu, kollajen sentezi) ile`,E:`Pozitif geri besleme döngüsü kronik enflamasyonun sürdürülmesinde önemlidir`},dogru:`B`,aciklama:`Tıbbi Patoloji düzeneğinde Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve bilinir. Çevrede lenfositler bulunur. Mekanizma bu sırayla işlediği için beklenen sonuç Çevrede lenfositler bulunur olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kronik enflamasyon ve fibrozis sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,B:`Doğru; Çevrede lenfositler bulunur çünkü Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade Aşırı duyarlılık (immün) hastalıkları sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Alternatif (M2) makrofaj aktivasyonu sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Lenfosit-makrofaj döngüsü sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`},bilgi:[25],benzer_cikmis:[`96c5c762df10`]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q07`,kazanim:9,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Granülomatöz enflamasyonun tanımı mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile`,B:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde`,C:`Eozinofil aktivasyonu yapar`,D:`Kronik enflamasyonun özel bir tipi`,E:`Merkezi nekroz alanı`},dogru:`D`,aciklama:`Kronik enflamasyonun özel bir tipi. Sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz (özellikle tüberkülozda). Fizyopatolojik sıra bu yönde ilerlediğinden Kronik enflamasyonun özel bir tipi varlığında Sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kronik enflamasyonun üç histolojik özelliği sürecine ait bir özelliktir ve granülomatöz enflamasyonun tanımı düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Yerleşik makrofaj isimleri sürecine ait bir özelliktir ve granülomatöz enflamasyonun tanımı düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Th2 hücreleri sürecine ait bir özelliktir ve granülomatöz enflamasyonun tanımı düzeneğini tanımlamaz.`,D:`Doğru; Kronik enflamasyonun özel bir tipi. Bu mekanizma sıklıkla çevresinde lenfosit halkası, bazen merkezi nekroz (özellikle sonucunu doğurur.`,E:`Yanlış; bu ifade Kazeöz (kazeifiye) granülom sürecine ait bir özelliktir ve granülomatöz enflamasyonun tanımı düzeneğini tanımlamaz.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q08`,kazanim:9,zorluk:`orta`,soru:`Granülomatöz enflamasyonun temel yapı taşı olan bir 'Granülom'un mikroskopik incelemesinde yer alan 'Epiteloid Histiyosit' (Epiteloid Hücre) kavramı aşağıdakilerden hangisini tanımlar?`,secenekler:{A:`Deri skuamöz epitelinin malign dönüşüme uğramış halini`,B:`İnterferon-gama ile yoğun şekilde aktive olmuş; geniş, soluk pembe (eozinofilik) granüler sitoplazmalı, oval veziküler çekirdekli ve epitel hücrelerine benzeyen modifiye makrofajları`,C:`Kemik iliğinde olgunlaşmamış eritroblastları`,D:`Fibroblastların kıkırdak hücresine dönüşmesini`,E:`Damar endotelinin lümene doğru dökülmesini`},dogru:`B`,aciklama:`Granülomun tanısal hücresi Epiteloid Histiyosittir. Epiteloid histiyositler gerçek epitel hücresi değildir; Th1 kaynaklı IFN-γ uyarısıyla aşırı derecede aktive olmuş modifiye makrofajlardır. Bol eozinofilik (pembe) granüler sitoplazmaları, belirsiz hücre sınırları ve oval/terliksi veziküler nükleusları ile mikroskopta epitel hücrelerini andırdıkları için bu adı alırlar. Fagositoz kapasiteleri azalmış, sekretuar kapasiteleri artmıştır.`,sik_aciklamalari:{A:`Skuamöz malign epitel değildir; makrofaj kökenlidir.`,B:`Doğrudur. IFN-γ ile aktive, geniş eozinofilik sitoplazmalı modifiye makrofajlardır.`,C:`Eritroblast kemik iliği hücresidir.`,D:`Kıkırdak hücresi değildir.`,E:`Endotel dökülmesi değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q09`,kazanim:9,zorluk:`orta`,soru:`Bir granülom odağında birden fazla epiteloid histiyositin sitoplazmalarının birleşmesiyle (füzyonuyla) oluşan ve çekirdekleri hücrenin periferinde 'at nalı' (U harfi) şeklinde dizilen karakteristik multinükleer dev hücreye ne ad verilir?`,secenekler:{A:`Langhans tipi dev hücre`,B:`Yabancı cisim tipi dev hücre`,C:`Touton tipi dev hücre`,D:`Osteoklastik dev hücre`,E:`Reed-Sternberg hücresi`},dogru:`A`,aciklama:`Langhans tipi multinükleer dev hücreler, epiteloid histiyositlerin füzyonuyla meydana gelir. Tipik olarak çekirdekleri hücre periferinde yarım ay veya 'at nalı' şeklinde dizilir. Tüberküloz, lepra ve sarkoidoz gibi immün granülomlarda sıkça görülür. Çekirdeklerin dağınık olduğu dev hücreler 'yabancı cisim', lipid halkası içerenler 'Touton' dev hücresidir.`,sik_aciklamalari:{A:`Doğrudur. Çekirdekleri at nalı şeklinde dizilen multinükleer dev hücre Langhans tipi dev hücredir.`,B:`Yabancı cisim dev hücresinde çekirdekler sitoplazmada düzensiz dağınıktır.`,C:`Touton dev hücresi ksantomalarda görülür, nükleus etrafında lipid halkası vardır.`,D:`Osteoklastik dev hücre kemikte veya kemik tümörlerindedir.`,E:`Reed-Sternberg Hodgkin lenfomanın çift nükleuslu neoplastik hücresidir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q10`,kazanim:9,zorluk:`zor`,soru:`Tipik bir immün granülomun tabakalanması merkezden perifere doğru incelendiğinde, hücresel organizasyonun doğru sıralaması aşağıdakilerden hangisidir?`,secenekler:{A:`Merkezde antijen/nekroz → Çevresinde epiteloid histiyositler ve dev hücreler → Dışta lenfosit (T hücre) kuşağı → En dışta fibroblast ve kollajen lifleri`,B:`Merkezde saf nötrofiller → Çevresinde sadece eritrositler → Dışta düz kas hücreleri`,C:`Merkezde kemik iliği → Çevresinde yağ dokusu → Dışta sinir lifleri`,D:`Merkezde mast hücreleri → Çevresinde eozinofiller → Dışta bazofiller`,E:`Merkezde fibrinoid nekroz → Çevresinde skuamöz epitel → Dışta trombositler`},dogru:`A`,aciklama:`Granülom, temizlenemeyen bir ajanı çevreleyip hapsetmeyi amaçlayan organize hücresel kümedir. Merkezde etken/antijen veya kazeifikasyon nekrozu yer alır. Bunu çevreleyen ana tabaka epiteloid histiyositler ve Langhans dev hücreleridir. Onların etrafında T lenfositleri (özellikle CD4+) ve plazma hücrelerinden oluşan bir hücresel manto (yaka/kuşak) bulunur. En dışta ise lezyonu sınırlayan fibroblastik proliferasyon ve fibröz bağ dokusu kapsülü yer alır.`,sik_aciklamalari:{A:`Doğrudur. Merkezde nekroz/antijen → Epiteloid histiyosit/dev hücre → Lenfosit kuşağı → Fibröz kapsül klasik granülom mimarisidir.`,B:`Nötrofil-eritrosit dizilimi granülom mimarisi değildir.`,C:`Kemik iliği organizasyonu değildir.`,D:`Granülomun temel hücresi epiteloid makrofajdır, mast/bazofil değildir.`,E:`Skuamöz epitel granülomda bulunmaz.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q11`,kazanim:9,zorluk:`orta`,soru:`Granülomatöz enflamasyonun organizma açısından temel fizyopatolojik amacı nedir?`,secenekler:{A:`Dolaşımdaki tüm eritrositleri parçalayarak sarılık oluşturmak`,B:`Fagosite edilip de bir türlü sindirilemeyen veya temizlenemeyen persistan etkenleri (mikrop, yabancı cisim) hücresel bir duvarla hapsederek vücudun diğer bölgelerine yayılmasını önlemek`,C:`Tüm periferik sinir iletimini kalıcı olarak kesmek`,D:`Karaciğerde pıhtılaşma faktörlerinin sentezini durdurmak`,E:`Kemiklerde kontrolsüz kalsiyum emilimi başlatmak`},dogru:`B`,aciklama:`Granülom oluşumu koruyucu bir savunma adaptasyonudur. Nötrofiller ve standart makrofajlar fagositozla yok edemedikleri dirençli bir mikropla (M. tuberculosis) veya inorganik partikülle (dikiş ipliği, silika) karşılaştıklarında, ajanı hücresel bir bariyerle (epiteloid hücreler ve fibröz doku) izole ederler (sekestrasyon/hapsolma). Bu sayede etkenin vücuda dissemine olması engellenir.`,sik_aciklamalari:{A:`Eritrosit parçalamak granülomun amacı değildir.`,B:`Doğrudur. Temizlenemeyen ajanın etrafına hücresel duvar örerek hapsedilmesi ve yayılmasının engellenmesidir.`,C:`Sinir iletimini kesmek amaç değildir.`,D:`Koagülasyonu durdurmak değildir.`,E:`Kemik metabolizması primer hedef değildir.`},bilgi:[9,13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q12`,kazanim:9,zorluk:`zor`,soru:`Histopatolojik kesitlerde epiteloid histiyositlerin fagositoz yeteneğinin normal doku makrofajlarına göre daha DÜŞÜK olmasının, buna karşın hangi hücresel özelliğinin aşırı gelişmiş olmasının sebebi sitoplazmalarındaki bol endoplazmik retikulum ve Golgi aygıtıdır?`,secenekler:{A:`Aktif protein ve sitokin sekresyonu (sekretuar kapasite)`,B:`Mitoz bölünmeyle sperm hücresi üretme`,C:`Saf kalsiyum minerali depolama`,D:`Nörotransmiter depolayarak elektriksel aksiyon potansiyeli üretme`,E:`Glikojen depolarını yağa dönüştürme`},dogru:`A`,aciklama:`Epiteloid histiyositler fagositoz yeteneklerini büyük oranda kaybedip sekretuar hücrelere dönüşmüşlerdir. Elektron mikroskobunda sitoplazmalarında fagozomlardan çok zengin granüler endoplazmik retikulum, geniş Golgi aygıtı ve çok sayıda sekretuar vezikül izlenir. Sürekli olarak TNF, IL-1, kemokinler, lizozim ve fibroblast büyüme faktörleri salgılarlar.`,sik_aciklamalari:{A:`Doğrudur. Epiteloid histiyositler fagositozdan ziyade aktif sekresyon (sitokin/enzim salgısı) yapan modifiye hücrelerdir.`,B:`Gamet hücresi üretemezler.`,C:`Kalsiyum depolayıcı mineral deposu değillerdir.`,D:`Sinir hücresi değillerdir.`,E:`Yağ dönüşümü temel amaç değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q13`,kazanim:9,zorluk:`kolay`,soru:`Aşağıdakilerden "Kazeöz (kazeifiye) granülom" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,E:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,B:`IFN-γ üretir`,C:`Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde`,A:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`},dogru:`D`,aciklama:`Doğru: Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,sik_aciklamalari:{D:`Doğru. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,E:`Yanlış. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,B:`Yanlış. IFN-γ üretir`,C:`Yanlış. Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde`,A:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q14`,kazanim:9,zorluk:`orta`,soru:`"Granülomların klinik önemi ve tanısı" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,D:`Nötrofiller ve ödem`,B:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,C:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`IFN-γ üretir`},dogru:`A`,aciklama:`Doğru: Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,sik_aciklamalari:{A:`Doğru. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,D:`Yanlış. Nötrofiller ve ödem`,B:`Yanlış. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,C:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Yanlış. IFN-γ üretir`},bilgi:[33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q15`,kazanim:9,zorluk:`orta`,soru:`"Yabancı cisim granülomları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,C:`Nötrofiller ve ödem`,D:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,A:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`},dogru:`E`,aciklama:`Doğru: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,sik_aciklamalari:{E:`Doğru. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,C:`Yanlış. Nötrofiller ve ödem`,D:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,A:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k09-q16`,kazanim:9,zorluk:`zor`,soru:`"M1 ve M2 dengesi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,A:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Merkezi nekroz yoktur`,C:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},dogru:`E`,aciklama:`Doğru: Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,sik_aciklamalari:{E:`Doğru. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,A:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Yanlış. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Yanlış. Merkezi nekroz yoktur`,C:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},bilgi:[14],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:10,metin:`Kazeifiye ve non-kazeifiye granülomları ayırt etmek`,sorular:[{id:`k1-13-q28`,kazanim:10,zorluk:`kolay`,soru:`Merkezi kazeöz (peynirimsi) nekroz içeren granülomların tipik örneği aşağıdakilerden hangisidir?`,secenekler:{A:`Sarkoidoz`,B:`Crohn hastalığı`,C:`Tüberküloz`,D:`Dikiş materyali granülomu`,E:`Talk granülomu`},dogru:`C`,aciklama:`Kazeöz granülomun tipik örneği tüberkülozdur; sarkoidoz, Crohn ve çoğu yabancı cisim granülomu non-kazeözdür.`,sik_aciklamalari:{A:`Sarkoidoz non-kazeöz granülom oluşturur.`,B:`Crohn hastalığı non-kazeöz granülom oluşturur.`,C:`Doğru. Kazeöz granülomun tipik örneği tüberkülozdur; sarkoidoz, Crohn ve çoğu yabancı cisim granülomu non-kazeözdür.`,D:`Yabancı cisim granülomları genellikle non-kazeözdür.`,E:`Talk granülomu yabancı cisim granülomudur.`},bilgi:[26,27],benzer_cikmis:[]},{id:`k1-13-q29`,kazanim:10,zorluk:`orta`,soru:`Aşağıdakilerin hangisinde non-kazeöz (nekrozsuz) granülom beklenir?`,secenekler:{A:`Akciğer tüberkülozu`,B:`Sarkoidoz`,C:`Tüberküloz lenfadeniti`,D:`Kazeifiye tüberküloz odağı`,E:`Miliyer tüberküloz`},dogru:`B`,aciklama:`Non-kazeöz granülomlar sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür.`,sik_aciklamalari:{A:`Tüberküloz kazeöz granülom oluşturur.`,B:`Doğru. Non-kazeöz granülomlar sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür.`,C:`Tüberküloz lenfadenitinde kazeöz granülom beklenir.`,D:`Tanımı gereği kazeöz nekroz içerir.`,E:`Tüberkülozun yaygın formudur; kazeöz granülom beklenir.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-13-q30`,kazanim:10,zorluk:`zor`,soru:`Kazeöz granülomun merkezindeki nekrozun mikroskopik görünümü aşağıdakilerden hangisidir?`,secenekler:{A:`Hücre konturlarının korunduğu, çekirdeksiz eozinofilik hücreler`,B:`Amorf, eozinofilik, granüler materyal; doku mimarisi ve hücre sınırları kaybolmuş`,C:`Gölgeli yağ hücreleri ve bazofilik kalsiyum sabunları`,D:`Damar duvarında parlak pembe camsı materyal`,E:`Sıvılaşmış nötrofil yığınları`},dogru:`B`,aciklama:`Kazeöz nekroz makroskopik olarak peynirimsi, mikroskopik olarak amorf granüler pembe materyaldir; hücre sınırları seçilemez.`,sik_aciklamalari:{A:`Hücre konturlarının korunması koagülatif nekroza aittir.`,B:`Doğru. Kazeöz nekroz makroskopik olarak peynirimsi, mikroskopik olarak amorf granüler pembe materyaldir; hücre sınırları seçilemez.`,C:`Bu yağ nekrozunun görünümüdür.`,D:`Bu fibrinoid nekrozdur.`,E:`Bu likefaksiyon nekrozu/apsedir.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q04`,kazanim:10,zorluk:`orta`,soru:`40 yaşındaki bir hasta yıllardır süren yakınmalarla başvuran ve fizik muayenede tipik bulguları saptanan bir hastada hekime başvuruyor. Değerlendirmede "Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Kazeifiye ve non-kazeifiye granülomları ayırt etmek" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik… ilkesinin tam tersi geçerlidir ve Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür gözlenmez`,B:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal Bu nedenle Tipik örneği tüberkülozdur`,C:`Bu tablodan sorumlu temel mekanizma Non-kazeöz granülom olup "Kazeifiye ve non-kazeifiye granülomları ayırt etmek" ile ilişkisizdir`,D:`Bulgular "Kazeifiye ve non-kazeifiye granülomları ayırt etmek" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Kazeöz (kazeifiye) granülom" ile açıklanamaz`},dogru:`B`,aciklama:`Robbins/Harrison mantığıyla: Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal Doğrudan sonucu "Tipik örneği tüberkülozdur" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,B:`Doğru; Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler…`,C:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`},bilgi:[26,27],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q05`,kazanim:10,zorluk:`zor`,soru:`Farklı bir hasta tedavi seçeneğinin tartışıldığı farklı bir klinik senaryoda ele alınıyor. Öyküde "Non-kazeöz granülom" vurgulanıyor ve hekim "Kazeifiye ve non-kazeifiye granülomları ayırt etmek" kazanımındaki "Merkezi nekroz yoktur" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür hiçbir koşulda gözlenmez ve Kazeöz (kazeifiye) granülom tek belirleyicidir`,B:`Bu süreçte "Kazeöz (kazeifiye) granülom" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür Çünkü Merkezi nekroz yoktur`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Non-kazeöz granülom" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Kazeifiye ve non-kazeifiye granülomları ayırt etmek" yalnızca teorik bir bilgidir`},dogru:`C`,aciklama:`Guyton/Robbins bütünlüğünde: Merkezi nekroz yoktur sonucu "Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,C:`Doğru; Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür Çünkü Merkezi nekroz yoktur`,D:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kazeöz (kazeifiye) granülom" bilgisiyle çelişir.`},bilgi:[26,27],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q06`,kazanim:10,zorluk:`orta`,soru:`Non-kazeöz granülom: Merkezi nekroz yoktur. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Genelde tam iyileşme veya basit skar ile sonlanır`,B:`Mikrop ve nekrotik doku fagositozu, sitokin ve büyüme faktörü salgısı,`,C:`Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür`,D:`B hücreleri ve plazma hücreleri antikor üretir`,E:`Hem akut hem kronik enflamasyon süreçlerine katılır`},dogru:`C`,aciklama:`Merkezi nekroz yoktur. Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür. Fizyopatolojik sıra bu yönde ilerlediğinden Merkezi nekroz yoktur varlığında Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Akut enflamasyonda baskın hücre sürecine ait bir özelliktir ve non-kazeöz granülom düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Makrofajın merkezi rolü sürecine ait bir özelliktir ve non-kazeöz granülom düzeneğini tanımlamaz.`,C:`Doğru; Sarkoidoz, Crohn hastalığı ve bazı yabancı cisim granülomlarında görülür çünkü Merkezi nekroz yoktur düzeneği bu sonucu üretir.`,D:`Yanlış; bu ifade Lenfositlerin rolü sürecine ait bir özelliktir ve non-kazeöz granülom düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Mast hücreleri sürecine ait bir özelliktir ve non-kazeöz granülom düzeneğini tanımlamaz.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q07`,kazanim:10,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Kazeöz (kazeifiye) granülom mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma)`,B:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır`,C:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar`,D:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş`,E:`Merkezi nekroz alanı`},dogru:`E`,aciklama:`Merkezi nekroz alanı. Tipik örneği tüberkülozdur. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Merkezi nekroz alanı doğrudan Tipik örneği tüberkülozdur doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Uzun süreli toksik maruziyet sürecine ait bir özelliktir ve kazeöz (kazeifiye) granülom düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade M1 ve M2 dengesi sürecine ait bir özelliktir ve kazeöz (kazeifiye) granülom düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Eozinofiller sürecine ait bir özelliktir ve kazeöz (kazeifiye) granülom düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Yabancı cisim granülomları sürecine ait bir özelliktir ve kazeöz (kazeifiye) granülom düzeneğini tanımlamaz.`,E:`Doğru; Merkezi nekroz alanı. Bu mekanizma tipik örneği tüberkülozdur sonucunu doğurur.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q08`,kazanim:10,zorluk:`orta`,soru:`Tüberküloz enfeksiyonunda izlenen 'Kazeifikasyon Nekrozu'nun makroskopik ve mikroskopik karakteristik özellikleri ile ilgili aşağıdakilerden hangisi DOĞRUDUR?`,secenekler:{A:`Makroskopik olarak peynirimsi, sarı-beyaz, ufalanabilir; mikroskopik olarak hücresel sınırların tamamen kaybolduğu asellüler, homojen, eozinofilik granüler debris`,B:`Makroskopik olarak şeffaf sıvı ile dolu kist; mikroskopik olarak sağlam nötrofiller`,C:`Makroskopik olarak siyah taş kıvamında doku; mikroskopik olarak yoğun yağ nekrozu`,D:`Sadece kan pıhtısından ibaret bir lezyon`,E:`Tamamen canlı bakteri kolonilerinden oluşan saf mukus tabakası`},dogru:`A`,aciklama:`Kazeifikasyon nekrozu (peynirleşme nekrozu): Makroskopik olarak yumuşak, sarı-beyaz, kuru ve peyniri andıran (caseous) bir görünümdedir. Mikroskopik olarak hücresel detaylar ve hücre sınırları tamamen silinmiştir; nükleer döküntüler (karyoreksis) içeren amorf, asellüler, granüler pembe (eozinofilik) bir nekroz alanı izlenir.`,sik_aciklamalari:{A:`Doğrudur. Peynirimsi makroskopi ve asellüler eozinofilik granüler mikroskopi kazeifikasyonun temelidir.`,B:`Kistik berrak sıvı seröz kisttir, kazeifikasyon değildir.`,C:`Siyah taş kıvamında lezyon değildir.`,D:`Kan pıhtısı değildir.`,E:`Canlı mukus tabakası değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q09`,kazanim:10,zorluk:`orta`,soru:`Aşağıdaki hastalıklardan hangisi merkezinde kazeifikasyon nekrozu İÇERMEYEN 'Non-kazeifiye (sert) granülomlar' ile karakterizedir?`,secenekler:{A:`Akciğer Tüberkülozu`,B:`Sarkoidoz`,C:`Tüberküloz Lenfadeniti (Scrofuloderma)`,D:`Kazeifiye Renal Tüberküloz`,E:`Kavitary Tüberküloz Pnömonisi`},dogru:`B`,aciklama:`Sarkoidoz, Crohn hastalığı, berilyozis ve yabancı cisim reaksiyonları merkezlerinde kazeifikasyon nekrozu barındırmayan 'Non-kazeifiye Granülom' prototipleridir. Mikroskopide granülom merkezinde nekroz bulunmaz; epiteloid histiyositler ve dev hücreler sıkıca bir arada durur ('sert granülom'). Tüberküloz formlarında ise merkezde nekroz kuraldır ('yumuşak/kazeifiye granülom').`,sik_aciklamalari:{A:`Akciğer tüberkülozu klasik kazeifiye granülomdur.`,B:`Doğrudur. Sarkoidoz non-kazeifiye (nekrozsuz) epiteloid granülomların klasik prototipidir.`,C:`Tüberküloz lenfadeniti kazeöz nekroz içerir.`,D:`Renal tüberküloz kazeözdür.`,E:`Kavitary tüberküloz kazeifikasyonun likefiye olup boşalmasıdır.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q10`,kazanim:10,zorluk:`zor`,soru:`Kazeifiye granülom ile non-kazeifiye granülom patogenetik ve etiyolojik açıdan karşılaştırıldığında, granülom merkezinde kazeöz nekroz gelişmesini belirleyen temel faktör nedir?`,secenekler:{A:`Trombositlerin damarları tıkaması sonucu sadece venöz enfarktüs olması`,B:`Mikobakteriyel hücre duvar lipidleri (kord faktörü) ve aşırı Th1 immün yanıtı zemininde yüksek düzeyde TNF-α salınımı, lökosit lizisi ve iskemik doku hasarının birleşmesi`,C:`Dokuda histamin konsantrasyonunun sıfıra inmesi`,D:`Sadece hastanın kan grubunun Rh negatif olması`,E:`Tübüllerdeki kalsiyum kanallarının mutasyonu`},dogru:`B`,aciklama:`Kazeifikasyon nekrozu, canlı mikroba karşı gelişen aşırı gecikmiş tip aşırı duyarlık yanıtının bir sonucudur. Mikobakteri lipitleri (kord faktörü / trehaloz dimikolat), aktive makrofajlardan yüksek miktarda TNF-α ve reaktif oksijen/azot radikalleri salgılatır. Bu toksik mikroçevre ve merkezdeki vasküler yetersizlik/iskemi hem mikropları hem de konak hücrelerini öldürerek hücre detaylarının eridiği kazeöz nekroza yol açar. Sarkoidoz gibi durumlarda bu şiddetli litik immün hasar olmadığından nekroz oluşmaz.`,sik_aciklamalari:{A:`Sadece mekanik venöz enfarktüs değildir.`,B:`Doğrudur. Mikobakteri lipidleri, aşırı Th1 yanıtı, yüksek TNF-α ve iskemi birleşerek kazeöz nekrozu oluşturur.`,C:`Histamin eksikliği nekroz nedeni değildir.`,D:`Kan grubuyla doğrudan ilişkisi yoktur.`,E:`Kalsiyum kanal mutasyonuyla ilgili değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q11`,kazanim:10,zorluk:`orta`,soru:`Otuz beş yaşında kadın hasta persistan kuru öksürük ve nefes darlığı ile başvuruyor. Toraks BT'de bilateral hiler lenfadenopati ve akciğer parankiminde retikülonodüler infiltratlar izleniyor. Yapılan transbronşiyal akciğer biyopsisinde merkezinde nekroz bulunmayan, multinükleer dev hücreler ve epiteloid histiyositlerden oluşan iyi sınırlı granülomlar saptanıyor. 
Bu hastada en olası tanı aşağıdakilerden hangisidir?`,secenekler:{A:`Sarkoidoz`,B:`Miliyer Tüberküloz`,C:`Akut bakteriyel bronkopnömoni`,D:`Akciğer adenokarsinomu`,E:`Astım bronşiale`},dogru:`A`,aciklama:`Genç-orta yaşta bilateral hiler lenfadenopati ve biyopside 'non-kazeifiye epiteloid granülomlar' izlenmesi Sarkoidoz için klasik klinik-patolojik tablodur. Tüberkülozda kazeöz nekroz beklenir; karsinomda atipik malign hücreler vardır; pnömonide ise granülom değil nötrofilik eksüda bulunur.`,sik_aciklamalari:{A:`Doğrudur. Bilateral hiler lenfadenopati + non-kazeifiye granülom = Sarkoidoz.`,B:`Miliyer tüberkülozda yaygın kazeöz nekrozlu granülomlar ve ARB pozitifliği vardır.`,C:`Bakteriyel pnömonide granülom oluşmaz, alveolar nötrofil birikir.`,D:`Karsinom epitelyal malign neoplazmdır.`,E:`Astımda eozinofil ve mukus tıkaçları vardır, granülom yoktur.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q12`,kazanim:10,zorluk:`zor`,soru:`Crohn hastalığı ile Ülseratif Kolit'in ayırıcı tanısında endoskopik biyopsilerin histopatolojik incelenmesinde Crohn hastalığı lehine olan en karakteristik granülomatöz bulgu hangisidir?`,secenekler:{A:`Mukozada ve submukozada dağınık yerleşimli, kazeifikasyon nekrozu içermeyen küçük mikrogranülomlar`,B:`Kript abseleri içinde serbest nötrofiller`,C:`Sadece mukozada sınırlı ülserler`,D:`Yaygın amiloidoz plakları`,E:`Tüm barsak duvarında kazeöz kavitasyon`},dogru:`A`,aciklama:`Crohn hastalığı tüm barsak duvarını transmural olarak tutar ve olguların yaklaşık %40-60'ında submukoza veya mukozada non-kazeifiye (nekrozsuz) epiteloid granülomlar izlenir. Bu granülomların saptanması Ülseratif Kolit'ten (granülom içermez, sadece mukoza/submukoza ile sınırlıdır ve kript apseleri ön plandadır) ayrımda patognomoniktir.`,sik_aciklamalari:{A:`Doğrudur. Non-kazeifiye mikrogranülomlar Crohn hastalığı için son derece karakteristiktir.`,B:`Kript apseleri her iki enflamatuar barsak hastalığında da görülebilir, ÜK'de daha yoğundur.`,C:`Mukozayla sınırlı ülserler Ülseratif Kolit özelliğidir.`,D:`Amiloidoz spesifik ayırıcı granülom bulgusu değildir.`,E:`Crohn'da kazeöz kavitasyon olmaz; kazeöz nekroz tüberküloza aittir.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q13`,kazanim:10,zorluk:`kolay`,soru:`"Kazeöz (kazeifiye) granülom" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,D:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,B:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Merkezi nekroz yoktur`,A:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},dogru:`C`,aciklama:`Doğru: Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,sik_aciklamalari:{C:`Doğru. Merkezi nekroz alanı; makroskopik olarak peynir benzeri, mikroskopik olarak amorf, eozinofilik granüler materyal`,D:`Yanlış. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,B:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Yanlış. Merkezi nekroz yoktur`,A:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`},bilgi:[26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q14`,kazanim:10,zorluk:`orta`,soru:`"Granülomatöz enflamasyonun tanımı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,C:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`},dogru:`B`,aciklama:`Doğru: Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,sik_aciklamalari:{B:`Doğru. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,D:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,C:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,E:`Yanlış. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`},bilgi:[24],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q15`,kazanim:10,zorluk:`orta`,soru:`"Granülomların klinik önemi ve tanısı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,A:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,B:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,E:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},dogru:`C`,aciklama:`Doğru: Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,sik_aciklamalari:{C:`Doğru. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,A:`Yanlış. İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi) türetilir; bazı yerleşik makrofajlar embriyonik öncüllerden (vitellus kesesi, fetal karaciğer)`,B:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,E:`Yanlış. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,D:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`},bilgi:[33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k10-q16`,kazanim:10,zorluk:`zor`,soru:`"Kronik enflamasyon ve fibrozis" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,C:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,B:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},dogru:`A`,aciklama:`Doğru: Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,sik_aciklamalari:{A:`Doğru. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,C:`Yanlış. Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür`,E:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,B:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`},bilgi:[34],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:11,metin:`Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık örneklerini açıklamak`,sorular:[{id:`k1-13-q31`,kazanim:11,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi granülomatöz enflamasyona yol açan hastalıklardan biri değildir?`,secenekler:{A:`Tüberküloz`,B:`Sarkoidoz`,C:`Crohn hastalığı`,D:`Sifiliz`,E:`Fibroadenom`},dogru:`E`,aciklama:`Granülomatöz enflamasyon enfeksiyöz (tüberküloz, sifiliz, mantar, parazit), immün aracılı (sarkoidoz, Crohn) ve yabancı cisim nedenlerine bağlıdır. Fibroadenom memenin benign fibroepitelyal tümörüdür.`,sik_aciklamalari:{A:`Granülomatöz enflamasyon yapar.`,B:`Granülomatöz enflamasyon yapar.`,C:`Granülomatöz enflamasyon yapar.`,D:`Granülomatöz enflamasyon yapar (gumma).`,E:`Yol açmaz (aranan cevap); bir tümördür. Granülomatöz enflamasyon enfeksiyöz (tüberküloz, sifiliz, mantar, parazit), immün aracılı (sarkoidoz, Crohn) ve yabancı cisim nedenlerine bağlıdır. Fibroadenom memenin benign fibroepitelyal tümörüdür.`},bilgi:[28],benzer_cikmis:[`d3-b-139`]},{id:`k1-13-q32`,kazanim:11,zorluk:`orta`,soru:`Makrofajlardan oluşan bir duvar, belirgin plazma hücresi infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz içeren granülomatöz lezyon (gumma) hangi hastalığın hangi evresinde görülür?`,secenekler:{A:`Tüberkülozun primer evresi`,B:`Sifilizin üçüncül evresi`,C:`Sarkoidozun akciğer evresi`,D:`Kedi tırmığı hastalığının erken evresi`,E:`Crohn hastalığının aktif dönemi`},dogru:`B`,aciklama:`Gumma Treponema pallidum enfeksiyonunun üçüncül (tersiyer) evresinde görülür; plazma hücrelerinden zengin infiltrat tipiktir.`,sik_aciklamalari:{A:`Tüberküloz kazeöz granülom oluşturur; gumma terimi kullanılmaz.`,B:`Doğru. Gumma Treponema pallidum enfeksiyonunun üçüncül (tersiyer) evresinde görülür; plazma hücrelerinden zengin infiltrat tipiktir.`,C:`Sarkoidoz non-kazeöz granülomdur.`,D:`Kedi tırmığı hastalığında stellat, nötrofilden zengin granülomlar görülür.`,E:`Crohn non-kazeöz granülom oluşturur.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-13-q33`,kazanim:11,zorluk:`zor`,soru:`Kediyle oynadıktan birkaç hafta sonra koltuk altında lenfadenopati gelişen bir çocuğun lenf düğümü biyopsisinde yıldız (stellat) şekilli, merkezinde granüler debris ve belirgin nötrofiller bulunan granülomlar görülüyor.

Bu tablonun etkeni ve granülom özelliği aşağıdakilerden hangisinde doğru verilmiştir?`,secenekler:{A:`Mycobacterium tuberculosis – kazeöz granülom, bol Langhans dev hücresi`,B:`Bartonella henselae – stellat granülom, merkezde nötrofil; dev hücreler genellikle nadir`,C:`Treponema pallidum – gumma`,D:`Silika – yabancı cisim granülomu`,E:`Sarkoidoz – non-kazeöz granülom`},dogru:`B`,aciklama:`Kedi tırmığı hastalığının etkeni gram-negatif bir basil olan Bartonella henselae'dir; yuvarlak veya stellat granülomlar, merkezde granüler debris ve nötrofiller görülür.`,sik_aciklamalari:{A:`Tüberküloz bu öykü ve morfolojiye uymaz.`,B:`Doğru. Kedi tırmığı hastalığının etkeni gram-negatif bir basil olan Bartonella henselae'dir; yuvarlak veya stellat granülomlar, merkezde granüler debris ve nötrofiller görülür.`,C:`Gumma sifilizin üçüncül evresine aittir.`,D:`Silika yabancı cisim granülomu yapar; kedi teması öyküsüyle ilişkisizdir.`,E:`Sarkoidoz nötrofilden zengin stellat granülom yapmaz.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q04`,kazanim:11,zorluk:`orta`,soru:`47 yaşındaki bir hasta akut başvuru yapan ve laboratuvar-görüntüleme bulguları birlikte değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık örneklerini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı… ilkesinin tam tersi geçerlidir ve Dev hücreler genellikle nadirdir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Kedi tırmığı hastalığında granülom olup "Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık…" ile ilişkisizdir`,C:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş,… Bu nedenle Nedenler sınırlı sayıda hastalık grubunu düşündürür; tanısal ipucu sağlar`,D:`Bulgular "Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Granülomatöz enflamasyonun nedenleri" ile açıklanamaz`},dogru:`C`,aciklama:`Robbins/Harrison mantığıyla: Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika,… Doğrudan sonucu "Nedenler sınırlı sayıda hastalık grubunu düşündürür; tanısal ipucu sağlar" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,C:`Doğru; Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn…`,D:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`},bilgi:[28,31],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q05`,kazanim:11,zorluk:`zor`,soru:`Farklı bir hasta hastalığın seyri ve prognozunun değerlendirildiği ayrı bir vakada ele alınıyor. Öyküde "Kedi tırmığı hastalığında granülom" vurgulanıyor ve hekim "Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık örneklerini açıklamak" kazanımındaki "Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Dev hücreler genellikle nadirdir hiçbir koşulda gözlenmez ve Granülomatöz enflamasyonun nedenleri tek belirleyicidir`,B:`Bu süreçte "Granülomatöz enflamasyonun nedenleri" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Kedi tırmığı hastalığında granülom" ayırıcı tanıda gereksizdir`,D:`Dev hücreler genellikle nadirdir Çünkü Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde…`,E:`Bu olguda izlem gerekmez; "Granülomatöz enflamasyonun başlıca nedenlerini ve hastalık…" yalnızca teorik bir bilgidir`},dogru:`D`,aciklama:`Guyton/Robbins bütünlüğünde: Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil sonucu "Dev hücreler genellikle nadirdir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`,D:`Doğru; Dev hücreler genellikle nadirdir Çünkü Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız…`,E:`Yanlış; ders paketindeki "Granülomatöz enflamasyonun nedenleri" bilgisiyle çelişir.`},bilgi:[31,32],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q06`,kazanim:11,zorluk:`orta`,soru:`Kedi tırmığı hastalığında granülom: Bartonella henselae (gram-negatif basil). Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Tüberkülozda granülomatöz enflamasyon ve fibrozis`,B:`Mikropların öldürülmesi ve enflamasyonun sürdürülmesi sağlanır`,C:`Nötrofil alımı ve aktivasyonu artar`,D:`Dev hücreler genellikle nadirdir`,E:`Tipik örneği tüberkülozdur`},dogru:`D`,aciklama:`Bartonella henselae (gram-negatif basil). Dev hücreler genellikle nadirdir. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Bartonella henselae (gram-negatif basil) doğrudan Dev hücreler genellikle nadirdir doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kalıcı enfeksiyonlar sürecine ait bir özelliktir ve kedi tırmığı hastalığında granülom düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Klasik (M1) makrofaj aktivasyonu sürecine ait bir özelliktir ve kedi tırmığı hastalığında granülom düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Th17 hücreleri sürecine ait bir özelliktir ve kedi tırmığı hastalığında granülom düzeneğini tanımlamaz.`,D:`Doğru; Dev hücreler genellikle nadirdir çünkü Bartonella henselae (gram-negatif basil) düzeneği bu sonucu üretir.`,E:`Yanlış; bu ifade Kazeöz (kazeifiye) granülom sürecine ait bir özelliktir ve kedi tırmığı hastalığında granülom düzeneğini tanımlamaz.`},bilgi:[32],benzer_cikmis:[`38a0c0543117`,`4cfc86f268db`]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q07`,kazanim:11,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Sifilizde granülom (gumma) mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları`,B:`İnflamatuvar yanıtta çoğu makrofaj kemik iliği hematopoetik öncüllerinden (kan monositi)`,C:`IFN-γ üretir`,D:`Kronik enflamasyonun özel bir tipi`,E:`Bartonella henselae (gram-negatif basil)`},dogru:`A`,aciklama:`Tıbbi Patoloji düzeneğinde Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu bilinir. Treponema pallidum enfeksiyonunda hastalığın üçüncül evresinde görülür. Mekanizma bu sırayla işlediği için beklenen sonuç Treponema pallidum enfeksiyonunda hastalığın üçüncül evresinde görülür olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı. Bu mekanizma treponema pallidum enfeksiyonunda hastalığın üçüncül evresinde görülür sonucunu doğurur.`,B:`Yanlış; bu ifade Makrofaj kökeni sürecine ait bir özelliktir ve sifilizde granülom (gumma) düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Th1 hücreleri sürecine ait bir özelliktir ve sifilizde granülom (gumma) düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Granülomatöz enflamasyonun tanımı sürecine ait bir özelliktir ve sifilizde granülom (gumma) düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kedi tırmığı hastalığında granülom sürecine ait bir özelliktir ve sifilizde granülom (gumma) düzeneğini tanımlamaz.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q08`,kazanim:11,zorluk:`orta`,soru:`Aşağıdaki enfeksiyöz etken ve oluşturduğu granülomatöz hastalık eşleştirmelerinden hangisi YANLIŞTIR?`,secenekler:{A:`Mycobacterium leprae — Cüzzam (Lepra)`,B:`Treponema pallidum — Tersiyer Sifiliz (Gom lezyonu)`,C:`Bartonella henselae — Kedi Tırmığı Hastalığı (Süpüratif nekrotizan granülom)`,D:`Histoplasma capsulatum — Histoplazmozis`,E:`Clostridium tetani — Kazeifiye Akciğer Granülomu`},dogru:`E`,aciklama:`Clostridium tetani anaerobik, sporlu bir basildir; dokuya invaze olup granülom yapmaz, salgıladığı tetanospazmin nörotoksini ile retrograd aksonal taşınarak merkezi inhibitör nöronları (GABA/glisin) bloke eder ve spastik felç yapar. M. leprae lepra, T. pallidum sifilitik gom, B. henselae kedi tırmığı (yıldızsı süpüratif granülom), H. capsulatum ise fungal granülom yapar.`,sik_aciklamalari:{A:`M. leprae granülomatöz lepraya yol açar.`,B:`T. pallidum tersiyer evrede gom adı verilen nekrotik granülomlar yapar.`,C:`B. henselae lenf nodunda süpüratif mikroabseli nekrotizan granülom yapar.`,D:`H. capsulatum tüberküloza çok benzeyen kazeifiye granülomlar yapar.`,E:`Doğrudur. Clostridium tetani nörotoksik bir bakteridir, granülom oluşturmaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q09`,kazanim:11,zorluk:`zor`,soru:`Genç bir hastada kedi tırmalamasından 2-3 hafta sonra aksiller lenf nodunda ağrılı büyüme gelişiyor. Yapılan biyopside 'merkezinde nötrofil birikimi ve mikroapse odakları bulunan, etrafı epiteloid histiyositler ve dev hücrelerle çevrili yıldızsı (stellat) nekrotizan granülomlar' izleniyor. 
Bu hastada en olası etken ve tanı aşağıdakilerden hangisidir?`,secenekler:{A:`Bartonella henselae — Kedi Tırmığı Hastalığı`,B:`Streptococcus pneumoniae — Pnömokokal lenfadenit`,C:`Mycobacterium leprae — Lepromatöz lepra`,D:`Borrelia burgdorferi — Lyme hastalığı`,E:`Ebstein-Barr Virüsü — İnfeksiyöz Mononükleoz`},dogru:`A`,aciklama:`Kedi tırmığı hastalığı (Cat-scratch disease), Bartonella henselae tarafından oluşturulur. Tipik olarak kedi tırmalamasını takiben bölgesel lenf nodunda ağrılı büyüme olur. Karakteristik histopatolojisi 'yıldızsı (stellat) şekilli, merkezinde nötrofiller ve mikroapse (süpürasyon) içeren nekrotizan granülomlar'dır (Warthin-Starry gümüşleme boyasıyla basiller gösterilebilir).`,sik_aciklamalari:{A:`Doğrudur. Kedi tırmığı hastalığı (B. henselae) merkezinde nötrofil içeren yıldızsı nekrotizan granülom yapar.`,B:`Pnömokok granülom yapmaz, akut pürülan lenfadenit yapar.`,C:`Lepromatöz leprada köpüksü makrofajlar (Virchow hücreleri) vardır, süpüratif granülom yoktur.`,D:`Borrelia eritema migrans yapar, yıldızsı süpüratif granülom yapmaz.`,E:`EBV lenfoid hiperplazi yapar, granülom yapmaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q10`,kazanim:11,zorluk:`orta`,soru:`Tersiyer sifilizde karaciğer, kemik veya deride görülen; merkezinde koagülasyon nekrozuna benzer elastik kıvamlı nekroz alanı, çevresinde epiteloid histiyositler, dev hücreler ve belirgin ENDARTERİTİS OBLİTERANS gösteren plazma hücrelerinden zengin granülomatöz lezyona ne ad verilir?`,secenekler:{A:`Gom (Gumma)`,B:`Şankr (Chancre)`,C:`Kondiloma lata`,D:`Ghon odağı`,E:`Aschoff nodülü`},dogru:`A`,aciklama:`Gom (Gumma), Treponema pallidum'a bağlı tersiyer sifilizin karakteristik granülomudur. Merkezinde lastik kıvamında (rubbery) nekroz bulunur. Çevresinde epiteloid hücreler, dev hücreler ve özellikle damar duvarlarında lüminal daralma (endarteritis obliterans) yapan zengin plazma hücresi infiltrasyonu izlenir. Şankr primer sifiliz lezyonudur; kondiloma lata sekonder sifilizdedir; Ghon tüberkülozdadır.`,sik_aciklamalari:{A:`Doğrudur. Tersiyer sifilizin granülomatöz lezyonu Gom (Gumma)'dır.`,B:`Şankr primer sifilizin ağrısız sert ülseridir.`,C:`Kondiloma lata sekonder sifilizin mukokutanöz lezyonudur.`,D:`Ghon odağı primer tüberkülozun akciğer subplevral lezyonudur.`,E:`Aschoff nodülü akut romatizmal karditte görülür.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q11`,kazanim:11,zorluk:`zor`,soru:`Lenfogranüloma venereum (LGV) etkeni olan Chlamydia trachomatis L1, L2, L3 serovarlarının inguinal lenf nodlarında oluşturduğu granülom tipi aşağıdakilerden hangisidir?`,secenekler:{A:`Non-kazeifiye sert sarkoid benzeri granülom`,B:`Üçgen veya yıldız biçimli, merkezinde nötrofil mikroapseleri içeren nekrotizan granülom`,C:`Sadece yabancı cisim dev hücresi içeren kistik granülom`,D:`Kemik iliği yağ granülomu`,E:`Kalsifiye subplevral granülom`},dogru:`B`,aciklama:`Chlamydia trachomatis (L1-L3) tarafından oluşturulan Lenfogranüloma venereum (LGV), inguinal lenf nodlarında (bubo) kedi tırmığı hastalığına çok benzer şekilde 'yıldızsı, merkezinde nötrofiller ve nekroz barındıran süpüratif nekrotizan granülomlar' oluşturur. İlerleyen evrede lenf nodları birbirine yapışır, fistülize olur ve fibrozisle lenfödem tablosu meydana gelir.`,sik_aciklamalari:{A:`LGV nekrozsuz sert granülom yapmaz; süpüratiftir.`,B:`Doğrudur. LGV merkezinde nötrofil apseleri bulunan süpüratif nekrotizan granülomlar yapar.`,C:`Yabancı cisim reaksiyonu değildir, enfeksiyözdür.`,D:`Kemik iliği lezyonu değildir.`,E:`Subplevral kalsifikasyon tüberküloza aittir.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q12`,kazanim:11,zorluk:`orta`,soru:`Aşağıdakilerden hangisi granülomatöz enflamasyona yol açan OTOİMMÜN VEYA VASKÜLİTİK hastalıklardan biridir?`,secenekler:{A:`Granülomatoz Polianjiyitis (eski adıyla Wegener Granülomatozu)`,B:`Poliarteritis Nodoza (PAN)`,C:`Henoch-Schönlein Purpurası (IgA Vasküliti)`,D:`Mikroskopik Polianjiyitis`,E:`Kawasaki Hastalığı`},dogru:`A`,aciklama:`Granülomatoz Polianjiyitis (GPA / Wegener), nekrotizan vaskülit ile birlikte üst ve alt solunum yollarında 'coğrafi nekroz içeren granülomatöz enflamasyon' ve kresentik glomerülonefrit triadı ile seyreder. PR3-ANCA (c-ANCA) pozitiftir. Poliarteritis nodoza, Henoch-Schönlein ve Mikroskopik polianjiyitis granülom oluşturmayan vaskülitlerdir.`,sik_aciklamalari:{A:`Doğrudur. Granülomatoz Polianjiyitis (Wegener) solunum yollarında granülom yapan klasik otoimmün vaskülittir.`,B:`PAN nekrotizan vaskülittir ancak granülom yapmaz.`,C:`IgA vaskülitinde lökositoklastik vaskülit vardır, granülom yoktur.`,D:`Mikroskopik polianjiyitiste granülom bulunmaz (GPA'dan temel farkı).`,E:`Kawasaki koroner vaskülittir, granülom yapmaz.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q13`,kazanim:11,zorluk:`kolay`,soru:`"Uzun süreli toksik maruziyet" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{C:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,E:`IL-17 ve diğer sitokinleri salgılar`,D:`Nötrofiller ve ödem`,B:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,A:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},dogru:`C`,aciklama:`Doğru: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,sik_aciklamalari:{C:`Doğru. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,E:`Yanlış. IL-17 ve diğer sitokinleri salgılar`,D:`Yanlış. Nötrofiller ve ödem`,B:`Yanlış. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,A:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q14`,kazanim:11,zorluk:`orta`,soru:`"Non-klasik hastalıklar" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,B:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,C:`IL-17 ve diğer sitokinleri salgılar`,D:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},dogru:`E`,aciklama:`Doğru: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,sik_aciklamalari:{E:`Doğru. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Yanlış. Akut enflamasyonun tipik hücresidir; bazı kronik tablolarda süregelen katılım gösterebilir`,B:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,C:`Yanlış. IL-17 ve diğer sitokinleri salgılar`,D:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},bilgi:[35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q15`,kazanim:11,zorluk:`orta`,soru:`"Makrofajların ana fonksiyonları" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,D:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,C:`IL-17 ve diğer sitokinleri salgılar`,A:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,E:`Merkezi nekroz yoktur`},dogru:`B`,aciklama:`Doğru: Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,sik_aciklamalari:{B:`Doğru. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,D:`Yanlış. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,C:`Yanlış. IL-17 ve diğer sitokinleri salgılar`,A:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,E:`Yanlış. Merkezi nekroz yoktur`},bilgi:[15],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k11-q16`,kazanim:11,zorluk:`zor`,soru:`"Lenfositlerin rolü" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Eozinofil aktivasyonu yapar`,D:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,B:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},dogru:`C`,aciklama:`Doğru: Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,sik_aciklamalari:{C:`Doğru. Kronik enflamasyonda makrofajlarla birlikte baskın; adaptif bağışıklıkla antijen özgüllüğü sağlar`,E:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,A:`Yanlış. Eozinofil aktivasyonu yapar`,D:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,B:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},bilgi:[16],benzer_cikmis:[]}],ilgili_cikmis:[{id:`d3-b-139`,soru:`Aşağıdakilerden hangisi, granülomatöz inflamasyona yol açabilen hastalıklardan birisi değildir?`,secenekler:{A:`Sifiliz`,B:`Sarkoidoz`,C:`Fibroadenom`,D:`Tüberküloz`,E:`Crohn hastalığı`},cevap:`C`}]},{no:12,metin:`Yabancı cisim granülomlarının özelliklerini tanımlamak`,sorular:[{id:`k1-13-q34`,kazanim:12,zorluk:`kolay`,soru:`Yabancı cisim granülomlarına yol açan materyaller arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Dikiş iplikleri`,B:`Talk`,C:`Cam parçacıkları`,D:`Metal parçacıkları`,E:`Mycobacterium tuberculosis`},dogru:`E`,aciklama:`Yabancı cisim granülomları fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş, cam, metal) gelişir; M. tuberculosis enfeksiyöz (immün) granülom yapar.`,sik_aciklamalari:{A:`Yabancı cisim granülomu nedenidir.`,B:`Yabancı cisim granülomu nedenidir.`,C:`Yabancı cisim granülomu nedenidir.`,D:`Yabancı cisim granülomu nedenidir.`,E:`Yer almaz (aranan cevap); immün aracılı kazeöz granülom yapar.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-q35`,kazanim:12,zorluk:`orta`,soru:`Geçirilmiş ameliyat bölgesinden alınan biyopside dev hücrelerin içinde ve çevresinde polarize ışıkta ışığı kıran partiküller görülüyor.

Bu bulgu için en olası tanı aşağıdakilerden hangisidir?`,secenekler:{A:`Tüberküloz granülomu`,B:`Sarkoidoz`,C:`Yabancı cisim granülomu`,D:`Sifilitik gumma`,E:`Kedi tırmığı hastalığı`},dogru:`C`,aciklama:`Yabancı cisim granülomunda dev hücrelerin merkezinde veya çevresinde yabancı materyal bulunur; polarize ışıkta çift kırılım gösteren partiküller tanıya yardımcı olur.`,sik_aciklamalari:{A:`Tüberkülozda kazeöz nekroz ve asit-fast basiller beklenir.`,B:`Sarkoidozda polarize partikül tipik değildir.`,C:`Doğru. Yabancı cisim granülomunda dev hücrelerin merkezinde veya çevresinde yabancı materyal bulunur; polarize ışıkta çift kırılım gösteren partiküller tanıya yardımcı olur.`,D:`Gumma plazma hücreli, merkezi nekrozlu sifilitik lezyondur.`,E:`Kedi tırmığında nötrofilden zengin stellat granülom görülür.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-q36`,kazanim:12,zorluk:`zor`,soru:`Yabancı cisim granülomlarını immün (enfeksiyöz) granülomlardan ayıran özellik aşağıdakilerden hangisidir?`,secenekler:{A:`Yabancı cisim granülomlarında güçlü antijen özgül T hücre yanıtı temel uyarandır.`,B:`Yabancı cisim granülomlarında uyaran, fagositoz edilemeyecek kadar büyük veya çözünmeyen inert materyaldir; dev hücreler materyali çevreler.`,C:`Yabancı cisim granülomlarında daima kazeöz nekroz bulunur.`,D:`Yabancı cisim granülomları yalnızca akciğerde görülür.`,E:`Yabancı cisim granülomlarında makrofaj bulunmaz.`},dogru:`B`,aciklama:`Yabancı cisim granülomu inert materyalin uzaklaştırılamamasına karşı gelişir; immün granülomlarda ise kalıcı antijene karşı T hücre ve IFN-γ yanıtı temel uyarandır.`,sik_aciklamalari:{A:`Antijen özgül T hücre yanıtı immün granülomların özelliğidir.`,B:`Doğru. Yabancı cisim granülomu inert materyalin uzaklaştırılamamasına karşı gelişir; immün granülomlarda ise kalıcı antijene karşı T hücre ve IFN-γ yanıtı temel uyarandır.`,C:`Yabancı cisim granülomları genellikle non-kazeözdür.`,D:`Herhangi bir dokuda (deri, cerrahi saha) görülebilir.`,E:`Makrofaj ve dev hücreler granülomun temel bileşenidir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q04`,kazanim:12,zorluk:`orta`,soru:`54 yaşındaki bir hasta ayırıcı tanısı tartışılan ve öyküsü derinleştirilen bir hastada hekime başvuruyor. Değerlendirmede "Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Yabancı cisim granülomlarının özelliklerini tanımlamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam,… ilkesinin tam tersi geçerlidir ve Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı… gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Yabancı cisim granülomları olup "Yabancı cisim granülomlarının özelliklerini tanımlamak" ile ilişkisizdir`,C:`Bulgular "Yabancı cisim granülomlarının özelliklerini tanımlamak" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal) Bu nedenle Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Yabancı cisim granülomları" ile açıklanamaz`},dogru:`D`,aciklama:`Robbins/Harrison mantığıyla: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal) Doğrudan sonucu "Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,D:`Doğru; Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal) Bu…`,E:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q05`,kazanim:12,zorluk:`zor`,soru:`Farklı bir hasta tanısal test sonucunun yorumlandığı bağımsız bir olguda ele alınıyor. Öyküde "Yabancı cisim granülomları" vurgulanıyor ve hekim "Yabancı cisim granülomlarının özelliklerini tanımlamak" kazanımındaki "Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür hiçbir koşulda gözlenmez ve Yabancı cisim granülomları tek belirleyicidir`,B:`Bu süreçte "Yabancı cisim granülomları" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,C:`Benzer tabloların tamamı aynı nedene bağlıdır; "Yabancı cisim granülomları" ayırıcı tanıda gereksizdir`,D:`Bu olguda izlem gerekmez; "Yabancı cisim granülomlarının özelliklerini tanımlamak" yalnızca teorik bir bilgidir`,E:`Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür Çünkü Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},dogru:`E`,aciklama:`Guyton/Robbins bütünlüğünde: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal) sonucu "Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Yabancı cisim granülomları" bilgisiyle çelişir.`,E:`Doğru; Dev hücrelerin merkezinde/çevresinde yabancı materyal; polarize ışıkta ışığı kıran partiküller görülür Çünkü…`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q06`,kazanim:12,zorluk:`orta`,soru:`Yabancı cisim granülomları: Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal). Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Anjiyogenez, fibrozis ve yara izi oluşumu izlenir`,B:`T lenfositlerine antijen sunulur ve ko-uyarıcı sinyal sağlanır`,C:`Osteomiyelit ve sigara ilişkili akciğer hastalıklarında süregen nötrofil görülür`,D:`Granülom vücut için izolasyon stratejisidir`,E:`Dev hücrelerin merkezinde/çevresinde yabancı materyal`},dogru:`E`,aciklama:`Tıbbi Patoloji düzeneğinde Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere bilinir. Dev hücrelerin merkezinde/çevresinde yabancı materyal. Mekanizma bu sırayla işlediği için beklenen sonuç Dev hücrelerin merkezinde/çevresinde yabancı materyal olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt E seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Kronik enflamasyonun morfolojik özellikleri sürecine ait bir özelliktir ve yabancı cisim granülomları düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Makrofajların ana fonksiyonları sürecine ait bir özelliktir ve yabancı cisim granülomları düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Nötrofillerin kronik tablolardaki katılımı sürecine ait bir özelliktir ve yabancı cisim granülomları düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade T hücre aracılı granülomatöz yanıt sürecine ait bir özelliktir ve yabancı cisim granülomları düzeneğini tanımlamaz.`,E:`Doğru; Dev hücrelerin merkezinde/çevresinde yabancı materyal çünkü Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı düzeneği bu sonucu üretir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q07`,kazanim:12,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Granülom morfolojisi mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`IL-4 ve IL-13 ile indüklenir`,B:`Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı`,C:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder`,D:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük`},dogru:`B`,aciklama:`Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı. Çevrede lenfositler bulunur. Fizyopatolojik sıra bu yönde ilerlediğinden Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve varlığında Çevrede lenfositler bulunur beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Alternatif (M2) makrofaj aktivasyonu sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,B:`Doğru; Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı. Bu mekanizma çevrede lenfositler bulunur sonucunu doğurur.`,C:`Yanlış; bu ifade Lenfosit-makrofaj döngüsü sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Granülomatöz enflamasyonun nedenleri sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Non-klasik hastalıklar sürecine ait bir özelliktir ve granülom morfolojisi düzeneğini tanımlamaz.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q08`,kazanim:12,zorluk:`orta`,soru:`Yabancı cisim granülomlarının immün granülomlardan (örn. tüberküloz veya sarkoidoz granülomu) EN TEMEL PATOGENETİK FARKI aşağıdakilerden hangisidir?`,secenekler:{A:`Yabancı cisim granülomlarında hiçbir makrofajın bulunmaması`,B:`Yabancı cisim granülomlarının T hücre aracılı antijene özgü bir immün yanıt (gecikmiş tip aşırı duyarlık) GEREKTİRMEMESİ; inert, antijenik olmayan partiküllerin etrafında gelişmesi`,C:`Yabancı cisim granülomlarının sadece kemik iliğinde gelişebilmesi`,D:`Yabancı cisim granülomlarında kazeöz nekrozun 10 kat daha fazla olması`,E:`Yabancı cisim granülomlarının sadece virüslerle tetiklenmesi`},dogru:`B`,aciklama:`Granülomlar patogenezlerine göre ikiye ayrılır: 1) İmmün Granülomlar: T hücresi aracılı gecikmiş tip aşırı duyarlık yanıtıyla oluşur; antijen sunumu ve IFN-γ zorunludur (tüberküloz, sarkoidoz). 2) Yabancı Cisim Granülomları: Antijenik olmayan veya immün yanıt tetiklemeyen inert maddelere (cerrahi dikiş ipliği, talk, cam vb.) karşı oluşur; T hücresi aracılı adaptif immün yanıt gerektirmez. Makrofajlar ve dev hücreler cismi fiziksel olarak kuşatır.`,sik_aciklamalari:{A:`Makrofajlar ve yabancı cisim dev hücreleri ana hücrelerdir.`,B:`Doğrudur. T hücre aracılı adaptif immün yanıt olmadan inert partiküllere karşı oluşması temel farktır.`,C:`Herhangi bir yumuşak dokuda oluşabilir.`,D:`Kazeöz nekroz içermezler.`,E:`Virüslerle değil inert maddelerle tetiklenir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q09`,kazanim:12,zorluk:`orta`,soru:`Yabancı cisim tipi multinükleer dev hücrelerin morfolojik olarak Langhans tipi dev hücrelerden ayrılmasını sağlayan çekirdek yerleşim paterni aşağıdakilerden hangisidir?`,secenekler:{A:`Çekirdeklerin hücre periferinde muntazam at nalı şeklinde dizilmesi`,B:`Çekirdeklerin sitoplazma içinde düzensiz, rastgele ve dağınık olarak kümelenmesi`,C:`Hücrede sadece tek bir dev nükleus bulunması`,D:`Çekirdeklerin hücrenin tam merkezinde halka şeklinde dizilip etrafının lipidle sarılması`,E:`Hücrenin nükleussuz (çekirdeksiz) olması`},dogru:`B`,aciklama:`Yabancı cisim tipi multinükleer dev hücrelerde onlarca nükleus sitoplazmanın her tarafına düzensiz, kaotik ve rastgele dağılmıştır. Çekirdeklerin periferde düzenli 'at nalı' şeklinde dizildiği hücreler ise Langhans tipi dev hücrelerdir.`,sik_aciklamalari:{A:`At nalı dizilimi Langhans tipi dev hücreye aittir.`,B:`Doğrudur. Çekirdeklerin sitoplazmada düzensiz ve dağınık yerleşimi yabancı cisim dev hücresi özelliğidir.`,C:`Multinükleer hücrelerdir, onlarca çekirdek içerirler.`,D:`Lipid halkalı santral çekirdek Touton dev hücresidir.`,E:`Çekirdeksiz değillerdir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q10`,kazanim:12,zorluk:`zor`,soru:`Bir deri altı biyopsisinde ameliyat skarı komşuluğunda granülomatöz reaksiyon izlenmektedir. Polarize ışık mikroskobunda incelendiğinde dev hücrelerin içinde parlak, çift kırıcı (birefringent) lifsel yabancı materyal saptanmıştır. 
Bu klinikopatolojik tablo en olası olarak aşağıdakilerden hangisidir?`,secenekler:{A:`Cerrahi sütür (dikiş) granülomu`,B:`Primer deri tüberkülozu (Lupus vulgaris)`,C:`Akut flegmonöz sellülit`,D:`Deri leşmanyazisi`,E:`Eritema nodosum`},dogru:`A`,aciklama:`Cerrahi sütür granülomu en sık karşılaşılan yabancı cisim granülomudur. Cerrahi ipek, naylon veya absorbe olmayan sütür materyalleri dokuda kalıcı inert cisim olarak yabancı cisim tipi dev hücreleri uyarır. Polarize ışık mikroskobunda yabancı cisimler (sütür lifleri, talk pudrası kristalleri, silika) parlak, çift kırıcı (refraktil / birefringent) olarak parlar; bu bulgu tüberküloz veya sarkoidozdan ayrımda kesin tanı koydurucudur.`,sik_aciklamalari:{A:`Doğrudur. Polarize ışıkta parlayan lifsel materyal cerrahi sütür reaksiyonunu gösterir.`,B:`Lupus vulgaris tüberkülozdur, polarize ışıkta parlayan yabancı lif içermez.`,C:`Sellülit akut nötrofilik enfeksiyondur.`,D:`Leşmanyaziste makrofaj içinde amastigotlar görülür, sütür lifi değil.`,E:`Eritema nodosum septal pannikülittir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q11`,kazanim:12,zorluk:`orta`,soru:`Aşağıdakilerden hangisi dokuda yabancı cisim granülomu oluşturabilecek EKZOJEN materyallerden biri DEĞİLDİR?`,secenekler:{A:`Cerrahi eldiven talk pudrası partikülleri`,B:`Dövme (tattoo) pigment boyaları`,C:`Deriye batan ağaç veya cam kıymıkları`,D:`Eklem kıkırdağına çöken endojen monosodyum ürat kristalleri (Tofüs)`,E:`İntravenöz madde bağımlılarında damara enjekte edilen nişasta/selüloz partikülleri`},dogru:`D`,aciklama:`Yabancı maddeler ekzojen (vücut dışından gelen) veya endojen (vücudun kendi ürettiği) olabilir. Talk pudrası, dövme boyası, tahta/cam kıymığı ve enjekte edilen selüloz/nişasta ekzojen yabancı cisimlerdir. Gut hastalığında eklem ve yumuşak dokuda çöken monosodyum ürat kristalleri (tofüs) ve aterosklerozdaki kolesterol kristalleri ise vücudun kendi metabolizmasından kaynaklanan 'endojen yabancı cisimler'dir.`,sik_aciklamalari:{A:`Talk pudrası ekzojendir.`,B:`Dövme boyası ekzojendir.`,C:`Kıymık ekzojendir.`,D:`Doğrudur. Monosodyum ürat kristalleri (gut tofüsü) ekzojen değil, endojen metabolik bir maddedir.`,E:`Enjekte edilen nişasta ekzojendir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q12`,kazanim:12,zorluk:`zor`,soru:`Yabancı cisim granülomlarında yabancı cismin boyutu ile makrofajların hücresel davranışı arasındaki ilişki incelendiğinde, multinükleer dev hücrelerin oluşumunu tetikleyen temel fiziksel faktör nedir?`,secenekler:{A:`Yabancı cismin tek bir makrofajın fagositoz yapabileceği boyuttan (yaklaşık 10-20 mikron) ÇOK DAHA BÜYÜK olması ve fagositozun engellenmesi (frustrated phagocytosis)`,B:`Cismin sadece sıvı formda olması`,C:`Cismin elektrik yükünün tamamen sıfır olması`,D:`Cismin makrofaj DNA'sını mutasyona uğratması`,E:`Yabancı cismin kalsiyum salgılaması`},dogru:`A`,aciklama:`Eğer yabancı partikül çok küçükse tek bir makrofaj onu fagositozla içine alır ve lizozomlarında sindirir (veya taşıyıp uzaklaştırır). Ancak partikül tek bir makrofajın yutamayacağı kadar büyükse (örn. sütür ipliği, büyük talk agregatı), fagositoz başarısız olur ('engellenmiş/hüsrana uğramış fagositoz' - frustrated phagocytosis). Makrofajlar cismin yüzeyine yapışır, sitoplazmalarını birleştirerek multinükleer dev hücreleri oluşturur ve cismi çepeçevre kuşatırlar.`,sik_aciklamalari:{A:`Doğrudur. Tek bir makrofajın yutamayacağı büyüklükteki cisimler makrofaj füzyonunu ve dev hücre oluşumunu tetikler.`,B:`Sıvı partiküller pinositozla alınır, dev hücre granülomu yapmaz.`,C:`Elektrik yükü sıfırlığı temel boyut faktörü değildir.`,D:`Mutajenik etki değildir.`,E:`Kalsiyum salgısıyla ilgili değildir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q13`,kazanim:12,zorluk:`kolay`,soru:`"Th1 hücreleri" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`IFN-γ üretir`,C:`Nötrofiller ve ödem`,B:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,E:`Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,A:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`},dogru:`D`,aciklama:`Doğru: IFN-γ üretir`,sik_aciklamalari:{D:`Doğru. IFN-γ üretir`,C:`Yanlış. Nötrofiller ve ödem`,B:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,E:`Yanlış. Mikrobiyal ürünler (LPS, TLR ligandları) ve T hücre kaynaklı IFN-γ ile indüklenir; lizozomal enzimler, ROS, NO ve IL-1, TNF, IL-12, IL-6, kemokinler artar`,A:`Yanlış. Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`},bilgi:[17],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q14`,kazanim:12,zorluk:`orta`,soru:`"M1 ve M2 dengesi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,D:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,A:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,B:`Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,C:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`},dogru:`E`,aciklama:`Doğru: Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,sik_aciklamalari:{E:`Doğru. Teorik olarak erken yanıt M1 ağırlıklı, sonra M2 ağırlıklıdır; pratikte ara formlar sıktır`,D:`Yanlış. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,A:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,B:`Yanlış. Bartonella henselae (gram-negatif basil); yuvarlak veya yıldız (stellat) şekilli granülomlar, merkezde granüler debris ve belirgin nötrofil`,C:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q15`,kazanim:12,zorluk:`orta`,soru:`"Lenfosit-makrofaj döngüsü" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,D:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,A:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,C:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`},dogru:`E`,aciklama:`Doğru: Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,sik_aciklamalari:{E:`Doğru. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`,D:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,A:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,C:`Yanlış. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`},bilgi:[20],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k12-q16`,kazanim:12,zorluk:`zor`,soru:`"Kronik enflamasyon ve fibrozis" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,B:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},dogru:`C`,aciklama:`Doğru: Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,sik_aciklamalari:{C:`Doğru. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,D:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,B:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,A:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`},bilgi:[34],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:13,metin:`Granülomların klinik önemini, tanı yöntemlerini ve iyileşme biçimini açıklamak`,sorular:[{id:`k1-13-q37`,kazanim:13,zorluk:`kolay`,soru:`Granülomatöz enflamasyonda kesin etken tanısı için kullanılan yöntemler arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Asit-fast (ARB) boyası`,B:`Mantar boyaları`,C:`Kültür`,D:`Moleküler yöntemler`,E:`Yalnızca rutin HE boyasıyla granülom görülmesi`},dogru:`E`,aciklama:`Granülom sınırlı bir hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar, kültür, moleküler yöntemler ve seroloji gerekir.`,sik_aciklamalari:{A:`Kullanılır; mikobakterileri gösterir.`,B:`Kullanılır; mantar boyaları granülom yapan mantar etkenlerini gösterir.`,C:`Kullanılır; kültür etkenin üretilip tanımlanmasını sağlar.`,D:`Kullanılır; seroloji de yardımcıdır.`,E:`Kesin etken tanısı için yeterli değildir (aranan cevap).`},bilgi:[33],benzer_cikmis:[]},{id:`k1-13-q38`,kazanim:13,zorluk:`orta`,soru:`Granülom oluşumunun vücut açısından anlamı ve iyileşme biçimi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Granülom etkeni her zaman tamamen yok eder ve iz bırakmadan iyileşir.`,B:`Granülom etkeni izole etme stratejisidir; etken yok edilemese de yayılımı sınırlanır ve çoğunlukla fibrozis ve kalıcı skarla iyileşir.`,C:`Granülom etkenin yayılmasını hızlandırır.`,D:`Granülomlar yalnızca akut enflamasyonda görülür.`,E:`Granülomlar likefaksiyon nekrozuyla iyileşir.`},dogru:`B`,aciklama:`Granülom etkeni hapseden bir duvar oluşturur; iyileşme çoğunlukla fibrozis ve skarla olur.`,sik_aciklamalari:{A:`Etken her zaman yok edilemez; iyileşme skarla olur.`,B:`Doğru. Granülom etkeni hapseden bir duvar oluşturur; iyileşme çoğunlukla fibrozis ve skarla olur.`,C:`Granülom yayılımı sınırlar.`,D:`Granülomatöz enflamasyon kronik enflamasyonun özel tipidir.`,E:`Granülomlar fibrozisle iyileşir.`},bilgi:[30,33],benzer_cikmis:[]},{id:`k1-13-q39`,kazanim:13,zorluk:`zor`,soru:`Akciğer biyopsisinde kazeöz granülomlar görülen bir hastada tanının kesinleştirilmesi için en uygun yaklaşım aşağıdakilerden hangisidir?`,secenekler:{A:`Granülom görülmesi tek başına tüberküloz tanısı için yeterlidir; ek test gerekmez.`,B:`Asit-fast boyama, kültür ve moleküler yöntemlerle etkenin gösterilmesi; mantar enfeksiyonları da ayırıcı tanıda değerlendirilmeli`,C:`Yalnızca serum CRP düzeyine bakılması`,D:`Yalnızca PAS boyasıyla glikojen aranması`,E:`Yalnızca Prusya mavisi ile demir aranması`},dogru:`B`,aciklama:`Kazeöz granülom tüberkülozu düşündürür ancak mantarlar da benzer tablo yapabilir; kesin tanı etkenin özel boya, kültür ve moleküler yöntemlerle gösterilmesini gerektirir.`,sik_aciklamalari:{A:`Granülom sınırlı bir hastalık grubunu düşündürür; etken gösterilmelidir.`,B:`Doğru. Kazeöz granülom tüberkülozu düşündürür ancak mantarlar da benzer tablo yapabilir; kesin tanı etkenin özel boya, kültür ve moleküler yöntemlerle gösterilmesini gerektirir.`,C:`CRP özgül değildir: yalnızca serum CRP düzeyine bakılması.`,D:`PAS mantar duvarını gösterebilir ama tek başına yaklaşım yetersizdir; glikojen aramak amaç değildir.`,E:`Prusya mavisi demir boyasıdır; etken göstermez.`},bilgi:[33,26],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q04`,kazanim:13,zorluk:`orta`,soru:`61 yaşındaki bir hasta tedavi yanıtı izlenen ve kliniği yeniden değerlendirilen bir olguda hekime başvuruyor. Değerlendirmede "Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Granülomların klinik önemini, tanı yöntemlerini ve iyileşme biçimini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif… ilkesinin tam tersi geçerlidir ve Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir gözlenmez`,B:`Bu tablodan sorumlu temel mekanizma Granülomların klinik önemi ve tanısı olup "Granülomların klinik önemini, tanı yöntemlerini ve iyileşme…" ile ilişkisizdir`,C:`Bulgular "Granülomların klinik önemini, tanı yöntemlerini ve iyileşme biçimini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,D:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "T hücre aracılı granülomatöz yanıt" ile açıklanamaz`,E:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür Bu nedenle Granülom vücut için izolasyon stratejisidir; etken yok edilemese de yayılımı sınırlanır`},dogru:`E`,aciklama:`Robbins/Harrison mantığıyla: Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür Doğrudan sonucu "Granülom vücut için izolasyon stratejisidir; etken yok edilemese de yayılımı sınırlanır" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,B:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,E:`Doğru; Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid…`},bilgi:[30,33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q05`,kazanim:13,zorluk:`zor`,soru:`Farklı bir hasta aynı konunun farklı bir yönünü aydınlatmak için ele alınan ikinci bir olguda ele alınıyor. Öyküde "Granülomların klinik önemi ve tanısı" vurgulanıyor ve hekim "Granülomların klinik önemini, tanı yöntemlerini ve iyileşme biçimini açıklamak" kazanımındaki "Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve…" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir Çünkü Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar…`,B:`Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir hiçbir koşulda gözlenmez ve T hücre aracılı granülomatöz yanıt tek belirleyicidir`,C:`Bu süreçte "T hücre aracılı granülomatöz yanıt" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Granülomların klinik önemi ve tanısı" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Granülomların klinik önemini, tanı yöntemlerini ve iyileşme biçimini…" yalnızca teorik bir bilgidir`},dogru:`A`,aciklama:`Guyton/Robbins bütünlüğünde: Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve… sonucu "Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Doğru; Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir Çünkü Granülomatöz enflamasyon sınırlı hastalık…`,B:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "T hücre aracılı granülomatöz yanıt" bilgisiyle çelişir.`},bilgi:[30,33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q06`,kazanim:13,zorluk:`orta`,soru:`Granülomların klinik önemi ve tanısı: Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir`,B:`Tümü mononükleer fagosit sisteminin parçasıdır`,C:`Alternatif (M2) makrofaj aktivasyonunu destekler`,D:`Çevrede lenfositler bulunur`,E:`Dev hücreler genellikle nadirdir`},dogru:`A`,aciklama:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür. Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir. Fizyopatolojik sıra bu yönde ilerlediğinden Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür varlığında Granülomlar çoğunlukla fibrozis ve kalıcı skar ile beklenir. Diğer seçenekler bu düzeneğin parçası değildir ve sorudaki tabloyu açıklayamaz. Bu nedenle doğru yanıt A seçeneğidir.`,sik_aciklamalari:{A:`Doğru; Granülomlar çoğunlukla fibrozis ve kalıcı skar ile iyileşir çünkü Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür düzeneği bu sonucu üretir.`,B:`Yanlış; bu ifade Yerleşik makrofaj isimleri sürecine ait bir özelliktir ve granülomların klinik önemi ve tanısı düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Th2 hücreleri sürecine ait bir özelliktir ve granülomların klinik önemi ve tanısı düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Granülom morfolojisi sürecine ait bir özelliktir ve granülomların klinik önemi ve tanısı düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kedi tırmığı hastalığında granülom sürecine ait bir özelliktir ve granülomların klinik önemi ve tanısı düzeneğini tanımlamaz.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q07`,kazanim:13,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: T hücre aracılı granülomatöz yanıt mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kronik enflamasyonda makrofajlarla birlikte baskın`,B:`Alerjik reaksiyonların ana hücresi`,C:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir`,D:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları`,E:`makrofajlar, lenfositler, plazma hücreleri`},dogru:`C`,aciklama:`Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür. Granülom vücut için izolasyon stratejisidir. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Kalıcı mikrobiyal antijen güçlü T hücre yanıtı doğrudan Granülom vücut için izolasyon stratejisidir doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt C seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Lenfositlerin rolü sürecine ait bir özelliktir ve t hücre aracılı granülomatöz yanıt düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Mast hücreleri sürecine ait bir özelliktir ve t hücre aracılı granülomatöz yanıt düzeneğini tanımlamaz.`,C:`Doğru; Kalıcı mikrobiyal antijen güçlü T hücre yanıtı oluşturur, IFN-γ üretilir ve makrofajlar aktif epiteloid hücrelere dönüşür. Bu mekanizma granülom vücut için izolasyon stratejisidir sonucunu doğurur.`,D:`Yanlış; bu ifade Sifilizde granülom (gumma) sürecine ait bir özelliktir ve t hücre aracılı granülomatöz yanıt düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonda baskın hücreler sürecine ait bir özelliktir ve t hücre aracılı granülomatöz yanıt düzeneğini tanımlamaz.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q08`,kazanim:13,zorluk:`orta`,soru:`Bir doku biyopsisinde kazeifiye veya nekrotizan granülom saptandığında, etkenin 'Mycobacterium tuberculosis' olduğunu histokimyasal olarak kanıtlamak için kullanılan altın standart özel boya aşağıdakilerden hangisidir?`,secenekler:{A:`Ziehl-Neelsen (veya Kinyoun / Asido-Rezistan Bakteri - ARB) boyası`,B:`Prusya mavisi boyası`,C:`Kongo kırmızısı boyası`,D:`Periyodik Asit Schiff (PAS) boyası`,E:`Von Kossa boyası`},dogru:`A`,aciklama:`Mycobacterium tuberculosis basilinin hücre duvarında mikolik asitten zengin yoğun lipid tabakası bulunur. Bu sayede asit-alkol ile dekolorizasyona direnç gösterir (Asido-Rezistan Basil / ARB). Ziehl-Neelsen (ZN) boyamasında mavi zemin üzerinde parlak kırmızı/pembe çomaklar şeklinde boyanır.`,sik_aciklamalari:{A:`Doğrudur. Tüberküloz basillerini göstermek için Ziehl-Neelsen (ARB) boyası kullanılır.`,B:`Prusya mavisi hemosiderin (demir) boyasıdır.`,C:`Kongo kırmızısı amiloid boyasıdır.`,D:`PAS mantar ve glikojen boyasıdır.`,E:`Von Kossa kalsiyum boyasıdır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q09`,kazanim:13,zorluk:`orta`,soru:`Granülomatöz lezyonların zaman içindeki doğal iyileşme ve sonlanma biçimi incelendiğinde, lezyon odağında en sık gözlenen morfolojik değişiklikler hangisidir?`,secenekler:{A:`Konsantrik fibroblastik proliferasyon, kollajen depolanması (fibrozis/skar) ve ardından distrofik kalsifikasyon gelişimi`,B:`Lezyonun aniden beyin omurilik sıvısına dönüşmesi`,C:`Tüm granülomun pürüzsüz şeffaf kıkırdağa dönüşmesi`,D:`Granülomun hızla malign skuamöz karsinoma dönüşmesi`,E:`Lezyonun eriyip tamamen hava boşluğu haline gelmesi ve akciğerin yok olması`},dogru:`A`,aciklama:`Granülomlar iyileşirken fibroblastlar lezyonu çevreler ve içine doğru kollajen lifleri örerler (fibrozis/fibröz enkapsülasyon). Zamanla granülom tamamen asellüler kollajenöz bir skara dönüşür. Nekrotik artıkların üzerine kalsiyum tuzları çöker (Distrofik Kalsifikasyon). Örneğin primer tüberküloz iyileşirken Ghon odağı kireçlenerek kalsifiye 'Ranke kompleksine' dönüşür.`,sik_aciklamalari:{A:`Doğrudur. Granülomlar tipik olarak fibrozis (skarlaşma) ve distrofik kalsifikasyonla iyileşir.`,B:`BOS oluşumu söz konusu değildir.`,C:`Kıkırdak metaplazisi kural değildir.`,D:`Granülom kendiliğinden karsinom olmaz.`,E:`Her granülom kavitasyon yapmaz; iyileşme fibrozisle olur.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q10`,kazanim:13,zorluk:`zor`,soru:`Romatoid artrit veya ankilozan spondilit nedeniyle anti-TNF biyolojik tedavi (örn. infliksimab) başlanacak bir hastada tedavi öncesi mutlaka Tüberkülin Cilt Testi (PPD) veya IGRA yapılmasının ve latent tüberküloz taramasının en kritik fizyopatolojik gerekçesi nedir?`,secenekler:{A:`TNF'nin böbreklerden atılımını ölçmek`,B:`TNF-alfa granülomların bütünlüğünü ve basillerin hapsedilmesini sağlayan kilit sitokin olduğundan, bloke edildiğinde kalsifiye/fibröz granülomun parçalanması ve latent tüberkülozun masif miliyer yayılımla reaktive olabilmesi`,C:`PPD testinin TNF düzeyini doğrudan düşürmesi`,D:`İlacın tüberküloz basillerini doğrudan besleyen bir protein olması`,E:`Anti-TNF ilaçların sadece tüberkülozlu hastalarda çalışması`},dogru:`B`,aciklama:`TNF-α, epiteloid makrofajların bir arada tutulması, adezyon moleküllerinin ekspresyonu ve granülom mimarisinin devamlılığı için mutlak zorunludur. Hastaya anti-TNF tedavi verildiğinde granülomun fibröz ve hücresel duvarı çöker, hapsedilmiş canlı tüberküloz basilleri serbest kalır ve fulminan dissemine miliyer tüberküloz veya tüberküloz menenjiti reaktivasyonu gelişir.`,sik_aciklamalari:{A:`Böbrek klerensiyle ilgili değildir.`,B:`Doğrudur. TNF granülom bütünlüğünü sağlar; blokajı granülomu dağıtarak latent tüberkülozu reaktive eder.`,C:`PPD tanısal antijendir, tedavi edici regülatör değildir.`,D:`İlaç basili beslemez.`,E:`Tüberkülozu olanlarda anti-TNF kontrendikedir, tedavi etmez.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q11`,kazanim:13,zorluk:`orta`,soru:`Fungal granülomların (örn. Histoplazmozis, Blastomykozis, Koksidioidomikozis) mikroskopik tanısında mantar sporları ve hiflerinin hücre duvarındaki polisakkaritleri siyah/koyu kahverengi boyayarak gösteren özel histokimyasal boya hangisidir?`,secenekler:{A:`Grocott Metenamin Gümüş (GMS) boyası`,B:`Yağ kırmızısı O (Oil Red O)`,C:`Toluidin mavisi`,D:`Sudan III boyası`,E:`Masson trikrom boyası`},dogru:`A`,aciklama:`Granülomatöz dokuda mantar etkenlerinin tespiti için Grocott Metenamin Gümüş (GMS) ve Periyodik Asit Schiff (PAS) boyaları kullanılır. GMS boyasında mantar hücre duvarındaki polisakkaritler gümüş tuzlarını indirger; mantar sporları, tomurcuklanmaları ve hifleri açık yeşil zemin üzerinde koyu siyah-kahverengi renkte son derece net olarak parlar.`,sik_aciklamalari:{A:`Doğrudur. GMS mantar etkenlerini granülomda siyah boyayan altın standart gümüş boyasıdır.`,B:`Oil Red O lipid boyasıdır.`,C:`Toluidin mavisi mast granülleri içindir.`,D:`Sudan III yağ boyasıdır.`,E:`Masson trikrom kollajen lifleri (fibrozis) boyar.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q12`,kazanim:13,zorluk:`zor`,soru:`Sarkoidoz granülomlarında epiteloid histiyositlerin ve Langhans dev hücrelerinin sitoplazmasında izlenebilen; granülomatöz tanıya destek sağlayan 'yıldızsı' inklüzyonlara ne ad verilir?`,secenekler:{A:`Astroid cisimcikleri (ve Schaumann cisimcikleri)`,B:`Negri cisimcikleri`,C:`Mallory-Denk cisimcikleri`,D:`Lewy cisimcikleri`,E:`Councilman cisimcikleri`},dogru:`A`,aciklama:`Sarkoidoz non-kazeifiye granülomlarında dev hücrelerin sitoplazmasında iki tip karakteristik inklüzyon görülebilir: 1) Astroid cisimcikleri: Yıldız şeklinde, kollajenöz/sitoiskelet liflerinden oluşan pembe inklüzyonlar. 2) Schaumann cisimcikleri: Lameller konsantrik kalsiyum ve protein birikimleridir. Negri kuduzda; Mallory alkolik hepatitte; Lewy Parkinson'da; Councilman viral hepatitteki apoptotik cisimciklerdir.`,sik_aciklamalari:{A:`Doğrudur. Astroid ve Schaumann cisimcikleri sarkoidoz granülomlarında dev hücrelerde görülebilen inklüzyonlardır.`,B:`Negri cisimciği kuduz virüsünde nöronlardadır.`,C:`Mallory-Denk hepatosit ara filaman yığılmasıdır.`,D:`Lewy cisimciği alfa-sinüklein agregatıdır.`,E:`Councilman hepatosit apoptozudur.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q13`,kazanim:13,zorluk:`kolay`,soru:`"Granülomatöz enflamasyonun nedenleri" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,E:`IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,C:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,D:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`IFN-γ üretir`},dogru:`A`,aciklama:`Doğru: Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,sik_aciklamalari:{A:`Doğru. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,E:`Yanlış. IgE aracılı reaksiyonlarda (alerjiler) ve helmint parazit enfeksiyonlarında rol oynar; özgül kemoatraktan eotaksindir`,C:`Yanlış. Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt (alerjik)`,D:`Yanlış. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,B:`Yanlış. IFN-γ üretir`},bilgi:[28],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q14`,kazanim:13,zorluk:`orta`,soru:`"Granülomların klinik önemi ve tanısı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,E:`Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,D:`Eozinofil aktivasyonu yapar`,C:`Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,B:`Merkezi nekroz yoktur`},dogru:`A`,aciklama:`Doğru: Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,sik_aciklamalari:{A:`Doğru. Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür; kesin etken tanısı için özel boyalar (asit-fast, mantar boyaları), kültür, moleküler yöntemler ve seroloji gerekir`,E:`Yanlış. Makrofajlardan oluşan duvar, belirgin plazma hücre infiltrasyonu ve hücre konturları tamamen kaybolmadan oluşan merkezi nekroz alanı`,D:`Yanlış. Eozinofil aktivasyonu yapar`,C:`Yanlış. Kronik enflamasyonun özel bir tipi; aktivasyon göstermiş makrofajların (epiteloid hücreler) nodüler kümeler (granülom) oluşturması`,B:`Yanlış. Merkezi nekroz yoktur`},bilgi:[33],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q15`,kazanim:13,zorluk:`orta`,soru:`"Mast hücreleri" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,C:`Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde`,A:`IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,D:`Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`},dogru:`B`,aciklama:`Doğru: Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,sik_aciklamalari:{B:`Doğru. Alerjik reaksiyonların ana hücresi; histamin, lökotrienler ve sitokinler salgılar`,E:`Yanlış. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,C:`Yanlış. Epiteloid hücreler bol, pembe, granüler sitoplazmalı ve belirsiz hücre sınırlı; Langhans tipi dev hücrelerde çekirdekler periferde taç şeklinde`,A:`Yanlış. IL-4 ve IL-13 ile indüklenir; IL-10, TGF-β ve büyüme faktörleri artar, mikrobisidal aktivite sınırlıdır`,D:`Yanlış. Kronik enflamasyonda baskın hücre tipi sıklıkla makrofajdır`},bilgi:[23],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k13-q16`,kazanim:13,zorluk:`zor`,soru:`"Non-klasik hastalıklar" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,E:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,B:`Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,D:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},dogru:`A`,aciklama:`Doğru: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,sik_aciklamalari:{A:`Doğru. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur`,E:`Yanlış. Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,C:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,B:`Yanlış. Kronik inflamatuvar hücre birikimi, parankim tahribi ve bağ dokusu ile yer değiştirme (fibrozis)`,D:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},bilgi:[35],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:14,metin:`Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla ilişkisini açıklamak`,sorular:[{id:`k1-13-q40`,kazanim:14,zorluk:`kolay`,soru:`Uzamış kronik enflamasyonda fibrozisin gelişmesinde en önemli fibrogenik sitokin aşağıdakilerden hangisidir?`,secenekler:{A:`IFN-γ`,B:`TGF-β`,C:`IL-12`,D:`Histamin`,E:`C5a`},dogru:`B`,aciklama:`TGF-β ve diğer fibrogenik sitokinler fibroblastları aktive eder ve kollajen birikimine yol açar.`,sik_aciklamalari:{A:`IFN-γ makrofajları klasik yolla aktive eder.`,B:`Doğru. TGF-β ve diğer fibrogenik sitokinler fibroblastları aktive eder ve kollajen birikimine yol açar.`,C:`IL-12 Th1 yanıtını uyarır.`,D:`Histamin vazoaktif amindir.`,E:`C5a kemotaktik kompleman ürünüdür.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-13-q41`,kazanim:14,zorluk:`orta`,soru:`Kronik enflamasyona bağlı fibrozisin klinik sonuçları arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Karaciğer sirozu`,B:`Akciğer fibrozisi`,C:`Böbrek yetmezliği`,D:`Konstriktif perikardit`,E:`Akut seröz efüzyonun iz bırakmadan çözülmesi`},dogru:`E`,aciklama:`Uzamış enflamasyonda fibrozis siroz, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardite yol açabilir.`,sik_aciklamalari:{A:`Fibrozisin klinik sonucudur.`,B:`Fibrozisin klinik sonucudur.`,C:`Fibrozisin klinik sonucudur.`,D:`Fibrozisin klinik sonucudur.`,E:`Yer almaz (aranan cevap); bu akut enflamasyonun tam rezolüsyonudur.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-13-q42`,kazanim:14,zorluk:`zor`,soru:`Klasik enflamatuvar hastalık olarak görülmeyen ancak seyrinde kronik, düşük dereceli enflamasyonun anlamlı rol oynadığı hastalıklar aşağıdakilerin hangisinde birlikte verilmiştir?`,secenekler:{A:`Ateroskleroz, tip 2 diyabet/metabolik sendrom, Alzheimer hastalığı`,B:`Akut apandisit, lobar pnömoni, sellülit`,C:`Kalıtsal anjiyoödem, PNH, HÜS`,D:`Trizomi 21, Turner sendromu, Klinefelter sendromu`,E:`Kırık, yanık, kesik`},dogru:`A`,aciklama:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik düşük dereceli enflamasyon hastalık seyrine katkıda bulunur.`,sik_aciklamalari:{A:`Doğru. Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik düşük dereceli enflamasyon hastalık seyrine katkıda bulunur.`,B:`Bunlar klasik akut enflamatuvar hastalıklardır.`,C:`Bunlar kompleman düzenleyici protein eksiklikleriyle ilişkilidir.`,D:`Bunlar kromozomal anomalilerdir.`,E:`Bunlar fiziksel yaralanmalardır.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q04`,kazanim:14,zorluk:`orta`,soru:`68 yaşındaki bir hasta tarama sırasında saptanan ve ileri incelemeye alınan bir kişide hekime başvuruyor. Değerlendirmede "Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur" bulgusuna ulaşılıyor. Bu dersin (Tıbbi Patoloji – Kronik ve Granülomatöz Enflamasyon) kapsamındaki "Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla ilişkisini açıklamak" kazanımı çerçevesinde aşağıdaki yargılardan hangisi doğrudur?`,secenekler:{A:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur Bu nedenle Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardit gelişebilir`,B:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen… ilkesinin tam tersi geçerlidir ve Bu enflamasyon hastalık seyrine anlamlı katkı sunar gözlenmez`,C:`Bu tablodan sorumlu temel mekanizma Non-klasik hastalıklar olup "Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla…" ile ilişkisizdir`,D:`Bulgular "Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla ilişkisini…" kapsamında tesadüfidir ve klinik kararı değiştirmez`,E:`Bu durum yalnızca laboratuvar artefaktına bağlıdır ve "Kronik enflamasyon ve fibrozis" ile açıklanamaz`},dogru:`A`,aciklama:`Robbins/Harrison mantığıyla: Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur Doğrudan sonucu "Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardit gelişebilir" doğurur; diğer seçenekler bu bilgi paketiyle çelişir.`,sik_aciklamalari:{A:`Doğru; Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi…`,B:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,C:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`},bilgi:[34,35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q05`,kazanim:14,zorluk:`zor`,soru:`Farklı bir hasta komplikasyon gelişen ve mekanizması sorgulanan başka bir hastada ele alınıyor. Öyküde "Non-klasik hastalıklar" vurgulanıyor ve hekim "Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla ilişkisini açıklamak" kazanımındaki "Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur" mekanizmasını sorguluyor. Bu hastada beklenen/hatalı olan yorumu bulmak için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bu enflamasyon hastalık seyrine anlamlı katkı sunar hiçbir koşulda gözlenmez ve Kronik enflamasyon ve fibrozis tek belirleyicidir`,B:`Bu enflamasyon hastalık seyrine anlamlı katkı sunar Çünkü Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon…`,C:`Bu süreçte "Kronik enflamasyon ve fibrozis" tümüyle etkisizdir ve yerini tamamen farklı bir yolak alır`,D:`Benzer tabloların tamamı aynı nedene bağlıdır; "Non-klasik hastalıklar" ayırıcı tanıda gereksizdir`,E:`Bu olguda izlem gerekmez; "Kronik enflamasyonun fibrozis ve non-klasik hastalıklarla ilişkisini…" yalnızca teorik bir bilgidir`},dogru:`B`,aciklama:`Guyton/Robbins bütünlüğünde: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur sonucu "Bu enflamasyon hastalık seyrine anlamlı katkı sunar" verir; çeldiriciler ders paketindeki bu nedenselliği bozar.`,sik_aciklamalari:{A:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,B:`Doğru; Bu enflamasyon hastalık seyrine anlamlı katkı sunar Çünkü Ateroskleroz, tip 2 diyabet/metabolik sendrom ve…`,C:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,D:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`,E:`Yanlış; ders paketindeki "Kronik enflamasyon ve fibrozis" bilgisiyle çelişir.`},bilgi:[34,35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q06`,kazanim:14,zorluk:`orta`,soru:`Non-klasik hastalıklar: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur. Buna göre beklenen sonuç aşağıdakilerden hangisidir?`,secenekler:{A:`Bu dengenin bozulması kronik enflamasyon ve fibroziste rol oynar`,B:`Bu enflamasyon hastalık seyrine anlamlı katkı sunar`,C:`Granüllerindeki major basic protein parazitler için toksiktir`,D:`Nedenler sınırlı sayıda hastalık grubunu düşündürür`,E:`Akut enflamasyonu izleyebilir veya sinsi başlangıçlı primer kronik olabilir`},dogru:`B`,aciklama:`Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında kronik, düşük dereceli enflamasyon bulunur. Bu enflamasyon hastalık seyrine anlamlı katkı sunar. Bu ilişki Tıbbi Patoloji fizyolojisinin temel düzeneklerinden biridir: Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer doğrudan Bu enflamasyon hastalık seyrine anlamlı katkı sunar doğurur. Diğer seçeneklerdeki süreçler farklı yolaklara aittir ve bu tabloda beklenen sonucu vermez. Bu nedenle doğru yanıt B seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade M1 ve M2 dengesi sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,B:`Doğru; Bu enflamasyon hastalık seyrine anlamlı katkı sunar çünkü Ateroskleroz, tip 2 diyabet/metabolik sendrom ve Alzheimer hastalığında düzeneği bu sonucu üretir.`,C:`Yanlış; bu ifade Eozinofiller sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,D:`Yanlış; bu ifade Granülomatöz enflamasyonun nedenleri sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`,E:`Yanlış; bu ifade Kronik enflamasyonun tanımı sürecine ait bir özelliktir ve non-klasik hastalıklar düzeneğini tanımlamaz.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q07`,kazanim:14,zorluk:`orta`,soru:`Aynı kazanımın farklı bir yönü: Kronik enflamasyon ve fibrozis mekanizması açısından aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`IL-17 ve diğer sitokinleri salgılar`,B:`Merkezi nekroz alanı`,C:`Granülomatöz enflamasyon sınırlı hastalık grubunu düşündürür`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar`,E:`Otoantijenlere karşı süregen yanıt (otoimmün) veya zararsız antijenlere aşırı yanıt`},dogru:`D`,aciklama:`Tıbbi Patoloji düzeneğinde Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler bilinir. Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif perikardit gelişebilir. Mekanizma bu sırayla işlediği için beklenen sonuç Karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve olur; çeldiricilerdeki olaylar farklı basamaklara aittir ve aynı sonucu üretmez. Bu nedenle doğru yanıt D seçeneğidir.`,sik_aciklamalari:{A:`Yanlış; bu ifade Th17 hücreleri sürecine ait bir özelliktir ve kronik enflamasyon ve fibrozis düzeneğini tanımlamaz.`,B:`Yanlış; bu ifade Kazeöz (kazeifiye) granülom sürecine ait bir özelliktir ve kronik enflamasyon ve fibrozis düzeneğini tanımlamaz.`,C:`Yanlış; bu ifade Granülomların klinik önemi ve tanısı sürecine ait bir özelliktir ve kronik enflamasyon ve fibrozis düzeneğini tanımlamaz.`,D:`Doğru; Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar. Bu mekanizma karaciğer sirozu, akciğer fibrozisi, böbrek yetmezliği ve konstriktif sonucunu doğurur.`,E:`Yanlış; bu ifade Aşırı duyarlılık (immün) hastalıkları sürecine ait bir özelliktir ve kronik enflamasyon ve fibrozis düzeneğini tanımlamaz.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q08`,kazanim:14,zorluk:`orta`,soru:`Kronik parankimal organ hasarlarında (örneğin Karaciğer Sirozu veya İdiyopatik Pulmoner Fibrozis) fonksiyonel dokunun yerini alan ve fibrozisi yöneten EN GÜÇLÜ profibrotik sitokin aşağıdakilerden hangisidir?`,secenekler:{A:`Transforme Edici Büyüme Faktörü-beta (TGF-β)`,B:`İnterlökin-2`,C:`Histamin`,D:`Prostasiklin`,E:`Bradikinin`},dogru:`A`,aciklama:`TGF-β (Transforming Growth Factor-beta), memeli dokularındaki en güçlü profibrotik sitokindir. Kronik enflamasyonda aktive M2 makrofajlar ve trombositler tarafından üretilir. Fibroblastların kemotaksisini, proliferasyonunu, miyofibroblasta dönüşümünü ve aşırı Tip I ve Tip III kollajen ile fibronektin sentezini uyarır; eşzamanlı olarak kollajenazları (MMP) inhibe edip doku inhibitörlerini (TIMP) artırarak matriks yıkımını durdurur.`,sik_aciklamalari:{A:`Doğrudur. TGF-β organ fibrozisinin ve sirozun anahtar profibrotik mediyatörüdür.`,B:`IL-2 T lenfosit büyüme faktörüdür.`,C:`Histamin vazoaktif amindir, profibrotik değildir.`,D:`Prostasiklin vazodilatatördür.`,E:`Bradikinin akut ağrı ve permeabilite faktörüdür.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q09`,kazanim:14,zorluk:`zor`,soru:`Uzun yıllar devam eden kronik enflamatuar hastalıkların (örn. Ülseratif Kolit, Kronik Hepatit B/C enfeksiyonu, Barrett Özofagusu) zemininde KANSER (malignite) gelişme riskinin belirgin artmasının moleküler mekanizmaları arasında aşağıdakilerden hangisi YER ALMAZ?`,secenekler:{A:`Aktive makrofaj ve nötrofillerin ürettiği ROS ve RNS'nin (reaktif radikaller) epitel hücresi DNA'sında mutasyonlara yol açması`,B:`Kronik hücre ölümünü telafi etmek için dokuda sürekli kompansatuar epitel proliferasyonu olması ve mutasyonların fikse olması`,C:`Enflamatuar sitokinlerin (TNF, IL-6) NF-κB ve STAT3 yolaklarını sürekli aktive ederek apoptozu engellemesi ve hücre sağkalımını artırması`,D:`Enflamasyon odağındaki VEGF ve FGF'nin tümör için hazır anjiyojenik zemin sağlaması`,E:`Kronik enflamasyonun hücrelerde telomer uzunluğunu aniden 10 katına çıkararak bölünmeyi tamamen durdurması`},dogru:`E`,aciklama:`Kronik enflamasyon-kanser ilişkisi günümüzde iyi aydınlatılmıştır: 1) ROS/RNS ile DNA mutasyonları, 2) Sürekli rejenerasyon ve mitozla mutasyonların kalıcılaşması, 3) NF-κB/STAT3 ile anti-apoptotik genlerin ekspresyonu, 4) Anjiyogenez ve matriks proteazlarıyla invazyon kolaylığı. Telomerleri uzatıp bölünmeyi durdurmaz; aksine replikatif stresle telomerler kısalır, kriz döneminde telomeraz reaktivasyonuyla hücre ölümsüzleşir.`,sik_aciklamalari:{A:`ROS/RNS DNA hasarı ve mutasyon yapar.`,B:`Sürekli proliferasyon mutasyon riskini ve tümörijenezi artırır.`,C:`NF-κB ve STAT3 kanser hücrelerinin apoptozdan kaçmasını sağlar.`,D:`Anjiyogenez tümör büyümesine zemin hazırlar.`,E:`Doğrudur. Bölünmeyi durdurmaz; kronik bölünme kansere yol açar.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q10`,kazanim:14,zorluk:`orta`,soru:`Kronik enflamatuar hastalıklarda (Romatoid Artrit, Tüberküloz, Bronşiektazi vb.) yıllar içinde serum amiloid A (SAA) proteininin aşırı üretiminin ve dokularda çözünmez fibriller şeklinde depolanmasının yol açtığı sistemik komplikasyon hangisidir?`,secenekler:{A:`Sekonder Reaktif Sistemik Amiloidoz (AA Amiloidozu)`,B:`Primer AL Amiloidozu`,C:`Senil Sistemik Amiloidoz`,D:`Dializ ilişkili beta-2 mikroglobulin birikimi`,E:`Kalsifilaksi`},dogru:`A`,aciklama:`Sekonder (Reaktif) Sistemik Amiloidoz (AA amiloidozu), uzun süren kronik enflamatuar hastalıklara sekonder gelişir. Karaciğer IL-6 ve IL-1 uyarısıyla sürekli SAA üretir. SAA proteolitik olarak AA proteinine parçalanır ve böbreklerde, karaciğerde ve dalakta çözünmez beta-kırmalı tabakalar (amiloid fibrilleri) şeklinde çöker. En sık nefrotik sendrom ve üremiye neden olur.`,sik_aciklamalari:{A:`Doğrudur. Kronik enflamasyonda SAA kaynaklı AA amiloidozu gelişir.`,B:`AL amiloidozu plazma hücresi diskrazilerinde immünoglobulin hafif zincirlerinden kaynaklanır.`,C:`Senil amiloidoz transtiretine bağlıdır.`,D:`Diyaliz amiloidozu beta-2 mikroglobuline bağlıdır.`,E:`Kalsifilaksi vasküler kalsifikasyondur.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q11`,kazanim:14,zorluk:`zor`,soru:`Aterosklerozun patogenezinde koroner damar lümeninde aterom plağının yırtılmasına ve akut miyokard enfarktüsüne yol açan kronik enflamatuar hücre ve enzim hangisidir?`,secenekler:{A:`Aktive makrofajların salgıladığı Matriks Metalloproteinazların (MMP'ler / kollajenazlar) fibröz başlığı eritip zayıflatması`,B:`Eritrositlerin damar duvarını sindirmesi`,C:`Kupffer hücrelerinin koroner artere göçmesi`,D:`Mast hücrelerinin kalsiyumu eritmesi`,E:`Kondrositlerin fibröz başlığı kemikleştirmesi`},dogru:`A`,aciklama:`Ateroskleroz bir kronik enflamatuar arter hastalığıdır. Aterom plağının üzerinde lipid çekirdeği lümenden ayıran bir kollajen fibröz başlık bulunur. Plaktaki aktive T lenfositleri (IFN-γ salarak düz kasların kollajen sentezini baskılar) ve aktive makrofajlar salgıladıkları MMP'ler (kollajenaz ve jelatinazlar) ile bu koruyucu fibröz başlığı sindirirler. İncelen başlık yırtılır; açığa çıkan trombogenik lipidler akut koroner tromboza ve miyokard enfarktüsüne yol açar.`,sik_aciklamalari:{A:`Doğrudur. Makrofaj kökenli MMP'ler plağın fibröz başlığını incelterek rüptüre ve enfarktüse yol açar.`,B:`Eritrositler başlığı sindirmez.`,C:`Kupffer karaciğerdedir.`,D:`Mast kalsiyumu eritmez.`,E:`Kondrositler arter başlığında primer hücre değildir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q12`,kazanim:14,zorluk:`orta`,soru:`Metabolik kronik enflamasyonun (meta-enflamasyon) obezite ve Tip 2 diyabette insülin direncine yol açmasında yağ dokusunu infiltre eden hangi hücre grubu ve salgıladığı sitokin başroldedir?`,secenekler:{A:`Pro-enflamatuar M1 polarize adipoz doku makrofajları ve salgıladıkları TNF-α / IL-1β`,B:`Saf B lenfositler ve salgıladıkları IgA antikorları`,C:`Kemik iliği eritroblastları`,D:`Deri melanositleri`,E:`Tiroit folikül hücreleri`},dogru:`A`,aciklama:`Obezitede hipertrofik adipositler hipoksi ve serbest yağ asitleri nedeniyle strese girer ve kemokinler salgılar. Yağ dokusuna göç eden monositler M1 makrofajlara dönüşür ('taç benzeri yapılar' oluştururlar). Bu makrofajların salgıladığı TNF-α ve IL-1β, adipositlerde ve kas hücrelerinde insülin reseptör substratlarını (IRS-1) fosforilleyerek insülin sinyalini engeller ve sistemik insülin direncini başlatır.`,sik_aciklamalari:{A:`Doğrudur. M1 makrofajlar ve salgıladıkları TNF-α / IL-1β obezitede insülin direncinin temel patojenik faktörüdür.`,B:`İnsülin direncini IgA yapmaz.`,C:`Eritroblastlar kemik iliğindedir.`,D:`Melanositler melanin üretir.`,E:`Tiroit folikül hücreleri tiroid hormonu yapar.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q13`,kazanim:14,zorluk:`kolay`,soru:`Aşağıdakilerden "Kronik enflamasyonda baskın hücreler" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,A:`Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,C:`IL-17 ve diğer sitokinleri salgılar`,D:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},dogru:`B`,aciklama:`Doğru: Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,sik_aciklamalari:{B:`Doğru. Mononükleer hücreler: makrofajlar, lenfositler, plazma hücreleri`,A:`Yanlış. Haftalar-aylar süren; enflamasyon, doku hasarı ve onarımın (anjiyogenez, fibrozis) eş zamanlı sürdüğü yanıt`,C:`Yanlış. IL-17 ve diğer sitokinleri salgılar`,D:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,E:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},bilgi:[3],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q14`,kazanim:14,zorluk:`orta`,soru:`"Uzun süreli toksik maruziyet" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,D:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,C:`Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},dogru:`E`,aciklama:`Doğru: Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,sik_aciklamalari:{E:`Doğru. Eksojen silika (silikozis), asbest (akciğer fibrozisi ve mezotelyoma); endojen kolesterol/lipid birikimi (ateroskleroz)`,D:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,C:`Yanlış. Uzamış enflamasyonda TGF-β ve diğer fibrogenik sitokinler artar; fibroblast aktivasyonu ve kollajen birikimi olur`,A:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},bilgi:[7],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q15`,kazanim:14,zorluk:`orta`,soru:`"Yerleşik makrofaj isimleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,D:`IFN-γ üretir`,A:`Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,B:`Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},dogru:`E`,aciklama:`Doğru: Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,sik_aciklamalari:{E:`Doğru. Karaciğerde Kupffer hücreleri, dalak/lenf düğümünde sinüs histiyositleri, beyinde mikroglia, akciğerde alveoler makrofajlar`,C:`Yanlış. Fagositoz edilemeyecek kadar büyük veya çözünmeyen materyallere karşı (talk, dikiş iplikleri, cam, metal)`,D:`Yanlış. IFN-γ üretir`,A:`Yanlış. Enfeksiyöz (M. tuberculosis, Treponema pallidum, bazı mantarlar, parazitler), immün aracılı (sarkoidoz, Crohn hastalığı) ve yabancı cisim (dikiş, talk, silika, partiküller)`,B:`Yanlış. Makrofaj antijen sunar ve IL-12 salgılar, T hücresini aktive eder; T hücresi IFN-γ ile makrofajı yeniden aktive eder`},bilgi:[11],benzer_cikmis:[]},{id:`k1-13-kronik-ve-granulomatoz-enflamasyon-k14-q16`,kazanim:14,zorluk:`zor`,soru:`"Non-kazeöz granülom" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Merkezi nekroz yoktur`,E:`Nötrofiller ve ödem`,A:`Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,C:`Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},dogru:`D`,aciklama:`Doğru: Merkezi nekroz yoktur`,sik_aciklamalari:{D:`Doğru. Merkezi nekroz yoktur`,E:`Yanlış. Nötrofiller ve ödem`,A:`Yanlış. Mononükleer hücre infiltrasyonu, kalıcı etkenin neden olduğu doku yıkımı ve iyileşme girişimleri`,B:`Yanlış. Fagositoz; inflamasyon mediyatörleri (TNF, IL-1, kemokinler, eikozanoidler) salgısı; onarım ve fibrozis (TGF-β, PDGF, FGF); antijen sunumu`,C:`Yanlış. Mikobakteriler (M. tuberculosis), bazı virüsler, mantarlar ve parazitler tarafından oluşturulan süregen enfeksiyonlar`},bilgi:[27],benzer_cikmis:[]}],ilgili_cikmis:[]}]};export{e as default};